import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { supabase } from '../../lib/supabase';
import Badge from './Badge';
import Skeleton from './Skeleton';
import EmptyState from './EmptyState';
import { fmtDate } from '../../utils/format';
import { openPopup } from '../../utils/openPopup';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { campaignLabel } from '../../utils/campaignLabel';

/**
 * components/shared/CampaignReference.js. Read-only campaign + deliverables
 * reconciliation block.
 *
 * Collapsible panel mounted above the Invoice/Payout tabs in the Payments detail
 * panel so an invoice/payout reconciles against what was contracted and
 * delivered without navigating to Campaigns. Self-fetches campaigns +
 * campaign_deliverables on mount. Shows identity, reconciliation dates, and
 * per-deliverable rows. Carries NO completion%/view stats (irrelevant to money).
 *
 * Used by: PaymentsPage PaymentDetailPanel. Reuse for any read-only deliverable
 * surface; never copy its renderer.
 *
 * @gotcha purely read-only; nothing here mutates. Deliverable editing stays in
 *         the Campaigns panel.
 * @gotcha the financial form must never wait on this fetch, and a failure here
 *         must not break it (independent useEffect, own loadError state).
 */

/**
 * @param {object} props
 * @param {string} props.campaignId - drives the self-fetch
 * @param {object} props.row - the payment row supplying identity (brand/campaign name, status, start date)
 * @param {boolean} [props.isMobile]
 */
export default function CampaignReference({ campaignId, row, isMobile = false }) {
  const { options: statusOptions, loading: vocabLoading } = useStatusOptions();
  const postedId = useMemo(
    () => (statusOptions.deliverable || []).find(o => o.value === 'Posted')?.id,
    [statusOptions]
  );
  // An empty deliverable group walks through StatusVocabularyGate, which branches on a REFUSED
  // read only, and then `d.draft_status_id === undefined` is false for every row. The summary
  // said "0 posted" as fact on work that is posted.
  const postsUnknown = !vocabLoading && postedId === undefined;

  const [open, setOpen]           = useState(false);
  const [meta, setMeta]           = useState(null);  // { deal_signed_date, campaign_end_date }
  const [delivs, setDelivs]       = useState(null);
  const [loading, setLoading]     = useState(true);
  const [loadError, setLoadError] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setLoadError(false);
    const [campRes, delivRes] = await Promise.all([
      supabase
        .from('campaigns')
        .select('deal_signed_date, campaign_end_date')
        .eq('id', campaignId)
        .maybeSingle(),
      supabase
        .from('campaign_deliverables')
        .select('id, quantity, draft_status_id, post_url, post_caption, contracted_post_date, actual_post_date, platform:platforms(name), deliverable_type:deliverable_types(name)')
        .eq('campaign_id', campaignId)
        .order('contracted_post_date', { nullsFirst: false }),
    ]);
    if (campRes.error || delivRes.error) {
      setLoadError(true);
      setMeta(null);
      setDelivs([]);
    } else {
      // Cleared on success, or a Try again that WORKED still shows the failure and keeps the
      // deliverable list hidden behind `!loadError`.
      setLoadError(false);
      setMeta(campRes.data || {});
      setDelivs(delivRes.data || []);
    }
    setLoading(false);
  }, [campaignId]);

  // Fetch on mount, independent of the invoice/payout fetch. The financial
  // form must never wait on this, and a failure here must not break it.
  useEffect(() => { load(); }, [load]);

  const totalSlots  = (delivs || []).reduce((s, d) => s + (d.quantity || 1), 0);
  const postedSlots = (delivs || [])
    .filter(d => d.draft_status_id === postedId)
    .reduce((s, d) => s + (d.quantity || 1), 0);

  const brand = row?.brand_name || campaignLabel(row) || 'Campaign';
  const summary = loading || vocabLoading
    ? 'Loading…'
    : loadError
      ? 'Campaign details unavailable'
      : [
          brand,
          totalSlots > 0 ? `${totalSlots} post${totalSlots !== 1 ? 's' : ''}` : 'No deliverables',
          // The slot count is a row count and stays true. Only the posted half depends on a
          // status id, so only the posted half goes quiet.
          totalSlots > 0 ? (postsUnknown ? 'posted count unavailable' : `${postedSlots} posted`) : null,
        ].filter(Boolean).join(' · ');

  const dateVal = d => (d ? fmtDate(d) : '—');

  return (
    <section className={`cref${isMobile ? ' cref-mobile' : ''}`}>
      <button
        type="button"
        className="cref-toggle"
        aria-expanded={open}
        onClick={() => setOpen(o => !o)}
      >
        <span className="cref-caret" data-open={open} aria-hidden="true">&#9656;</span>
        <span className="cref-title">Campaign &amp; deliverables</span>
        <span className="cref-summary">{summary}</span>
      </button>

      <div className="cref-panel" data-open={open}>
        <div className="cref-panel-inner">
          <div className="cref-body">
            {/* Identity */}
            <div className="cref-id">
              <div className="cref-id-main">
                <div className="cref-brand">{row?.brand_name || '—'}</div>
                {campaignLabel(row) && <div className="cref-campaign">{campaignLabel(row)}</div>}
              </div>
              {row?.status_id != null && <Badge group="campaign" statusId={row.status_id} status={row.status} />}
            </div>

            {/* Reconciliation dates */}
            <div className="cref-dates">
              <div className="cref-date">
                <div className="cref-date-label">Deal signed</div>
                <div className="cref-date-val">{loading ? '—' : dateVal(meta?.deal_signed_date)}</div>
              </div>
              <div className="cref-date">
                <div className="cref-date-label">Campaign start</div>
                <div className="cref-date-val">{dateVal(row?.campaign_start_date)}</div>
              </div>
              <div className="cref-date">
                <div className="cref-date-label">Campaign end</div>
                <div className="cref-date-val">{loading ? '—' : dateVal(meta?.campaign_end_date)}</div>
              </div>
            </div>

            {/* Deliverables */}
            {loading && (
              <Skeleton label="Loading deliverables" height={11}
                        widths={['72%', '58%', '64%']} />
            )}

            {!loading && loadError && (
              <div className="cref-note">
                Couldn&apos;t load campaign details.{' '}
                <button type="button" className="cref-postlink" onClick={load}>Try again</button>
              </div>
            )}

            {!loading && !loadError && delivs.length === 0 && (
              <EmptyState variant="note" text="No deliverables on this campaign." />
            )}

            {!loading && !loadError && delivs.length > 0 && (
              <div className="cref-list">
                <div className="cref-list-label">Deliverables</div>
                {delivs.map(d => (
                  <div key={d.id} className="cref-deliv">
                    <div className="cref-deliv-head">
                      <span className="cref-deliv-platform">
                        {d.platform?.name || 'Unknown platform'}
                        {d.deliverable_type?.name && (
                          <span className="cref-deliv-type"> &middot; {d.deliverable_type.name}</span>
                        )}
                        {d.quantity > 1 && <span className="cref-deliv-type"> &times;{d.quantity}</span>}
                      </span>
                      <Badge group="deliverable" statusId={d.draft_status_id} />
                    </div>

                    {d.post_caption && (
                      <div className="cref-caption" title={d.post_caption}>{d.post_caption}</div>
                    )}

                    <div className="cref-deliv-meta">
                      <span>
                        Due <span className="cref-deliv-strong">{dateVal(d.contracted_post_date)}</span>
                        {d.actual_post_date && (
                          <> &middot; posted <span className="cref-deliv-strong">{dateVal(d.actual_post_date)}</span></>
                        )}
                      </span>
                      {d.post_url && (
                        <button
                          type="button"
                          className="cref-postlink"
                          onClick={() => openPopup(d.post_url)}
                        >
                          Open post <span aria-hidden="true">&#8599;</span>
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}
