/**
 * Per-column dropdown filter button (Platforms / Payment header filters).
 *
 * @gotcha defined at module scope on purpose. Inlining it inside CampaignsPage
 *         makes React treat it as a new component type on every parent re-render,
 *         unmounting/remounting the open dropdown.
 */
function ColFilterBtn({ col, options, label, colFilters, openColFilter, setColFilters, setOpenColFilter }) {
  const active = !!colFilters[col];
  // Platforms are names, where what a reader sees IS what is compared; Payment is a row list
  // whose label and value differ. @see utils/paidFilter.js
  const rows = options.map(o => (typeof o === 'string' ? { value: o, label: o } : o));
  return (
    <div style={{ position: 'relative', display: 'inline-block' }}>
      <button
        className="btn btn-ghost btn-sm"
        style={{ fontSize: 10, padding: '1px 4px', marginLeft: 4, color: active ? 'var(--blue)' : 'var(--muted)', border: active ? '1px solid var(--blue)' : 'none' }}
        aria-label={`Filter ${label}`}
        onClick={e => { e.stopPropagation(); setOpenColFilter(openColFilter === col ? null : col); }}
      >▾</button>
      {openColFilter === col && (
        <div onClick={e => e.stopPropagation()} style={{ position: 'absolute', top: '100%', left: 0, zIndex: 200, background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 6, minWidth: 140, padding: 4, boxShadow: 'var(--shadow-md)' }}>
          <button type="button" className="col-filter-opt" aria-pressed={!active}
            style={{ padding: '5px 10px', fontSize: 12, color: active ? 'var(--white)' : 'var(--blue)' }}
            onClick={() => { setColFilters(f => ({ ...f, [col]: '' })); setOpenColFilter(null); }}>
            All {label}
          </button>
          {rows.map(o => (
            <button type="button" key={o.value} className="col-filter-opt" aria-pressed={colFilters[col] === o.value}
              style={{ padding: '5px 10px', fontSize: 12, color: colFilters[col] === o.value ? 'var(--blue)' : 'var(--white)', background: colFilters[col] === o.value ? 'rgba(255,92,0,0.08)' : 'transparent' }}
              onClick={() => { setColFilters(f => ({ ...f, [col]: o.value })); setOpenColFilter(null); }}>
              {o.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Campaigns page: filterable table + slide-in CampaignDetail panel.
 *
 * @param {object} props
 * @param {boolean} props.isAdmin - admin sees all campaigns + edit affordances; creator is scoped + read-only on money/brief
 * @param {string} [props.profileId] - when set, scopes the query to one creator's campaigns
 * @param {string} [props.pendingCampaignId] - auto-open this campaign on mount (overview deep-link)
 * @param {string} [props.pendingCampaignTab] - open it on this detail tab instead of Deliverables.
 *        Used by a System Health record whose fix is a control on one particular tab.
 * @param {string} [props.pendingDeliverableId] - highlight + scroll to this deliverable inside the opened campaign
 * @param {function} [props.onCampaignStatusChanged] - parent refresh hook fired after any campaign mutation
 * @gotcha status arrays/labels are derived from StatusOptionsContext via id->value maps
 *         (campMap/invMap), never hardcoded; the maps are in the useMemo dep arrays so
 *         displayCampaigns and filter options recompute on a status_options refresh.
 */
export default function CampaignsPage({ isAdmin, profileId, pendingCampaignId, pendingCampaignTab, pendingDeliverableId, onCampaignStatusChanged }) {
  const { options: statusOptions } = useStatusOptions();
  // Stable memoized values derived from statusOptions (recomputed only when statusOptions changes).
  // Using id→value maps (O(1) lookup) instead of per-call find (O(n)).
  // These are in the dependency arrays of the useMemo blocks below so that
  // displayCampaigns and filter options update correctly if statusOptions refreshes.
  // Rows, not values: `value` is the filter key and `label` is what the reader sees. @see utils/statusRow.js
  const CAMPAIGN_STATUSES    = useMemo(() => [ALL_CHOICE, ...(statusOptions.campaign || [])], [statusOptions.campaign]);
  const campMap       = useMemo(() => Object.fromEntries((statusOptions.campaign || []).map(o => [o.id, o.value])), [statusOptions.campaign]);
  const invMap        = useMemo(() => Object.fromEntries((statusOptions.payment  || []).map(o => [o.id, o.value])), [statusOptions.payment]);
  const campText      = useCallback(id => campMap[id] || null, [campMap]);
  const invText       = useCallback(id => invMap[id]  || null, [invMap]);
  const postedDelivId = useMemo(() => (statusOptions.deliverable || []).find(o => o.value === 'Posted')?.id, [statusOptions.deliverable]);
  // With no Posted id every row compared false and read "0/N" as fact. A count that cannot
  // be taken shows `?`, since the slot total is a row count and stays true. P200.
  const postedTitle = postedDelivId ? undefined : 'The status list has not loaded, so how many are posted cannot be counted.';

  const [campaigns, setCampaigns]             = useState([]);
  // Holds the RAW error: ReadError humanizes, and humanizing twice loses the reason. BOTH
  // branches must bind it. The admin branch reads `cRes.data` fifteen lines below the creator
  // branch that binds; unbound, a refused read there prints "No campaigns found".
  const [loadErr, setLoadErr]                 = useState(null);
  const [agencies, setAgencies]               = useState([]);
  const { creators } = useCreators(isAdmin);
  const [platforms, setPlatforms]             = useState([]);
  const [deliverableTypes, setDeliverableTypes] = useState([]);
  /* The three admin lookups only fill PICKERS, so each reports inside the form that uses it
   * rather than blanking a list that already guards itself.
   *
   * @gotcha an empty list is not "no agencies": a `<select>` whose value matches no option
   *         displays the FIRST one, so on a campaign that HAS an agency the control reads
   *         "No agency" over a live `agency_id` and the single choice left writes null over
   *         it. Same for the deliverable platform and type. Raw errors, because ReadError
   *         humanizes. @see .claude/rules/hub-ui.md
   */
  const [lookupErrors, setLookupErrors] = useState({ agencies: null, platforms: null, deliverableTypes: null });
  // Shape B of the same defect: this loader raised nothing, so a save that takes two seconds
  // showed the pre-save numbers for two seconds and nothing said so. @see hooks/useLoadState.js
  const { loading, refreshing, begin, end } = useLoadState();
  const [filter, setFilter]                   = useState('all');
  const [creatorFilter, setCreatorFilter]     = useState('all');
  const [monthFilter, setMonthFilter]         = useState('all');
  const [selectedCampaign, setSelectedCampaign] = useState(null);
  const [ytdlpMap, setYtdlpMap]               = useState({});
  const openCampaignIdRef                     = useRef(null);
  const [showModal, setShowModal]             = useState(false);
  const [detailTab, setDetailTab]             = useState('deliverables');
  const [highlightDeliverableId, setHighlightDeliverableId] = useState(null);
  const { sortBy: sortCol, sortDir, toggle: toggleSort } = useSortState('created_at', 'desc');
  const [agencyFilter, setAgencyFilter]       = useState('');
  const [colFilters, setColFilters]           = useState({ platform: '', payment: '' });
  const [openColFilter, setOpenColFilter]     = useState(null);
  // Every control `displayCampaigns` reads, not the three that were easiest to name: the
  // agency chip and the two column filters hid rows and left the empty state saying "Create
  // a campaign to get started" with no way back. @see .claude/rules/hub-ui.md
  const campaignFiltersDirty = filter !== 'all' || creatorFilter !== 'all' || monthFilter !== 'all'
    || !!agencyFilter || !!colFilters.platform || !!colFilters.payment;
  function clearCampaignFilters() {
    setFilter('all'); setCreatorFilter('all'); setMonthFilter('all');
    setAgencyFilter(''); setColFilters({ platform: '', payment: '' });
  }

  useEffect(() => { fetchAll(); }, []);

  // Auto-open a campaign (and optionally highlight a deliverable) from overview navigation
  useEffect(() => {
    if (!pendingCampaignId || campaigns.length === 0) return;
    const target = campaigns.find(c => c.id === pendingCampaignId);
    if (target) {
      openCampaignIdRef.current = target.id;
      setSelectedCampaign(target);
      // An unrecognised tab name falls back to Deliverables rather than selecting nothing in
      // the strip and rendering an empty body. @see CAMPAIGN_DETAIL_TABS
      setDetailTab(CAMPAIGN_DETAIL_TABS.includes(pendingCampaignTab) ? pendingCampaignTab : 'deliverables');
      if (pendingDeliverableId) setHighlightDeliverableId(pendingDeliverableId);
      enrichWithStats(target.id);
    }
  }, [pendingCampaignId, pendingCampaignTab, pendingDeliverableId, campaigns]);

  /**
   * The three admin picker lookups, apart from the list so a retry re-runs them and not the
   * campaign read and its invoice merge. Never throws: each read reports for itself through
   * `lookupErrors`, and a refusal empties its own array so no stale option survives it.
   */
  async function loadLookups() {
    const [aRes, pRes, dtRes] = await Promise.all([
      // @security not a table read, for the same reason AgenciesView is not: the contact and
      //           billing columns on `agencies` and all of `agency_contacts` are revoked
      //           from `authenticated`, and this branch is admin-only anyway. The
      //           RPC returns every agency, so the active filter moves to the client.
      //           @see schemas/SCHEMA.sql, get_agencies_admin
      supabase.rpc('get_agencies_admin'),
      supabase.from('platforms').select('*').eq('is_active', true),
      supabase.from('deliverable_types').select('*').eq('is_active', true),
    ]);
    setLookupErrors({
      agencies: aRes.error || null,
      platforms: pRes.error || null,
      deliverableTypes: dtRes.error || null,
    });
    // The RPC has no server-side filter, so `is_active` is applied here rather than as
    // an.eq on the query.
    setAgencies(aRes.error ? [] : (aRes.data || []).filter(a => a.is_active)
      .map(a => ({ ...a, contacts: sortContacts(a.contacts) })));
    setPlatforms(pRes.error ? [] : (pRes.data || []));
    setDeliverableTypes(dtRes.error ? [] : (dtRes.data || []));
  }

  /**
   * Load campaigns (+ embedded deliverables, revisions, payouts/splits) and, for
   * admins, the agency/platform/type lookups. Invoices are fetched separately and
   * merged by campaign_id (see file-header gotcha on view joins).
   *
   * @gotcha the embedded payout_splits select uses PAYOUT_SPLIT_DESTINATION_EMBED
   *         to disambiguate the dual destination FK; a bare embed returns PGRST201
   *         and the whole query fails silently.
   */
  async function fetchAll() {
    begin();
    setLoadErr(null);
    // Read to exhaustion, not `.limit(500)`: campaign 501 did not exist to this screen, and
    // this list is the product's spine with no pagination control to hang a notice on.
    // `id` is the paging tiebreak, since `created_at` is not unique.
    // @perf measured against production, not guessed: 82 campaigns with 143 deliverables, 84
    //       payouts and 181 splits serialise to 290 kB and 55 ms server side, which is ONE
    //       page at the 1,000 row default and about 3.6 kB per campaign. No explicit pageSize
    //       is warranted until roughly 3,000 campaigns. P179.
    // @see utils/fetchAllRows.js, .claude/rules/hub-data.md
    const makeCampaigns = () => {
      let q = supabase.from('campaigns').select(`
      *, agency:agencies(name), creator:profiles!campaigns_creator_profile_id_fkey(full_name, creator_name),
      campaign_deliverables(
        *, platform:platforms(name), deliverable_type:deliverable_types(name),
        revision_rounds(*, submitted_by_profile:profiles!revision_rounds_submitted_by_fkey(full_name))
      ),
      creator_payouts(payout_status_id, payout_amount, payout_date, payout_notes,
        payout_splits(split_status_id, amount, percentage, notes,
          destination_id, expense_id, expense_period, recharge_allocation_id,
          ${PAYOUT_SPLIT_DESTINATION_EMBED}(name, account_type, account_last4, institution),
          expense:expenses(id, name, type, frequency),
          sent_date, cleared_date, reference))
    `).order('created_at', { ascending: false }).order('id');
      if (profileId) q = q.eq('creator_profile_id', profileId);
      return q;
    };
    const campaignsRead = fetchAllRows(makeCampaigns)
      .then((data) => ({ data, error: null }), (error) => ({ data: null, error }));

    if (isAdmin) {
      const [cRes] = await Promise.all([campaignsRead, loadLookups()]);
      // The admin half of the same list the creator branch below already guards.
      if (cRes.error) { setLoadErr(cRes.error); setCampaigns([]); end(); return; }
      // Invoices fetched separately, scoped to the campaigns we just loaded.
      // Joining through views fails silently (see CLAUDE.md "Critical Gotchas").
      const campaignIds = (cRes.data || []).map(c => c.id);
      const invRes = campaignIds.length
        ? await supabase.from('invoices').select('*').in('campaign_id', campaignIds)
        : { data: [], error: null };
      // A refused invoice read is not a missing decoration: every campaign then merges an
      // empty `invoices` array, so a billed campaign reads as Not Invoiced and the row
      // offers to invoice it again.
      if (invRes.error) { setLoadErr(invRes.error); setCampaigns([]); end(); return; }
      const invoiceMap = {};
      for (const i of (invRes.data || [])) {
        if (!invoiceMap[i.campaign_id]) invoiceMap[i.campaign_id] = [];
        invoiceMap[i.campaign_id].push(i);
      }
      const merged = (cRes.data || []).map(camp => ({ ...camp, invoices: invoiceMap[camp.id] || [] }));
      setCampaigns(merged);
      setSelectedCampaign(prev => prev ? (merged.find(c => c.id === prev.id) || prev) : null);
      if (openCampaignIdRef.current) enrichWithStats(openCampaignIdRef.current);
    } else {
      const { data, error } = await campaignsRead;
      // The campaign list itself. An empty one reads as "no campaigns".
      if (error) { setLoadErr(error); end(); return; }
      const fresh = data || [];
      setCampaigns(fresh);
      setSelectedCampaign(prev => prev ? (fresh.find(c => c.id === prev.id) || prev) : null);
    }
    end();
  }

  /**
   * Re-fetch one campaign's deliverables from the stats view (adds views/ER/
   * completion that the base table lacks) and resolve artist/track metadata,
   * then splice the enriched rows onto the open campaign.
   *
   * @perf two batched yt_dlp_metadata lookups (music IDs, posted-video IDs),
   *       never one round-trip per deliverable.
   */
  async function enrichWithStats(campaignId) {
    const { data, error } = await supabase
      .from('campaign_deliverables_with_stats')
      .select('*, platform:platforms(name), deliverable_type:deliverable_types(name), revision_rounds(*, submitted_by_profile:profiles!revision_rounds_submitted_by_fkey(full_name))')
      .eq('campaign_id', campaignId);
    // Enrichment over an already-rendered list: a failure leaves the stats
    // columns unfilled rather than emptying the tab, so it is not escalated.
    if (error || !data) return;

    const map = {};

    // For deliverables with a music_url: look up yt-dlp data keyed by the stable numeric
    // music ID (extracted from the URL). Short links (no parseable ID) fall back to the
    // full URL as the key (same behavior as before for those rare cases).
    const musicLookupKeys = [...new Set(
      data.filter(d => d.music_url)
        .map(d => extractTikTokMusicId(d.music_url) || d.music_url)
    )];
    // For deliverables without a music_url: show artist/track from the posted video itself.
    // Extract TikTok video IDs directly from post_url (not from the view join) to ensure
    // we're always looking up the exact video the creator posted.
    const postVideoIds = [...new Set(
      data.filter(d => !d.music_url && d.post_url)
        .map(d => { const m = d.post_url.match(/\/video\/(\d+)/); return m ? m[1] : null; })
        .filter(Boolean)
    )];

    /* Deliberately best-effort, the same classification `enrichWithStats` states above it and
     * the same one `useCreators`, `RateCardEditor` and `AnalyticsPage` write down: these two
     * decorate an already-rendered deliverable with an artist and a track name, and a refusal
     * leaves the sound cell blank rather than asserting the post used no licensed audio. It
     * was the one such read in this repo that did not say so, which is what made it
     * indistinguishable from an oversight. */
    const [musicRes, videoRes] = await Promise.all([
      musicLookupKeys.length > 0
        ? supabase.from('yt_dlp_metadata').select('video_id, raw').in('video_id', musicLookupKeys).not('raw', 'is', null)
        : Promise.resolve({ data: [] }),
      postVideoIds.length > 0
        ? supabase.from('yt_dlp_metadata').select('video_id, raw').in('video_id', postVideoIds).not('raw', 'is', null)
        : Promise.resolve({ data: [] }),
    ]);

    for (const m of musicRes.data || []) {
      const artist        = m.raw?.artist || m.raw?.music_author || null;
      const track         = m.raw?.track  || m.raw?.music        || null;
      const canonical_url = m.raw?.canonical_url || null;
      if (artist || track || canonical_url) map[`music:${m.video_id}`] = { artist, track, canonical_url };
    }
    for (const m of videoRes.data || []) {
      const artist    = m.raw?.artist     || m.raw?.music_author || null;
      const track     = m.raw?.track      || m.raw?.music        || null;
      const music_url = m.raw?.music_url  || null;
      if (artist || track || music_url) map[`vid:${m.video_id}`] = { artist, track, music_url };
    }

    setYtdlpMap(map);

    setSelectedCampaign(prev => {
      if (!prev || prev.id !== campaignId) return prev;
      return { ...prev, campaign_deliverables: data };
    });
  }

  const { agencyOptions, platformOptions, months } = useMemo(() => ({
    agencyOptions:   [...new Set(campaigns.map(c => c.agency?.name).filter(Boolean))].sort(),
    platformOptions: [...new Set(campaigns.flatMap(c => (c.campaign_deliverables || []).map(d => d.platform?.name)).filter(Boolean))].sort(),
    months:          [...new Set(campaigns.map(c => { const d = c.campaign_start_date || c.created_at; return d ? d.slice(0, 7) : null; }).filter(Boolean))].sort().reverse(),
  }), [campaigns]);
  // Fixed, unlike the platform list beside it: a choice that vanishes when nothing matches it
  // cannot answer "is anything unpaid?", which is the only question this control is asked.
  const paymentOptions = PAID_FILTER_CHOICES.filter(o => o.value !== PAID_FILTER_ALL);

  useEffect(() => {
    if (!openColFilter) return;
    const handler = () => setOpenColFilter(null);
    document.addEventListener('click', handler);
    return () => document.removeEventListener('click', handler);
  }, [openColFilter]);

  const displayCampaigns = useMemo(() => {
    // Pre-build min-date index to avoid O(n·m) cost inside the sort comparator
    const postDateMin = sortCol === 'post_date'
      ? Object.fromEntries(campaigns.map(c => [c.id, (c.campaign_deliverables || []).reduce((min, d) =>
          !d.contracted_post_date ? min : (!min || d.contracted_post_date < min ? d.contracted_post_date : min), null)]))
      : null;

    const filtered = campaigns.filter(c => {
      if (filter !== 'all' && campText(c.status_id) !== filter) return false;
      if (isAdmin && creatorFilter !== 'all' && c.creator_profile_id !== creatorFilter) return false;
      if (isAdmin && agencyFilter && c.agency?.name !== agencyFilter) return false;
      if (isAdmin && colFilters.platform && !(c.campaign_deliverables || []).some(d => d.platform?.name === colFilters.platform)) return false;
      if (isAdmin && colFilters.payment
        && !matchesPaidFilter(colFilters.payment, agencyHasPaid(invText(c.invoices?.[0]?.payment_status_id)))) return false;
      if (monthFilter !== 'all') {
        const d = c.campaign_start_date || c.created_at || '';
        if (!d.startsWith(monthFilter)) return false;
      }
      return true;
    });

    return [...filtered].sort((a, b) => {
      let av, bv;
      switch (sortCol) {
        // Sorts by what the cell SHOWS, not the internal serial (which orders by date).
        case 'campaign_name': av = campaignLabel(a).toLowerCase(); bv = campaignLabel(b).toLowerCase(); break;
        case 'agency': av = (a.agency?.name || '').toLowerCase(); bv = (b.agency?.name || '').toLowerCase(); break;
        case 'posts': av = (a.campaign_deliverables || []).length; bv = (b.campaign_deliverables || []).length; break;
        case 'post_date': av = (postDateMin[a.id] || ''); bv = (postDateMin[b.id] || ''); break;
        case 'rate': av = Number(a.contracted_rate) || 0; bv = Number(b.contracted_rate) || 0; break;
        case 'status': av = campText(a.status_id) || ''; bv = campText(b.status_id) || ''; break;
        case 'payment': av = invText(a.invoices?.[0]?.payment_status_id) || ''; bv = invText(b.invoices?.[0]?.payment_status_id) || ''; break;
        default: av = a.created_at || ''; bv = b.created_at || '';
      }
      if (av < bv) return sortDir === 'asc' ? -1 : 1;
      if (av > bv) return sortDir === 'asc' ? 1 : -1;
      return 0;
    });
  }, [campaigns, filter, creatorFilter, agencyFilter, monthFilter, sortCol, sortDir, colFilters, isAdmin, campText, invText]);

  function openDetail(c) {
    openCampaignIdRef.current = c.id;
    setSelectedCampaign(c);
    setDetailTab('deliverables');
    enrichWithStats(c.id);
  }
  function closeDetail() {
    openCampaignIdRef.current = null;
    setSelectedCampaign(null);
  }

  useEscapeKey(useCallback(closeDetail, []), !!selectedCampaign);

  if (loading) return <div className="page"><Loading /></div>;

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">{isAdmin ? 'CAMPAIGNS' : 'MY CAMPAIGNS'}</h1>
          <div className="page-subtitle">
            {isAdmin ? `${displayCampaigns.length} of ${campaigns.length} deals` : `${campaigns.length} total deals`}
            <Refreshing on={refreshing} />
          </div>
        </div>
        {isAdmin && <button className="btn btn-primary" onClick={() => setShowModal(true)}>+ New Campaign</button>}
      </div>

      <div className="filters-row">
        {isAdmin && <span className="text-muted text-xs" style={{ marginRight: 4 }}>STATUS</span>}
        {CAMPAIGN_STATUSES.map(s => (
          <button key={s.value} className={`filter-chip ${filter === s.value ? 'active' : ''}`} aria-pressed={filter === s.value} onClick={() => setFilter(s.value)}>{s.label}</button>
        ))}
        {isAdmin && (
          <>
            <div style={{ width: 1, height: 20, background: 'var(--border)', margin: '0 8px' }} />
            <span className="text-muted text-xs" style={{ marginRight: 4 }}>CREATOR</span>
            <CreatorFilterChips value={creatorFilter} onChange={setCreatorFilter} creators={creators} />
            <div style={{ width: 1, height: 20, background: 'var(--border)', margin: '0 8px' }} />
            <span className="text-muted text-xs" style={{ marginRight: 4 }}>AGENCY</span>
            <AgencySelect value={agencyFilter} onChange={setAgencyFilter} options={agencyOptions} />
            {(colFilters.platform || colFilters.payment) && (
              <button className="filter-chip" style={{ color: 'var(--blue)', marginLeft: 8 }}
                onClick={() => setColFilters({ platform: '', payment: '' })}>
                Clear column filters ✕
              </button>
            )}
          </>
        )}
        {months.length > 0 && (
          <select className="form-select" aria-label="Filter by month" style={{ width: 'auto', padding: '4px 8px', fontSize: 12, marginLeft: 8 }} value={monthFilter} onChange={e => setMonthFilter(e.target.value)}>
            <option value="all">All months</option>
            {months.map(m => <option key={m} value={m}>{fmtMonth(m)}</option>)}
          </select>
        )}
      </div>

      {loadErr ? (
        <ReadError error={loadErr} onRetry={fetchAll} />
      ) : displayCampaigns.length === 0 ? (
        /* "Adjust filters" fired with every filter at its default, telling a brand new admin
           to undo something they never did. */
        <EmptyState icon="◎"
          title={isAdmin ? 'No campaigns yet' : 'No campaigns here'}
          text={isAdmin ? 'Create a campaign to get started.' : 'Your manager will add campaigns as deals are confirmed'}
          filtered={{ unfiltered: campaigns, dirty: campaignFiltersDirty, onClear: clearCampaignFilters,
            title: 'No campaigns match these filters',
            text: `${campaigns.length} ${campaigns.length === 1 ? 'campaign is' : 'campaigns are'} hidden by the filters above.` }} />
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <SortTh col="campaign_name" sortBy={sortCol} sortDir={sortDir} onToggle={toggleSort}>Campaign</SortTh>
                <th scope="col">
                  Platforms
                  {isAdmin && <ColFilterBtn col="platform" options={platformOptions} label="Platforms" colFilters={colFilters} openColFilter={openColFilter} setColFilters={setColFilters} setOpenColFilter={setOpenColFilter} />}
                </th>
                <th scope="col" style={{ userSelect: 'none' }}>
                  <button type="button" className="th-sort" onClick={() => toggleSort('posts')}>Posts<SortIcon col="posts" sortBy={sortCol} sortDir={sortDir} /></button>
                  <span style={{ margin: '0 4px', color: 'var(--dim)' }}>·</span>
                  <button type="button" className="th-sort" onClick={() => toggleSort('post_date')}>Date<SortIcon col="post_date" sortBy={sortCol} sortDir={sortDir} /></button>
                </th>
                <SortTh col="rate" sortBy={sortCol} sortDir={sortDir} onToggle={toggleSort}>Rate</SortTh>
                <SortTh col="status" sortBy={sortCol} sortDir={sortDir} onToggle={toggleSort}>Status</SortTh>
                <th scope="col">
                  <button type="button" className="th-sort" onClick={() => toggleSort('payment')}>Payment<SortIcon col="payment" sortBy={sortCol} sortDir={sortDir} /></button>
                  {isAdmin && <ColFilterBtn col="payment" options={paymentOptions} label="Payment" colFilters={colFilters} openColFilter={openColFilter} setColFilters={setColFilters} setOpenColFilter={setOpenColFilter} />}
                </th>
              </tr>
            </thead>
            <tbody>
              {displayCampaigns.map(c => {
                const deliverables = c.campaign_deliverables || [];
                const posted = postedDelivId ? deliverables.filter(d => d.draft_status_id === postedDelivId).length : null;
                const total  = deliverables.length;
                const earliestPost = deliverables.reduce((min, d) => {
                  if (!d.contracted_post_date) return min;
                  return !min || d.contracted_post_date < min ? d.contracted_post_date : min;
                }, null);
                const inv          = c.invoices?.[0];
                const payout       = c.creator_payouts?.[0];
                const paymentStatusId = inv?.payment_status_id;
                const inKindValue  = inv?.in_kind_value;
                const platformCounts = {};
                deliverables.forEach(d => {
                  const name = d.platform?.name || '?';
                  platformCounts[name] = (platformCounts[name] || 0) + 1;
                });
                return (
                  <tr key={c.id} className={selectedCampaign?.id === c.id ? 'is-selected' : ''} {...activationProps(() => openDetail(c), { pressed: selectedCampaign?.id === c.id })}>
                    <td><CampaignName campaign={c} /></td>
                    <td>
                      <div className="flex gap-8" style={{ flexWrap: 'wrap' }}>
                        {Object.entries(platformCounts).length === 0
                          ? <span className="text-muted">—</span>
                          : Object.entries(platformCounts).map(([name, count]) => (
                              <span key={name} className="badge badge-neutral">
                                {name}{count > 1 ? ` ×${count}` : ''}
                              </span>
                            ))}
                      </div>
                    </td>
                    <td style={{ fontWeight: 500 }}>
                      {total > 0 ? (
                        <div>
                          {isAdmin
                            ? <span title={postedTitle} style={{ color: posted === total ? 'var(--green)' : 'var(--white)' }}>{posted ?? '?'}/{total}</span>
                            : (
                              <div className="flex items-center gap-8">
                                <span title={postedTitle} style={{ fontSize: 12 }}>{posted ?? '?'}/{total}</span>
                                {posted !== null && <div style={{ width: 40, height: 3, background: 'var(--surface3)', borderRadius: 2 }}>
                                  <div style={{ width: `${(posted / total) * 100}%`, height: '100%', background: posted === total ? 'var(--green)' : 'var(--orange)', borderRadius: 2 }} />
                                </div>}
                              </div>
                            )}
                          {earliestPost && <div className="text-muted text-xs" style={{ marginTop: 2 }}>{fmtDate(earliestPost)}</div>}
                        </div>
                      ) : <span className="text-muted">—</span>}
                    </td>
                    <td>
                      {/* The VALUE, not the word. The payment cell beside this one already
                          carries an "In Kind" badge, so printing the words here said it
                          twice and spent the money column on no number. --purple, not
                          --blue: the stated value of goods is not money.
                          @see docs/DESIGN.md, and the same call in the Payments in-kind table */}
                      {isInKind(inv?.is_in_kind)
                        ? <span style={{ color: 'var(--purple)', fontWeight: 500 }}>
                            {fmtMoney(inKindValue ?? inv?.invoice_amount ?? c.contracted_rate)}
                          </span>
                        : c.contracted_rate
                          ? <span style={{ color: 'var(--blue)', fontWeight: 500 }}>
                              {fmtMoney(c.contracted_rate)}
                            </span>
                          : <span className="text-muted">TBD</span>}
                    </td>
                    <td><Badge group="campaign" statusId={c.status_id} /></td>
                    <td>
                      {isAdmin ? (
                        paymentStatusId
                          ? <Badge group="payment" statusId={paymentStatusId} />
                          : <span className="text-muted text-xs">No invoice</span>
                      ) : (
                        (() => {
                          if (isInKind(inv?.is_in_kind)) return <span style={{ fontSize: 11, color: 'var(--muted)', fontStyle: 'italic' }}>In Kind</span>;
                          if (payout?.payout_status_id) return <Badge group="payout" statusId={payout.payout_status_id} />;
                          if (paymentStatusId) return <Badge group="payment" statusId={paymentStatusId} />;
                          return <span className="text-muted text-xs">—</span>;
                        })()
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {isAdmin && showModal && (
        <CampaignModal
          agencies={agencies} creators={creators} platforms={platforms} deliverableTypes={deliverableTypes}
          lookupErrors={lookupErrors} onRetryLookups={loadLookups}
          onClose={() => setShowModal(false)}
          onSaved={() => { setShowModal(false); fetchAll(); }}
        />
      )}

      {selectedCampaign && (
        <CampaignDetail
          // Key by campaign id so switching campaigns fully remounts the panel
          // (and InvoiceTab's mount-seeded form + write target). Same-id refresh
          // after fetchAll keeps the key stable, so in-place data updates still
          // work via CampaignDetail's useEffect([campaign]). Prevents a stale
          // invoice id from one campaign being written onto another.
          key={selectedCampaign.id}
          campaign={selectedCampaign}
          isAdmin={isAdmin}
          agencies={agencies} creators={creators} platforms={platforms} deliverableTypes={deliverableTypes}
          lookupErrors={lookupErrors} onRetryLookups={loadLookups}
          tab={detailTab} setTab={setDetailTab}
          highlightDeliverableId={highlightDeliverableId}
          ytdlpMap={ytdlpMap}
          onClose={closeDetail}
          onUpdated={() => { fetchAll(); if (onCampaignStatusChanged) onCampaignStatusChanged(); }}
        />
      )}
    </div>
  );
}

/**
 * Slide-in detail panel for one campaign: header (status/payment/edit actions)
 * plus the role-specific tab set. Owns campaign status + payment-status updates.
 *
 * @gotcha mounted with key={campaign.id} by the parent so switching campaigns
 *         fully remounts the panel; a same-id refresh keeps the key stable so
 *         in-place updates still flow through useEffect([campaign]).
 * @gotcha the Update Status quick-pick cannot set Cancelled; its options come
 *         from editableCampaignStatuses like every other status control. It used
 *         to offer it and handle it with a partial teardown of its own (deleting
 *         a non-Paid invoice, leaving any posted JE standing). Cancellation is
 *         CancelCampaignDialog / cancel_campaign only.
 */
function CampaignDetail({ campaign, isAdmin, agencies, creators, platforms, deliverableTypes, lookupErrors, onRetryLookups, tab, setTab, highlightDeliverableId, ytdlpMap, onClose, onUpdated }) {
  const { dirtyProps } = useUnsavedGuard();
  const toast = useToast();
  const askConfirm = useConfirm();
  const { options: statusOptions } = useStatusOptions();
  const campaignOptions     = statusOptions.campaign || [];
  const deliverableOptions  = statusOptions.deliverable || [];
  const PAYMENT_STATUSES    = statusOptions.payment || [];
  const postedDelivId       = deliverableOptions.find(o => o.value === 'Posted')?.id;
  const activeId            = campaignOptions.find(o => o.value === 'Active')?.id;
  const [c, setC] = useState(campaign);
  const [editingPayment, setEditingPayment] = useState(false);
  const [showEditCampaign, setShowEditCampaign] = useState(false);
  // The creator's Mark Campaign Complete is the only thing that writes here now: the admin's
  // status quick pick folded into Edit Campaign, which reports inside its own modal.
  const [actionError, setActionError] = useState('');

  useEffect(() => { setC(campaign); }, [campaign]);

  const deliverables = c.campaign_deliverables || [];
  // Derived from the rule, not restated. This gate counted ROWS while `completedBlockedReason`
  // counts SLOTS, so one row of quantity 3 with a single post live offered the creator a button
  // the two admin writers then refused. @see completedBlockedReason
  const canMarkComplete = completedBlockedReason(deliverables, postedDelivId) === null
    && c.status_id === activeId;

  async function updatePaymentStatus(payment_status) {
    if (c.invoices?.[0]) {
      const psId = (statusOptions.payment || []).find(o => o.value === payment_status)?.id || null;
      const { error } = await mutate(supabase.from('invoices').update({ payment_status_id: psId }).eq('id', c.invoices[0].id));
      if (error) { toast.error(error); return; }
    }
    setEditingPayment(false);
    toast.success(`Payment marked ${payment_status}`);
    onUpdated();
  }

  async function markComplete() {
    if (!(await askConfirm({ title: 'Mark as completed?', body: 'This locks the campaign and triggers invoice generation.', confirmLabel: 'Mark complete' }))) return;
    setActionError('');
    const { error } = await supabase.from('campaigns').update({ status_id: campaignOptions.find(o => o.value === 'Completed')?.id || null }).eq('id', c.id);
    if (error) { setActionError('Could not mark this campaign complete. Please try again.'); return; }
    toast.success('Campaign completed');
    onUpdated();
  }

  const tabs = isAdmin ? CAMPAIGN_DETAIL_TABS : ['deliverables', 'brief', 'payment', 'comments'];
  // Tab keys that need a label different from their capitalized key.
  const TAB_LABELS = { paylink: 'Stripe' };

  return (
    <div className="detail-panel" {...dirtyProps}>
      <div className="detail-header">
        <div className="flex items-center justify-between mb-8">
          <Badge group="campaign" statusId={c.status_id} status={c.status} />
          <button className="btn btn-ghost btn-icon btn-sm" onClick={onClose} aria-label="Close campaign details">✕</button>
        </div>
        {/* Agency and creator are both inside the display name; only the date
            adds anything, and it is the one thing telling two same-agency deals
            with the same creator apart. */}
        <h2 className="detail-panel-title">{campaignLabelParts(c).label}</h2>
        <div className="text-muted mt-4">{campaignLabelParts(c).date}</div>

        {isAdmin ? (
          <div className="mt-8" style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
            <button className="btn btn-secondary btn-sm" onClick={() => setShowEditCampaign(true)}>Edit Campaign</button>
            <button className="btn btn-secondary btn-sm" onClick={() => setEditingPayment(true)}>Update Payment</button>
          </div>
        ) : (
          <>
            {c.contracted_rate && (
              <div style={{ color: 'var(--blue)', fontWeight: 600, marginTop: 8 }}>
                {fmtMoney(c.contracted_rate)}
              </div>
            )}
            {canMarkComplete && (
              <button className="btn btn-primary btn-sm" style={{ marginTop: 10 }} onClick={markComplete}>
                ✓ Mark Campaign Complete
              </button>
            )}
          </>
        )}
        {actionError && <Feedback value={actionError} style={{ marginTop: 8 }} />}
      </div>

      <Tabs
        label="Campaign detail"
        panelId="campaign-detail-panel"
        style={{ padding: '0 24px' }}
        value={tab}
        onChange={setTab}
        items={tabs.map(t => ({ id: t, label: TAB_LABELS[t] || (t.charAt(0).toUpperCase() + t.slice(1)) }))}
      />

      <div className="detail-body" {...tabPanelProps('campaign-detail-panel', tab)}>
        {tab === 'deliverables' && (
          <DeliverableTab campaign={c} isAdmin={isAdmin} platforms={platforms} deliverableTypes={deliverableTypes} lookupErrors={lookupErrors} onRetryLookups={onRetryLookups} highlightDeliverableId={highlightDeliverableId} ytdlpMap={ytdlpMap} onUpdated={onUpdated} />
        )}
        {tab === 'brief' && !isAdmin && (
          <BriefTab campaign={c} />
        )}
        {tab === 'invoice' && isAdmin && (
          <InvoiceTab campaign={c} />
        )}
        {tab === 'paylink' && isAdmin && (
          <PayLinkTab campaign={c} />
        )}
        {tab === 'payment' && !isAdmin && (
          <PaymentTab campaign={c} />
        )}
        {tab === 'files' && isAdmin && (
          <FilesTab campaign={c} />
        )}
        {tab === 'comments' && (
          <Comments campaignId={c.id} />
        )}
      </div>

      {isAdmin && editingPayment && (
        <QuickPickModal title="Update Payment Status" options={PAYMENT_STATUSES}
          onPick={updatePaymentStatus} onClose={() => setEditingPayment(false)} />
      )}
      {isAdmin && showEditCampaign && (
        <EditCampaignModal campaign={c} agencies={agencies} creators={creators} lookupErrors={lookupErrors} onRetryLookups={onRetryLookups}
          onClose={() => setShowEditCampaign(false)}
          onSaved={() => { setShowEditCampaign(false); onUpdated(); }} />
      )}
    </div>
  );
}

/**
 * Deliverables tab: per-platform cards with music/retention/stats, revision
 * rounds, and role-specific actions (admin: add/edit/mark-posted/schedule;
 * creator: submit draft, link/mark-posted, confirm agency approval).
 *
 * @gotcha posted/total progress counts SLOTS (sums quantity), not rows, so a
 *         bundle of N counts as N. Campaign cannot be Completed until every slot
 *         is Posted.
 */
function DeliverableTab({ campaign, isAdmin, platforms, deliverableTypes, lookupErrors, onRetryLookups, highlightDeliverableId, ytdlpMap, onUpdated }) {
  const toast = useToast();
  const askConfirm = useConfirm();
  const { options: statusOptions } = useStatusOptions();
  const deliverableOptions = statusOptions.deliverable || [];
  const postedId    = deliverableOptions.find(o => o.value === 'Posted')?.id;
  const approvedId  = deliverableOptions.find(o => o.value === 'Approved')?.id;
  const scheduledId = deliverableOptions.find(o => o.value === 'Scheduled')?.id;
  const [showAddDeliverable, setShowAddDeliverable] = useState(false);
  const [editingDeliverable, setEditingDeliverable] = useState(null);
  const [editingRevision, setEditingRevision]       = useState(null);
  const [showAddRevision, setShowAddRevision]       = useState(null);
  const [showMarkPosted, setShowMarkPosted]         = useState(null);
  const [expanding, setExpanding]                   = useState(null);
  const [showSubmitDraft, setShowSubmitDraft]       = useState(null);
  const [showLinkVideo, setShowLinkVideo]           = useState(null);
  const [showCreatorMarkPosted, setShowCreatorMarkPosted] = useState(null);
  const [showSchedulePost, setShowSchedulePost]           = useState(null);
  const [confirmingApproval, setConfirmingApproval]       = useState(null);
  const [tabError, setTabError] = useState('');
  const highlightRef = useRef(null);

  useEffect(() => {
    if (highlightDeliverableId && highlightRef.current) {
      highlightRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, [highlightDeliverableId]);

  const deliverables = campaign.campaign_deliverables || [];
  const totalSlots   = deliverables.reduce((sum, d) => sum + slotsOf(d), 0);
  const postedSlots  = deliverables.filter(d => d.draft_status_id === postedId).reduce((sum, d) => sum + slotsOf(d), 0);
  const allPosted    = totalSlots > 0 && postedSlots === totalSlots;

  async function deleteDeliverable(d) {
    if (!(await askConfirm({ title: `Delete this ${d.platform?.name || 'platform'} deliverable?`, body: 'All its revision rounds will be deleted too. This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('campaign_deliverables').delete().eq('id', d.id));
    if (error) { toast.error(error); return; }
    toast.success('Deliverable deleted');
    onUpdated();
  }

  async function confirmAgencyApproval(revisionId) {
    setTabError('');
    setConfirmingApproval(revisionId);
    const { error } = await supabase.rpc('creator_confirm_agency_approval', { p_revision_id: revisionId });
    setConfirmingApproval(null);
    if (error) { setTabError('Could not confirm approval. Please try again.'); return; }
    toast.success('Approval confirmed');
    onUpdated();
  }

  /** Cancel a Zernio-scheduled post via the schedule-post edge function (returns it to Approved). */
  async function cancelScheduledPost(d) {
    if (!(await askConfirm({ title: 'Cancel this scheduled post?', body: 'The deliverable will return to Approved status.', confirmLabel: 'Cancel schedule' }))) return;
    setTabError('');
    const { error } = await supabase.functions.invoke('schedule-post', {
      body: { action: 'cancel', deliverable_id: d.id },
    });
    if (error) { setTabError('Could not cancel this scheduled post. Please try again.'); return; }
    onUpdated();
  }

  async function deleteRevision(r) {
    if (!(await askConfirm({ title: `Delete round ${r.round_number}?`, body: 'This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('revision_rounds').delete().eq('id', r.id));
    if (error) { toast.error(error); return; }
    toast.success('Revision deleted');
    onUpdated();
  }

  /** Replace a bundle row (quantity N) with N individually tracked deliverable rows. Irreversible. */
  async function expandDeliverable(d) {
    if (!(await askConfirm({ title: `Expand bundle into ${d.quantity} posts?`, body: 'The original bundle row is replaced with individually tracked deliverables. This cannot be undone.', confirmLabel: 'Expand bundle' }))) return;
    setExpanding(d.id);
    const rows = Array.from({ length: d.quantity }, (_, i) => ({
      campaign_id: d.campaign_id,
      platform_id: d.platform_id,
      deliverable_type_id: d.deliverable_type_id,
      deliverable_details: d.deliverable_details ? `${d.deliverable_details} (Post ${i + 1})` : `Post ${i + 1} of ${d.quantity}`,
      quantity: 1,
      contracted_post_date: d.contracted_post_date,
      draft_status_id: deliverableOptions.find(o => o.value === 'Not Started')?.id || null,
    }));
    // Expand one multi-post deliverable into N single-post rows. The insert has
    // to land before the original is removed, or a failure between them loses
    // the deliverable entirely.
    const { error: insErr } = await mutate(supabase.from('campaign_deliverables').insert(rows));
    if (insErr) { toast.error(insErr); return; }
    const { error: delErr } = await mutate(supabase.from('campaign_deliverables').delete().eq('id', d.id));
    if (delErr) { toast.error(delErr); return; }
    setExpanding(null);
    toast.success('Deliverable expanded');
    onUpdated();
  }

  return (
    <div>
      {tabError && <Feedback value={tabError} style={{ marginBottom: 8 }} />}
      {isAdmin ? (
        <div className="flex items-center justify-between mb-12">
          <div style={{ fontSize: 12, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 1, color: 'var(--muted)' }}>
            {postedSlots}/{totalSlots} Posted
            {totalSlots > 0 && !allPosted && <span style={{ color: 'var(--orange)', marginLeft: 8 }}>· Campaign cannot be Completed until all are posted</span>}
            {allPosted && totalSlots > 0 && <span style={{ color: 'var(--green)', marginLeft: 8 }}>· All posted ✓</span>}
          </div>
          <button className="btn btn-secondary btn-sm" onClick={() => setShowAddDeliverable(true)}>+ Add Deliverable</button>
        </div>
      ) : (
        <div className="text-muted text-xs mb-12" style={{ textTransform: 'uppercase', letterSpacing: 1 }}>
          {deliverables.length} platform(s) in this deal
        </div>
      )}

      {deliverables.length === 0 && (
        <EmptyState icon="◻"
          title={`No ${isAdmin ? 'deliverables' : 'platforms'} yet`}
          text={isAdmin ? 'Add platforms covered under this deal' : 'Your manager will add the platforms covered under this deal'} />
      )}

      {deliverables.map(d => {
        const canSubmitDraft = !isAdmin && d.draft_status_id !== postedId && d.draft_status_id !== approvedId && d.draft_status_id !== scheduledId;
        const isHighlighted  = d.id === highlightDeliverableId;
        return (
          <div key={d.id} className="deliverable-card"
            ref={isHighlighted ? highlightRef : null}
            style={isHighlighted ? { border: '1px solid var(--blue)', boxShadow: '0 0 0 3px color-mix(in oklab, var(--blue) 15%, transparent)' } : undefined}
          >
            <div className="deliverable-card-header">
              <div>
                <span className="deliverable-platform">{d.platform?.name || 'Unknown Platform'}</span>
                {d.deliverable_type && <span className="text-muted text-sm" style={{ marginLeft: 8 }}>· {d.deliverable_type.name}</span>}
                {d.quantity > 1 && (
                  <span className="text-muted text-sm" style={{ marginLeft: 6 }}>
                    × {d.quantity}
                    {isAdmin && (
                      <button
                        className="btn btn-ghost btn-sm"
                        style={{ fontSize: 10, padding: '1px 6px', marginLeft: 6, color: 'var(--orange)', border: '1px solid var(--orange)' }}
                        onClick={() => expandDeliverable(d)}
                        disabled={expanding === d.id}
                        title={`Split into ${d.quantity} individually tracked posts`}
                      >{expanding === d.id ? '…' : 'Expand'}</button>
                    )}
                  </span>
                )}
              </div>
              {isAdmin ? (
                <div className="flex items-center gap-8">
                  <button className="btn btn-ghost btn-sm" style={{ fontSize: 11, padding: '2px 8px' }} onClick={() => setEditingDeliverable(d)}>Edit</button>
                  <button className="btn btn-ghost btn-sm" style={{ fontSize: 11, padding: '2px 8px', color: 'var(--red)' }} onClick={() => deleteDeliverable(d)}>Delete</button>
                  <Badge group="deliverable" statusId={d.draft_status_id} />
                </div>
              ) : (
                <Badge group="deliverable" statusId={d.draft_status_id} />
              )}
            </div>

            {isAdmin && d.quantity > 1 && (
              <Feedback className="mb-8" value={{ tone: 'warn',
                title: `Bundle of ${d.quantity} posts tracked as one row`,
                body: `Click Expand to split it into ${d.quantity} individually trackable posts.` }} />
            )}

            {d.deliverable_details && (
              isAdmin
                ? <div className="text-muted text-sm mb-8">{d.deliverable_details}</div>
                : <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 10, padding: '8px 10px', background: 'var(--surface3)', borderRadius: 4 }}>{d.deliverable_details}</div>
            )}

            {(() => {
              if (d.music_url) {
                const musicLookupKey = extractTikTokMusicId(d.music_url) || d.music_url;
                const meta         = ytdlpMap?.[`music:${musicLookupKey}`];
                const isOriginal   = isOriginalSoundLabel(meta?.track);
                const resolvedTrack = isOriginal ? 'Original sound' : meta?.track;
                const artistTrack  = meta?.artist && resolvedTrack ? `${meta.artist} - "${resolvedTrack}"`
                                   : meta?.artist ? meta.artist
                                   : resolvedTrack ? `"${resolvedTrack}"` : null;
                const canonicalUrl = meta?.canonical_url || null;
                const primaryUrl   = canonicalUrl || d.music_url;
                const primaryLabel = primaryUrl.length > 50 ? primaryUrl.slice(0, 50) + '…' : primaryUrl;
                // Show the contracted URL below only for short links that resolved to a
                // canonical URL. Slug-only differences on the same numeric ID are the same song.
                const isShortLink    = /tiktok\.com\/t\/|vm\.tiktok\.com/i.test(d.music_url);
                const showContracted = isShortLink && canonicalUrl && canonicalUrl !== d.music_url;
                const contractedLabel = d.music_url.length > 45 ? d.music_url.slice(0, 45) + '…' : d.music_url;
                return (
                  <div style={{ marginBottom: 8, fontSize: 12 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <MusicIcon size={13} style={{ color: 'var(--muted)' }} />
                      <button type="button" className="link" style={{ cursor: 'pointer' }} onClick={() => openPopup(primaryUrl)}>
                        {primaryLabel}
                      </button>
                      <svg width="11" height="11" viewBox="0 0 16 16" fill="none" title="Contracted sound" style={{ color: 'var(--orange)', flexShrink: 0 }}>
                        <rect x="2" y="1" width="9" height="13" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
                        <path d="M5 5h5M5 8h5M5 11h3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>
                      </svg>
                    </div>
                    {showContracted && (
                      <div style={{ display: 'flex', alignItems: 'center', gap: 5, paddingLeft: 22, marginTop: 3 }}>
                        <svg width="11" height="11" viewBox="0 0 16 16" fill="none" style={{ color: 'var(--muted)', flexShrink: 0 }}>
                          <rect x="2" y="1" width="9" height="13" rx="1.5" stroke="currentColor" strokeWidth="1.5"/>
                          <path d="M5 5h5M5 8h5M5 11h3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>
                        </svg>
                        <span style={{ color: 'var(--muted)', fontSize: 11 }}>Contracted:</span>
                        <button type="button" className="link" style={{ cursor: 'pointer', fontSize: 11 }} onClick={() => openPopup(d.music_url)}>
                          {contractedLabel}
                        </button>
                      </div>
                    )}
                    {artistTrack && (
                      <div style={{ paddingLeft: 22, marginTop: 2, color: 'var(--muted)', fontStyle: 'italic' }}>
                        {artistTrack}
                      </div>
                    )}
                  </div>
                );
              }
              if (d.post_url) {
                // No contracted sound. Show music info derived from the posted video.
                const vidMatch = d.post_url?.match(/\/video\/(\d+)/);
                const meta     = vidMatch ? ytdlpMap?.[`vid:${vidMatch[1]}`] : null;
                if (!meta?.artist && !meta?.track && !meta?.music_url) return null;
                // The slug half stays English on purpose: TikTok builds the URL
                // slug from the track name and we have never observed the
                // localised forms there, so listing guesses would suppress a real
                // title. The label half is the one with 19 observed languages.
                const isOriginal = isOriginalSoundLabel(meta?.track) || /\/music\/original-sound-/i.test(meta?.music_url || '');
                const resolvedTrack = isOriginal ? 'Original sound' : meta?.track;
                const artistTrack = meta?.artist && resolvedTrack ? `${meta.artist} - "${resolvedTrack}"`
                                  : meta?.artist ? meta.artist
                                  : resolvedTrack ? `"${resolvedTrack}"` : null;
                if (!artistTrack && !meta?.music_url) return null;
                const muLabel = meta.music_url?.length > 50 ? meta.music_url.slice(0, 50) + '…' : meta.music_url;
                return (
                  <div style={{ marginBottom: 8, fontSize: 12 }}>
                    {meta.music_url ? (
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <MusicIcon size={13} style={{ color: 'var(--muted)' }} />
                        <button type="button" className="link" style={{ cursor: 'pointer' }} onClick={() => openPopup(meta.music_url)}>
                          {muLabel}
                        </button>
                      </div>
                    ) : (
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <MusicIcon size={13} style={{ color: 'var(--muted)' }} />
                      </div>
                    )}
                    {artistTrack && (
                      <div style={{ paddingLeft: 22, marginTop: 2, color: 'var(--muted)', fontStyle: 'italic' }}>
                        {artistTrack}
                      </div>
                    )}
                  </div>
                );
              }
              return null;
            })()}

            {((d.required_hashtags?.length > 0) || (d.ftc_disclosure && d.ftc_disclosure !== 'none')) && (
              <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center', marginBottom: 8 }}>
                {d.ftc_disclosure === 'required' && (
                  <span style={{ fontSize: 11, fontWeight: 700, padding: '2px 8px', borderRadius: 20, background: 'rgba(255,92,0,0.15)', color: 'var(--orange)' }}>FTC Required</span>
                )}
                {d.ftc_disclosure === 'optional' && (
                  <span style={{ fontSize: 11, padding: '2px 8px', borderRadius: 20, background: 'var(--surface2)', color: 'var(--muted)' }}>FTC Optional</span>
                )}
                {(d.required_hashtags || []).map(tag => (
                  <span key={tag} style={{ fontSize: 11, padding: '2px 8px', borderRadius: 20, background: 'var(--surface2)', color: 'var(--orange)' }}>#{tag}</span>
                ))}
              </div>
            )}

            {d.cover_image_url && (
              <div style={{ display: 'flex', gap: 12, marginBottom: 12, alignItems: 'flex-start' }}>
                <button type="button" className="thumb-btn" aria-label="Open this post" onClick={() => openPopup(d.post_url)}
                  style={{ flexShrink: 0, width: 72, height: 96, borderRadius: 6, overflow: 'hidden', border: '1px solid var(--border)', cursor: 'pointer' }}>
                  <img src={d.cover_image_url} alt="thumbnail" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                </button>
                <div style={{ flex: 1, minWidth: 0 }}>
                  {d.video_title && (
                    <div style={{ fontSize: 12, fontWeight: 500, lineHeight: 1.4, marginBottom: 4, wordBreak: 'break-word' }}>{d.video_title}</div>
                  )}
                  <div style={{ fontSize: 11, color: 'var(--muted)', display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                    {d.views != null && (
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                        <ViewsIcon size={12} /> {Number(d.views).toLocaleString()}
                        {d.complete_views != null && (
                          <span style={{ color: 'var(--dim)', fontSize: 10 }}> (~{Number(d.complete_views).toLocaleString()} complete)</span>
                        )}
                      </span>
                    )}
                    {d.likes != null && <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}><LikesIcon size={12} /> {Number(d.likes).toLocaleString()}</span>}
                    {d.comments != null && <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}><CommentsIcon size={12} /> {Number(d.comments).toLocaleString()}</span>}
                    {d.shares != null && <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}><SharesIcon size={12} /> {Number(d.shares).toLocaleString()}</span>}
                    {d.engagement_rate != null && <span style={{ color: 'var(--orange)' }}>{d.engagement_rate}% ER</span>}
                    {d.completion_pct != null && (
                      <span style={{ color: completionColor(d.completion_pct), fontWeight: 600 }}>◑ {d.completion_pct}% completion</span>
                    )}
                  </div>
                </div>
              </div>
            )}

            {d.completion_pct != null && (
              <div style={{ marginBottom: 12 }}>
                <h3 className="detail-section-title" style={{ marginBottom: 8 }}>RETENTION</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6, fontSize: 12 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <span className="text-muted" style={{ width: 120, flexShrink: 0 }}>Avg Completion</span>
                    <div style={{ flex: 1, height: 3, background: 'var(--surface2)', borderRadius: 2 }}>
                      <div style={{ width: `${Math.min(d.completion_pct, 100)}%`, height: '100%', background: completionColor(d.completion_pct), borderRadius: 2 }} />
                    </div>
                    <span style={{ width: 40, textAlign: 'right', fontWeight: 600, color: completionColor(d.completion_pct) }}>{d.completion_pct}%</span>
                  </div>
                  {d.average_time_watched != null && d.video_duration != null && (
                    <div style={{ color: 'var(--muted)', paddingLeft: 130 }}>
                      {Math.round(d.average_time_watched)}s avg watch · {Math.round(d.video_duration)}s total
                    </div>
                  )}
                  {d.full_video_watched_rate != null && (
                    <div style={{ color: 'var(--muted)', paddingLeft: 130 }}>
                      {(d.full_video_watched_rate * 100).toFixed(1)}% watched to end
                    </div>
                  )}
                  {d.complete_views != null && (
                    <div style={{ paddingLeft: 130 }}>
                      <span className="text-muted">Complete views: </span>
                      <span style={{ fontWeight: 500 }}>~{Number(d.complete_views).toLocaleString()}</span>
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="flex gap-16 mb-12" style={{ fontSize: 12, flexWrap: 'wrap' }}>
              <div><span className="text-muted">Due: </span><span style={{ fontWeight: 500 }}>{fmtDate(d.contracted_post_date)}</span></div>
              {d.draft_status_id === scheduledId && d.scheduled_post_at && (
                <div><span className="text-muted">Scheduled: </span><span style={{ color: 'var(--sky)', fontWeight: 500 }}>{fmtDate(d.scheduled_post_at.split('T')[0])} {new Date(d.scheduled_post_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span></div>
              )}
              {d.actual_post_date && <div><span className="text-muted">Posted: </span><span style={{ color: 'var(--green)' }}>{fmtDate(d.actual_post_date)}</span></div>}
              {d.post_url && <button type="button" className="link text-sm" style={{ cursor: 'pointer' }} onClick={() => openPopup(d.post_url)}>View Post <ExternalLinkIcon size={11} style={{ marginLeft: 3, verticalAlign: '-1px' }} /></button>}
            </div>
            {d.zernio_error && d.draft_status_id === scheduledId && (
              <Feedback className="mb-10" value={{ tone: 'error', title: 'Scheduling error', body: d.zernio_error }} />
            )}

            <div style={{ marginBottom: 10 }}>
              <h3 className="detail-section-title" style={{ marginBottom: 8 }}>REVISION ROUNDS</h3>
              {(!d.revision_rounds || d.revision_rounds.length === 0) && (
                <EmptyState variant="note" text="No drafts submitted yet." />
              )}
              {d.revision_rounds?.toSorted((a, b) => a.round_number - b.round_number).map(r => (
                <div key={r.id} className="revision-round">
                  <div className="revision-round-header">
                    <span className="round-number">Round {r.round_number}</span>
                    {/* The decision is stated in GREY, deliberately. It is not a
                        `status_options` value, and drawing it through <Badge> made it borrow
                        whichever group carried the same word. The colour a reader needs is
                        already on screen one level up: both revision modals write the
                        deliverable's `draft_status_id` FROM this field, and that pill sits in
                        this card's header painted from the live row. A round line is HISTORY,
                        so colouring it repeats the header for the latest round and shouts
                        about earlier rounds that are settled. The colour this decision does
                        earn is in the creator blocks below, which take `.feedback` tones.
                        @see docs/DESIGN.md */}
                    {isAdmin ? (
                      <div className="flex items-center gap-8">
                        <button className="btn btn-ghost btn-sm" style={{ fontSize: 11, padding: '2px 8px' }}
                          onClick={() => setEditingRevision({ ...r, deliverable_id: d.id })}>Edit</button>
                        <button className="btn btn-ghost btn-sm" style={{ fontSize: 11, padding: '2px 8px', color: 'var(--red)' }}
                          onClick={() => deleteRevision(r)}>Delete</button>
                        <span className="badge badge-neutral">{r.agency_decision}</span>
                      </div>
                    ) : (
                      <span className="badge badge-neutral">{r.agency_decision}</span>
                    )}
                  </div>
                  {r.submitted_at && <div className="text-sm text-muted">Submitted {fmtDate(localYMD(new Date(r.submitted_at)))}</div>}
                  {r.draft_url && <button type="button" className="link text-sm" style={{ cursor: 'pointer' }} onClick={() => openPopup(r.draft_url)}>View Draft <ExternalLinkIcon size={11} style={{ marginLeft: 3, verticalAlign: '-1px' }} /></button>}
                  {r.draft_notes && <div className="text-sm mt-4">{r.draft_notes}</div>}
                  {isAdmin && r.agency_feedback && (
                    <div className="mt-8" style={{ background: 'var(--surface)', padding: '8px 10px', borderRadius: 4, fontSize: 12 }}>
                      <span className="text-muted">Agency feedback: </span>{r.agency_feedback}
                    </div>
                  )}
                  {isAdmin && r.agency_response_date && <div className="text-sm text-muted mt-4">Response: {fmtDate(r.agency_response_date)}</div>}
                  {!isAdmin && r.agency_decision === 'Revisions Requested' && r.agency_feedback && (
                    <Feedback className="mt-8" value={{ tone: 'info', title: 'Feedback from agency', body: r.agency_feedback }} />
                  )}
                  {!isAdmin && r.agency_decision === 'Pending' && d.draft_status_id !== postedId && d.draft_status_id !== scheduledId && (
                    <div className="mt-8">
                      <button
                        className="btn btn-secondary btn-sm"
                        style={{ color: 'var(--green)' }}
                        disabled={confirmingApproval === r.id}
                        onClick={() => confirmAgencyApproval(r.id)}
                      >
                        {confirmingApproval === r.id ? 'Confirming…' : '✓ Agency Approved This'}
                      </button>
                    </div>
                  )}
                  {!isAdmin && r.agency_decision === 'Approved' && (
                    <Feedback className="mt-8" value={{ tone: 'success', body: r.agency_feedback || null,
                      title: `Approved${r.agency_response_date ? ` on ${fmtDate(r.agency_response_date)}` : ''}` }} />
                  )}
                </div>
              ))}
            </div>

            <div className="flex gap-8" style={{ flexWrap: 'wrap' }}>
              {isAdmin ? (
                <>
                  <button className="btn btn-secondary btn-sm" onClick={() => setShowAddRevision(d)}>+ Add Round</button>
                  {d.draft_status_id !== postedId && d.draft_status_id !== scheduledId && (
                    <button className="btn btn-secondary btn-sm" onClick={() => setShowMarkPosted(d)}>Mark posted…</button>
                  )}
                  {(d.draft_status_id === approvedId || d.draft_status_id === scheduledId) && (
                    <button className="btn btn-secondary btn-sm" style={{ color: 'var(--sky)' }} onClick={() => setShowSchedulePost(d)}>
                      {d.draft_status_id === scheduledId ? '◷ Reschedule' : '◷ Schedule Post'}
                    </button>
                  )}
                  {d.draft_status_id === scheduledId && (
                    <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => cancelScheduledPost(d)}>Cancel schedule…</button>
                  )}
                </>
              ) : (
                <>
                  {canSubmitDraft && (
                    <button className="btn btn-primary btn-sm" onClick={() => setShowSubmitDraft(d)}>Submit Draft</button>
                  )}
                  {d.draft_status_id === approvedId && (
                    <button className="btn btn-secondary btn-sm" style={{ color: 'var(--sky)' }} onClick={() => setShowSchedulePost(d)}>◷ Schedule Post</button>
                  )}
                  {d.draft_status_id === scheduledId && (
                    <>
                      {d.zernio_error && (
                        <button className="btn btn-secondary btn-sm" style={{ color: 'var(--orange2)' }} onClick={() => setShowSchedulePost(d)}>Retry Schedule</button>
                      )}
                      <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => cancelScheduledPost(d)}>Cancel schedule…</button>
                    </>
                  )}
                  {d.draft_status_id !== scheduledId && (
                    <button className="btn btn-secondary btn-sm" onClick={() => setShowLinkVideo(d)}>
                      {d.post_url ? 'Change Video' : 'Link Posted Video'}
                    </button>
                  )}
                  {(d.draft_status_id === approvedId || d.draft_status_id === postedId) && !d.post_url && (
                    <button className="btn btn-secondary btn-sm" onClick={() => setShowCreatorMarkPosted(d)}>Mark posted…</button>
                  )}
                  {d.draft_status_id === postedId && d.post_url && (
                    <span className="text-sm" style={{ color: 'var(--green)', padding: '5px 0' }}>✓ Posted</span>
                  )}
                </>
              )}
            </div>
          </div>
        );
      })}

      {isAdmin && (
        <div style={{ marginTop: 12 }}>
          <button className="btn btn-secondary btn-sm" onClick={() => setShowAddDeliverable(true)}>+ Add Platform</button>
        </div>
      )}

      {isAdmin && showAddDeliverable && (
        <AddDeliverableModal campaignId={campaign.id} platforms={platforms} deliverableTypes={deliverableTypes} lookupErrors={lookupErrors} onRetryLookups={onRetryLookups}
          onClose={() => setShowAddDeliverable(false)} onSaved={() => { setShowAddDeliverable(false); onUpdated(); }} />
      )}
      {isAdmin && showAddRevision && (
        <AddRevisionModal deliverable={showAddRevision} isAdmin={true}
          onClose={() => setShowAddRevision(null)} onSaved={() => { setShowAddRevision(null); onUpdated(); }} />
      )}
      {isAdmin && showMarkPosted && (
        <MarkPostedModal deliverable={showMarkPosted} campaign={campaign}
          onClose={() => setShowMarkPosted(null)} onSaved={() => { setShowMarkPosted(null); onUpdated(); }} />
      )}
      {isAdmin && editingDeliverable && (
        <EditDeliverableModal deliverable={editingDeliverable} campaign={campaign} platforms={platforms} deliverableTypes={deliverableTypes} lookupErrors={lookupErrors} onRetryLookups={onRetryLookups}
          onClose={() => setEditingDeliverable(null)} onSaved={() => { setEditingDeliverable(null); onUpdated(); }} />
      )}
      {isAdmin && editingRevision && (
        <EditRevisionModal revision={editingRevision}
          onClose={() => setEditingRevision(null)} onSaved={() => { setEditingRevision(null); onUpdated(); }} />
      )}
      {!isAdmin && showSubmitDraft && (
        <CreatorSubmitDraftModal deliverable={showSubmitDraft}
          onClose={() => setShowSubmitDraft(null)} onSaved={() => { setShowSubmitDraft(null); onUpdated(); }} />
      )}
      {!isAdmin && showLinkVideo && (
        <CreatorLinkVideoModal deliverable={showLinkVideo} campaign={campaign}
          onClose={() => setShowLinkVideo(null)} onSaved={() => { setShowLinkVideo(null); onUpdated(); }} />
      )}
      {!isAdmin && showCreatorMarkPosted && (
        <CreatorMarkPostedModal deliverable={showCreatorMarkPosted} campaign={campaign}
          onClose={() => setShowCreatorMarkPosted(null)} onSaved={() => { setShowCreatorMarkPosted(null); onUpdated(); }} />
      )}
      {showSchedulePost && (
        <SchedulePostPanel deliverable={showSchedulePost} campaign={campaign}
          onClose={() => setShowSchedulePost(null)} onSaved={() => { setShowSchedulePost(null); onUpdated(); }} />
      )}
    </div>
  );
}

