/**
 * Admin modal: edit a revision round.
 * @gotcha the agency_decision also drives the parent deliverable's draft status
 *         via statusMap (Pending->Draft Submitted, Approved->Approved,
 *         Revisions Requested->Revisions Requested).
 */
function EditRevisionModal({ revision, onClose, onSaved }) {
  const toast = useToast();
  const { options: statusOptions } = useStatusOptions();
  const deliverableOptions = statusOptions.deliverable || [];
  const [form, setForm] = useState({
    round_number: revision.round_number || 1,
    // The LOCAL day of the stored instant, not a UTC slice of it: the write below stores the
    // local midnight of the day picked, and a UTC slice of that is the day before east of UTC.
    submitted_at: revision.submitted_at ? localYMD(new Date(revision.submitted_at)) : '',
    draft_url: revision.draft_url || '',
    draft_notes: revision.draft_notes || '',
    agency_decision: revision.agency_decision || 'Pending',
    agency_feedback: revision.agency_feedback || '',
    agency_response_date: revision.agency_response_date || '',
  });
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState('');

  async function save() {
    setFormError('');
    const errors = [];
    if (form.submitted_at && !isValidDateString(form.submitted_at)) errors.push('Submitted date is not a valid date.');
    if (form.agency_response_date && !isValidDateString(form.agency_response_date)) errors.push('Agency response date is not a valid date.');
    if (form.draft_url && !isValidUrl(form.draft_url)) errors.push('Draft URL is not a valid URL.');
    // @invariant an agency cannot answer a draft it has not been shown. `chk_revision_rounds_dates`
    //            bounds each column on its own and says nothing about their order, so this and
    //            the field's own `min` are the only two guards. ISO YYYY-MM-DD sorts lexically.
    if (form.submitted_at && form.agency_response_date && form.agency_response_date < form.submitted_at) errors.push('Agency response date cannot be before the submitted date.');
    if (errors.length) { setFormError(errors.join(' ')); return; }
    setSaving(true);
    await supabase.from('revision_rounds').update({
      round_number: parseInt(form.round_number) || revision.round_number,
      submitted_at: form.submitted_at ? parseLocalDate(form.submitted_at).toISOString() : null,
      draft_url: form.draft_url || null, draft_notes: form.draft_notes || null,
      agency_decision: form.agency_decision, agency_feedback: form.agency_feedback || null,
      agency_response_date: form.agency_response_date || null,
    }).eq('id', revision.id);
    const statusMap = { 'Pending': 'Draft Submitted', 'Approved': 'Approved', 'Revisions Requested': 'Revisions Requested' };
    const dsText = statusMap[form.agency_decision] || 'Draft Submitted';
    const { error } = await mutate(supabase.from('campaign_deliverables').update({ draft_status_id: deliverableOptions.find(o => o.value === dsText)?.id || null }).eq('id', revision.deliverable_id));
    if (error) { setSaving(false); toast.error(error); return; }
    toast.success('Revision saved');
    setSaving(false); onSaved();
  }

  return (
    <Modal
      title={<>EDIT ROUND {revision.round_number}</>}
      titleStyle={{ fontSize: 18 }}
      size="md"
      onClose={onClose}
    >
        <div className="modal-body">
          {formError && <Feedback value={formError} style={{ marginBottom: 12 }} />}
          <div className="form-row">
            <Field label="Round #">{(id) => (<>
<input id={id} className="form-input" type="number" min={1} value={form.round_number} onChange={e => setForm(f => ({ ...f, round_number: e.target.value }))} />
            </>)}</Field>
            <Field label="Submitted Date">{(id) => (<>
<input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={form.submitted_at} onChange={e => setForm(f => ({ ...f, submitted_at: e.target.value }))} />
            </>)}</Field>
          </div>
          <Field label="Draft URL">{(id) => (<>
<input id={id} className="form-input" value={form.draft_url} onChange={e => setForm(f => ({ ...f, draft_url: e.target.value }))} placeholder="https://..." />
          </>)}</Field>
          <Field label="Notes">{(id) => (<>
<textarea id={id} className="form-textarea" value={form.draft_notes} onChange={e => setForm(f => ({ ...f, draft_notes: e.target.value }))} style={{ minHeight: 60 }} />
          </>)}</Field>
          <Field label="Agency Decision">{(id) => (<>
            <select id={id} className="form-select" value={form.agency_decision} onChange={e => setForm(f => ({ ...f, agency_decision: e.target.value }))}>
              <option>Pending</option><option>Approved</option><option>Revisions Requested</option>
            </select>
          </>)}</Field>
          {form.agency_decision !== 'Pending' && (
            <>
              <Field label="Agency Response Date">{(id) => (<>
<input id={id} className="form-input" type="date" min={form.submitted_at || DB_DATE_MIN} max={DB_DATE_MAX} value={form.agency_response_date} onChange={e => setForm(f => ({ ...f, agency_response_date: e.target.value }))} />
              </>)}</Field>
              <Field label="Agency Feedback">{(id) => (<>
<textarea id={id} className="form-textarea" value={form.agency_feedback} onChange={e => setForm(f => ({ ...f, agency_feedback: e.target.value }))} style={{ minHeight: 60 }} />
              </>)}</Field>
            </>
          )}
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={save} disabled={saving}>Save Changes</SubmitButton>
        </div>
    </Modal>
  );
}

