/**
 * components/shared/CampaignName.js: the two-line campaign cell.
 *
 * Headline = the campaign's display name ("YTK Media x Mys - JVKE - her (feat.
 * ZVC)"), muted second line = its date.
 *
 * @gotcha The date line is not decoration. A display name carries no date, so
 *         several deals with the same agency and creator share one headline and
 *         the date is the only thing separating them. Do not drop it to save a
 *         row of height.
 * @see utils/campaignLabel.js
 */
import React from 'react';
import { campaignLabelParts } from '../../utils/campaignLabel';

/**
 * @param {object} props
 * @param {object|string} props.campaign - the campaign row (or an embed of it).
 */
export default function CampaignName({ campaign }) {
  const { label, date } = campaignLabelParts(campaign);
  return (
    <>
      {/* title carries the full name for the long ones the 2-line clamp cuts. */}
      <div className="campaign-cell-label" title={label}>{label}</div>
      {date && <div className="text-muted text-xs">{date}</div>}
    </>
  );
}
