/**
 * components/shared/HelpView.js: the in-app Help reader.
 *
 * Renders the help corpus (from helpRegistry) with react-markdown@8 + remark-gfm.
 * Two states in one .page shell: library list and article reader. Screenshots
 * load from the private help-screenshots bucket via 1h signed URLs.
 *
 * @gotcha custom link scheme: a `manual:<slug>` href navigates within Help
 *         (transformLinkUri is identity so the scheme survives); only http(s)
 *         external links are allowed. Blockquotes starting with `NOTE:` / `WARN:`
 *         render as ledger-note / warning callouts (classifyBlockquote).
 * @security only http(s) external URLs render as links; anything else is inert.
 * @see components/shared/helpRegistry.js, CLAUDE.md (Help System)
 */
import React, { useState, useEffect, useMemo, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { byCategory, getArticle, search } from './helpRegistry';
import { supabase } from '../../lib/supabase';
import { NoteIcon, WarningIcon } from './Icon';
import EmptyState from './EmptyState';

// In-memory cache of signed URLs. Keyed by storage path. Each entry has
// the URL plus an expiry timestamp; we refresh proactively at 55 minutes.
const signedUrlCache = new Map();
const SIGNED_TTL_SECONDS = 3600;
async function getSignedScreenshotUrl(path) {
  const now = Date.now();
  const hit = signedUrlCache.get(path);
  if (hit && hit.expiresAt > now) return hit.url;
  const { data, error } = await supabase.storage
    .from('help-screenshots')
    .createSignedUrl(path, SIGNED_TTL_SECONDS);
  if (error || !data || !data.signedUrl) return null;
  signedUrlCache.set(path, { url: data.signedUrl, expiresAt: now + (SIGNED_TTL_SECONDS - 300) * 1000 });
  return data.signedUrl;
}

function HelpScreenshot({ path, alt }) {
  const [src, setSrc] = useState(() => signedUrlCache.get(path)?.url || null);
  const [hide, setHide] = useState(false);
  useEffect(() => {
    // Reset on every path change. The previous URL belonged to a different
    // screenshot (e.g. the lightbox re-uses one HelpScreenshot instance and
    // flips path as the user navigates) and must not be reused.
    let alive = true;
    setHide(false);
    const cached = signedUrlCache.get(path);
    if (cached && cached.url) {
      setSrc(cached.url);
      return () => { alive = false; };
    }
    setSrc(null);
    getSignedScreenshotUrl(path).then((u) => {
      if (!alive) return;
      if (!u) setHide(true);
      else setSrc(u);
    });
    return () => { alive = false; };
  }, [path]);
  if (hide) return null;
  if (!src) return <span className="help-article-img-loading" role="status" aria-live="polite">Loading screenshot…</span>;
  return <img src={src} alt={alt || ''} loading="lazy" className="help-article-img" onError={() => setHide(true)} />;
}

// Rendered in place of a run of 2+ adjacent screenshot images. Shows a
// thumbnail row; clicking a thumbnail opens the lightbox at that index with
// keyboard prev/next/escape support.
function HelpScreenshotGroup({ items }) {
  const [openIdx, setOpenIdx] = useState(null);
  useEffect(() => {
    if (openIdx === null) return undefined;
    const onKey = (e) => {
      if (e.key === 'Escape')     setOpenIdx(null);
      else if (e.key === 'ArrowRight') setOpenIdx((i) => (i + 1) % items.length);
      else if (e.key === 'ArrowLeft')  setOpenIdx((i) => (i - 1 + items.length) % items.length);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [openIdx, items.length]);
  return (
    <>
      <div className="help-screenshot-row" data-count={items.length}>
        {items.map((it, i) => (
          <button
            key={i}
            type="button"
            className="help-screenshot-thumb"
            onClick={() => setOpenIdx(i)}
            aria-label={`Open screenshot ${i + 1} of ${items.length}`}
          >
            <HelpScreenshot path={it.path} alt={it.alt} />
          </button>
        ))}
      </div>
      {openIdx !== null && (
        <HelpScreenshotLightbox
          items={items}
          index={openIdx}
          onClose={() => setOpenIdx(null)}
          onPrev={() => setOpenIdx((i) => (i - 1 + items.length) % items.length)}
          onNext={() => setOpenIdx((i) => (i + 1) % items.length)}
        />
      )}
    </>
  );
}

function HelpScreenshotLightbox({ items, index, onClose, onPrev, onNext }) {
  const item = items[index];
  const stop = (e) => e.stopPropagation();
  return (
    <div className="help-lightbox-overlay" onClick={onClose} role="dialog" aria-modal="true">
      <button type="button" className="help-lightbox-close" onClick={onClose} aria-label="Close">×</button>
      {items.length > 1 && (
        <button type="button" className="help-lightbox-nav help-lightbox-prev"
                onClick={(e) => { stop(e); onPrev(); }} aria-label="Previous screenshot">‹</button>
      )}
      <div className="help-lightbox-image" onClick={stop}>
        <HelpScreenshot path={item.path} alt={item.alt} />
      </div>
      {items.length > 1 && (
        <button type="button" className="help-lightbox-nav help-lightbox-next"
                onClick={(e) => { stop(e); onNext(); }} aria-label="Next screenshot">›</button>
      )}
      {items.length > 1 && (
        <div className="help-lightbox-count">{index + 1} / {items.length}</div>
      )}
    </div>
  );
}

// Split body markdown into chunks: regular markdown blocks vs. runs of 2+
// adjacent image-only lines (which become a gallery group). Blank lines
// between two adjacent image lines do not break the run.
function splitBodyIntoChunks(body) {
  const IMG_RE = /^!\[([^\]]*)\]\(([^)]+)\)\s*$/;
  const lines = body.split('\n');
  const chunks = [];
  let mdLines = [];
  let i = 0;
  while (i < lines.length) {
    // Scan forward across image-only and blank lines.
    const imgs = [];
    let j = i;
    let lastImgLine = -1;
    while (j < lines.length) {
      const t = lines[j].trim();
      if (t === '') { j++; continue; }
      const m = t.match(IMG_RE);
      if (!m) break;
      imgs.push({ alt: m[1], src: m[2] });
      lastImgLine = j;
      j++;
    }
    if (imgs.length >= 2) {
      if (mdLines.length > 0) { chunks.push({ type: 'md', md: mdLines.join('\n') }); mdLines = []; }
      chunks.push({ type: 'gallery', items: imgs });
      i = lastImgLine + 1;
    } else {
      mdLines.push(lines[i]);
      i++;
    }
  }
  if (mdLines.length > 0) chunks.push({ type: 'md', md: mdLines.join('\n') });
  return chunks;
}

// Help system v3.
// Lives inside the standard `.page` shell. No second sidebar. Two states:
// library list (when nothing is open) and article reader (when a slug is
// active). Type scale matches the rest of the app (see App.css `.help-*`).

const slugify = (s) =>
  String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');

function extractH2s(body) {
  const lines = (body || '').split('\n');
  const out = [];
  for (const line of lines) {
    const m = line.match(/^##\s+(.+?)\s*$/);
    if (m) out.push({ text: m[1], id: slugify(m[1]) });
  }
  return out;
}

function previewSentence(body) {
  const lines = (body || '').split('\n');
  for (const line of lines) {
    const t = line.trim();
    if (!t) continue;
    if (t.startsWith('#') || t.startsWith('---') || t.startsWith('>') || t.startsWith('!')) continue;
    return t.length > 160 ? t.slice(0, 160).trimEnd() + '…' : t;
  }
  return '';
}

function classifyBlockquote(children) {
  let leading = '';
  const walk = (n) => {
    if (typeof n === 'string') { leading += n; return; }
    if (Array.isArray(n)) { n.forEach((c) => { if (leading.length < 8) walk(c); }); return; }
    if (n && n.props && n.props.children) walk(n.props.children);
  };
  walk(children);
  const stripped = leading.trimStart();
  if (stripped.startsWith('NOTE:')) return { kind: 'ledger',  label: 'Ledger note' };
  if (stripped.startsWith('WARN:')) return { kind: 'warning', label: 'Heads up' };
  return { kind: 'note', label: null };
}

function stripLeadingSigil(children, sigil) {
  const arr = React.Children.toArray(children);
  for (let i = 0; i < arr.length; i++) {
    const node = arr[i];
    if (node && node.props && node.props.children != null) {
      const inner = React.Children.toArray(node.props.children);
      for (let j = 0; j < inner.length; j++) {
        if (typeof inner[j] === 'string' && inner[j].trimStart().startsWith(sigil)) {
          inner[j] = inner[j].replace(sigil, '').replace(/^\s+/, '');
          arr[i] = React.cloneElement(node, {}, ...inner);
          return arr;
        }
      }
    }
  }
  return arr;
}

function ArticleBody({ body, onNavigate, slug, audience }) {
  const folder = audience === 'creator' ? 'creator' : 'manual';
  const resolveImg = (src) => {
    if (!src) return src;
    if (src.startsWith('./screenshots/')) {
      return `${folder}/${slug}/${src.slice('./screenshots/'.length)}`;
    }
    return src;
  };
  const chunks = useMemo(() => splitBodyIntoChunks(body || ''), [body]);

  const markdownComponents = {
    a: ({ href, children }) => {
      const raw = href || '';
      if (raw.startsWith('manual:')) {
        const targetSlug = raw.slice('manual:'.length);
        return (
          <button type="button" onClick={() => onNavigate(targetSlug)} className="help-link help-link-btn">
            {children}
          </button>
        );
      }
      let safe = null;
      try {
        const u = new URL(raw);
        if (u.protocol === 'http:' || u.protocol === 'https:') safe = raw;
      } catch (_e) { /* ignore */ }
      if (!safe) return <span className="help-link-bad">{children}</span>;
      return <a className="help-link" href={safe} target="_blank" rel="noopener noreferrer">{children}</a>;
    },
    h2: ({ children }) => {
      const text = React.Children.toArray(children).filter((c) => typeof c === 'string').join(' ');
      return <h2 id={slugify(text)}>{children}</h2>;
    },
    h3: ({ children }) => {
      const text = React.Children.toArray(children).filter((c) => typeof c === 'string').join(' ');
      return <h3 id={slugify(text)}>{children}</h3>;
    },
    blockquote: ({ children }) => {
      const { kind, label } = classifyBlockquote(children);
      const inner = kind === 'ledger'  ? stripLeadingSigil(children, 'NOTE:')
                   : kind === 'warning' ? stripLeadingSigil(children, 'WARN:')
                   : children;
      const LabelIcon = kind === 'ledger' ? NoteIcon : kind === 'warning' ? WarningIcon : null;
      return (
        <aside className={`help-callout help-callout_${kind}`}>
          {label && (
            <div className="help-callout-label" style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              {LabelIcon && <LabelIcon size={13} />} {label}
            </div>
          )}
          <div className="help-callout-body">{inner}</div>
        </aside>
      );
    },
    img: ({ src, alt }) => {
      const path = resolveImg(src);
      if (!path || (path && path.startsWith && path.startsWith('http'))) {
        return <img src={path} alt={alt || ''} loading="lazy" className="help-article-img" />;
      }
      // Single images get the same thumbnail + click-to-zoom treatment as
      // galleries. Otherwise a tall panel screenshot at 560px still eats
      // most of the viewport and pushes the article text below the fold.
      return <HelpScreenshotGroup items={[{ path, alt }]} />;
    },
  };

  return (
    <>
      {chunks.map((chunk, i) => {
        if (chunk.type === 'gallery') {
          const items = chunk.items.map((it) => ({ path: resolveImg(it.src), alt: it.alt }));
          return <HelpScreenshotGroup key={`g-${i}`} items={items} />;
        }
        const md = chunk.md.replace(/([^\n])\n([^\n])/g, '$1  \n$2');
        return (
          <ReactMarkdown
            key={`m-${i}`}
            remarkPlugins={[remarkGfm]}
            transformLinkUri={(url) => url}
            components={markdownComponents}
          >
            {md}
          </ReactMarkdown>
        );
      })}
    </>
  );
}

/**
 * The Help view shell: search + category chips + library list, or the article
 * reader (with in-article jump rail, related links, prev/next) when a slug is open.
 *
 * @param {'admin'|'creator'} [props.audience='admin']
 * @param {string|null} [props.initialSlug] - open this article on mount.
 * @param {{label:string}|null} [props.returnView] - shows a "Back to {label}" link.
 */
export default function HelpView({ audience = 'admin', initialSlug = null, returnView = null, onBack }) {
  const groups = useMemo(() => byCategory(audience), [audience]);
  const [activeSlug, setActiveSlug] = useState(initialSlug);
  const [query, setQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState('all');
  const articleRef = useRef(null);

  useEffect(() => { if (initialSlug) setActiveSlug(initialSlug); }, [initialSlug]);
  useEffect(() => { if (articleRef.current) articleRef.current.scrollIntoView({ block: 'start', behavior: 'auto' }); }, [activeSlug]);

  const article = activeSlug ? getArticle(activeSlug, audience) : null;
  const flatList = useMemo(() => groups.flatMap((g) => g.articles), [groups]);
  const idx = flatList.findIndex((a) => a.slug === activeSlug);
  const prev = idx > 0 ? flatList[idx - 1] : null;
  const next = idx >= 0 && idx < flatList.length - 1 ? flatList[idx + 1] : null;
  const h2s = useMemo(() => (article ? extractH2s(article.body) : []), [article]);

  const navigateTo = (slug) => { if (getArticle(slug, audience)) setActiveSlug(slug); };
  const backToLibrary = () => setActiveSlug(null);

  const categoryLabel = (key) => groups.find((g) => g.key === key)?.label || key;

  const libraryArticles = useMemo(() => {
    if (query.trim()) return search(query, audience);
    if (activeCategory === 'all') return flatList;
    const g = groups.find((gg) => gg.key === activeCategory);
    return g ? g.articles : [];
  }, [query, activeCategory, audience, flatList, groups]);

  return (
    <div className="page help-page">
      {returnView && onBack ? (
        <button type="button" className="help-return-link" onClick={onBack}>
          <span className="help-return-arrow" aria-hidden="true">‹</span>
          Back to {returnView.label}
        </button>
      ) : null}
      <div className="page-header help-page-header">
        <div>
          <h1 className="page-title">HELP</h1>
          <div className="page-subtitle">
            Reference for the Nysterys hub. {flatList.length} {flatList.length === 1 ? 'article' : 'articles'}.
          </div>
        </div>
        <div className="help-search-wrap">
          <input
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search articles"
            maxLength={120}
            className="form-input help-search-input"
            aria-label="Search help articles"
          />
        </div>
      </div>

      {!article && (
        <div className="help-categories">
          <CategoryChip active={activeCategory === 'all'} onClick={() => setActiveCategory('all')}>All</CategoryChip>
          {groups.map((g) => (
            <CategoryChip key={g.key} active={activeCategory === g.key} onClick={() => setActiveCategory(g.key)}>
              {g.label}
            </CategoryChip>
          ))}
        </div>
      )}

      {article ? (
        <div className="help-layout">
          <article className="help-article" ref={articleRef}>
            <button type="button" className="help-breadcrumb" onClick={backToLibrary}>
              <span className="help-breadcrumb-arrow" aria-hidden="true">‹</span>
              Help library
            </button>
            <div className="help-article-eyebrow">{categoryLabel(article.category)}</div>
            <h1 className="help-article-title">{article.title}</h1>
            {article.lastReviewed && (
              <div className="help-article-meta">
                Last reviewed <span className="help-article-meta-date">{article.lastReviewed}</span>
              </div>
            )}
            <div className={`help-article-body help-article-body_${audience}`}>
              <ArticleBody body={article.body} onNavigate={navigateTo} slug={article.slug} audience={audience} />
            </div>
          </article>

          <aside className="help-rail">
            {h2s.length > 0 && (
              <div className="help-rail-section">
                <div className="help-rail-label">In this article</div>
                <ul className="help-rail-list">
                  {h2s.map((h) => (
                    <li key={h.id}>
                      <a className="help-rail-jump" href={`#${h.id}`}>{h.text}</a>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {article.related && article.related.length > 0 && (
              <div className="help-rail-section">
                <div className="help-rail-label">Related</div>
                <ul className="help-rail-list">
                  {article.related.map((slug) => {
                    const r = getArticle(slug, audience);
                    if (!r) return null;
                    return (
                      <li key={slug}>
                        <button className="help-rail-jump" type="button" onClick={() => navigateTo(slug)}>{r.title}</button>
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}
            {(prev || next) && (
              <div className="help-rail-section help-rail-pagination">
                {prev && (
                  <button type="button" className="help-rail-pn" onClick={() => navigateTo(prev.slug)}>
                    <span className="help-rail-pn-label">Previous</span>
                    <span className="help-rail-pn-title">{prev.title}</span>
                  </button>
                )}
                {next && (
                  <button type="button" className="help-rail-pn" onClick={() => navigateTo(next.slug)}>
                    <span className="help-rail-pn-label">Next</span>
                    <span className="help-rail-pn-title">{next.title}</span>
                  </button>
                )}
              </div>
            )}
          </aside>
        </div>
      ) : (
        <div className="help-library">
          {libraryArticles.length === 0 ? (
            <EmptyState
              title="Nothing found"
              text="Try a different search term or category." />
          ) : (
            libraryArticles.map((a) => (
              <button
                key={a.slug}
                type="button"
                className="help-library-row"
                onClick={() => navigateTo(a.slug)}
              >
                <span className="help-library-row-cat">{categoryLabel(a.category)}</span>
                <span className="help-library-row-body">
                  <span className="help-library-row-title">{a.title}</span>
                  <span className="help-library-row-snippet">{previewSentence(a.body)}</span>
                </span>
              </button>
            ))
          )}
        </div>
      )}
    </div>
  );
}

function CategoryChip({ active, onClick, children }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={active ? 'help-cat help-cat_active' : 'help-cat'}
    >{children}</button>
  );
}
