/**
 * utils/invoicePdfModel.js - single source for invoice PDF data.
 *
 * Both the on-screen preview (InvoicePreviewModal) and the stored issued PDF
 * (invoiceDocuments.generateAndUploadIssuedInvoice) build their
 * { row, invoice, data } from here, then render the SAME
 * components/shared/pdf/InvoicePDF.
 *   - fetchInvoicePdfData({ campaignId, creatorProfileId }) -> the `data` bag,
 *     used directly by the modal (which already knows the ids).
 *   - buildInvoicePdfModel(invoiceId) -> { row, invoice, data } for ANY invoice,
 *     campaign or reward; used by the stored-PDF generator.
 *
 * @invariant both paths share this builder so the saved file can never drift
 *            from the preview the user approved.
 * @see docs/MONEY.md (invoices), components/shared/pdf/InvoicePDF.js
 */
import { supabase } from '../lib/supabase';
import { extractTikTokMusicId } from './format';
import { isOriginalSoundLabel } from './originalSound.generated';

/**
 * Map business_profile (the FROM source of truth) into the legacy `sender` shape
 * the renderer + preview consume.
 * @gotcha invoice_sender was dropped; this mapping is the only place
 *         that knows the old field names, so every caller emits an identical
 *         FROM block.
 */
function mapSender(bp) {
  if (!bp) return null;
  return {
    company_name:   bp.legal_name,
    street_address: bp.street_address,
    city:           bp.city,
    state_province: bp.state_province,
    postal_code:    bp.postal_code,
    country:        bp.country,
    tax_id:         bp.ein,
    email:          bp.contact_email,
    phone:          bp.contact_phone,
  };
}

async function fetchPaymentAddresses(creatorProfileId) {
  if (!creatorProfileId) return [];
  const { data, error } = await supabase
    .from('platform_payment_addresses')
    .select('method, address, fields, label, is_preferred, platform_account:platform_accounts!inner(profile_id, platform)')
    .eq('platform_account.profile_id', creatorProfileId)
    .order('sort_order');
  // This is the remit-to block: WHERE the agency sends the money. A failed read falling
  // through `data || []` renders an invoice with no payment details on it, which is a
  // document asking to be paid with no way to pay it.
  if (error) throw error;
  return data || [];
}

/**
 * Resolve TikTok music metadata for the deliverables that carry a music_url.
 * @gotcha keys on the extracted numeric music id when available, else the raw
 *         url; "original sound" tracks are normalised to the label "Original
 *         sound" rather than the raw track string.
 */
async function fetchMusicMap(deliverables) {
  const musicLookupKeys = [...new Set(
    deliverables.filter(d => d.music_url)
      .map(d => extractTikTokMusicId(d.music_url) || d.music_url)
  )];
  const musicMap = {};
  if (musicLookupKeys.length === 0) return musicMap;
  // Deliberately best-effort, unlike every other read in this module: a track
  // name DECORATES a line item, it is not a term of the invoice, so a failed
  // lookup drops the track and still bills the right amount to the right party.
  // Do not "fix" this into a throw; that would refuse an invoice over a missing
  // sound name.
  const { data: ytRows } = await supabase
    .from('yt_dlp_metadata')
    .select('video_id, raw')
    .in('video_id', musicLookupKeys)
    .not('raw', 'is', null);
  for (const m of ytRows || []) {
    const isOriginal = isOriginalSoundLabel(m.raw?.track);
    musicMap[m.video_id] = {
      artist: m.raw?.artist || m.raw?.music_author || null,
      track:  isOriginal ? 'Original sound' : (m.raw?.track || null),
    };
  }
  return musicMap;
}

/**
 * Fold the campaign's agent onto the agency row as contact_name / email.
 *
 * An agency has several agents (agency_contacts); the one this campaign was
 * signed with is the person the invoice addresses. Resolving here, rather than
 * in the renderer, keeps InvoicePDF + InvoicePreviewModal on their original
 * single-contact contract so the stored PDF cannot drift from the preview.
 *
 * @gotcha this does NOT beat agencies.billing_contact_name, which InvoicePDF
 *         still prefers. Billing is occasionally a different person entirely:
 *         Sweet Records' agent is Cannelle but invoices bill Danny at un:hurd.
 * @param {object} agencyRow agencies row, with a `contacts` embed
 * @param {object|null} agent the campaign's agency_contacts row, if any
 * @returns {object} agency row with contact_name/email resolved to the agent
 */
function withAgent(agencyRow, agent) {
  if (!agencyRow?.id) return agencyRow || {};
  // No agent on the campaign (agency added its contacts after the deal) falls
  // back to the agency's primary, which is who the mail would go to anyway.
  const who = agent || (agencyRow.contacts || []).find(c => c.is_primary) || null;
  const { contacts, ...rest } = agencyRow;
  if (!who) return rest;
  return {
    ...rest,
    contact_name: who.name  || rest.contact_name,
    email:        who.email || rest.email,
    phone:        who.phone || rest.phone,
  };
}

/**
 * The `data` bag for a campaign invoice. The one query set and shaping for both surfaces,
 * so the live preview and the stored PDF render from the exact same inputs.
 */
export async function fetchInvoicePdfData({ campaignId, creatorProfileId }) {
  const [campaignRes, creatorRes, delivRes, senderRes, platformAcctsRes] = await Promise.all([
    // @security an RPC, not an embed. The contact and billing columns on `agencies`, and
    //           `agency_contacts` entirely, are unreadable by `authenticated`, or either
    //           creator reads every agency's contact email, phone, billing address and VAT
    //           number. An admin holds the same role, so a column GRANT cannot tell them
    //           apart; this returns the identical shape an embed would.
    //           @see schemas/SCHEMA.sql, get_campaign_invoice_agency
    supabase.rpc('get_campaign_invoice_agency', { p_campaign_id: campaignId }),
    supabase.from('profiles')
      .select('id, full_name, creator_name, email')
      .eq('id', creatorProfileId).maybeSingle(),
    supabase.from('campaign_deliverables')
      .select('*, platform:platforms(name), type:deliverable_types(name)')
      .eq('campaign_id', campaignId)
      .order('contracted_post_date'),
    supabase.from('business_profile')
      .select('legal_name, ein, street_address, city, state_province, postal_code, country, contact_email, contact_phone')
      .eq('is_active', true).maybeSingle(),
    supabase.from('platform_accounts')
      .select('platform, username, display_name')
      .eq('profile_id', creatorProfileId)
      .eq('is_active', true),
  ]);

  // check-unchecked-reads.mjs matches a single-line destructure and cannot see a
  // Promise.all, so these five are on their own. delivRes is the invoice's LINE ITEMS:
  // a refused read falling through `|| []` produces a document billing an agency for
  // nothing, with a blank Bill To and no sender.
  const failed = [campaignRes, creatorRes, delivRes, senderRes, platformAcctsRes].find(r => r.error);
  if (failed) throw failed.error;

  const deliverables   = delivRes.data || [];
  const delivPlatforms = new Set(deliverables.map(d => d.platform?.name?.toLowerCase()).filter(Boolean));
  const allAccts       = platformAcctsRes.data || [];
  const platformAccts  = allAccts.filter(a => delivPlatforms.has(a.platform?.toLowerCase()));
  const musicMap       = await fetchMusicMap(deliverables);
  const paymentAddresses = await fetchPaymentAddresses(creatorProfileId);

  return {
    agency:           withAgent(campaignRes.data?.agencies, campaignRes.data?.agency_contact),
    creator:          creatorRes.data || {},
    sender:           mapSender(senderRes.data),
    deliverables,
    musicMap,
    paymentAddresses,
    platformAccts,
  };
}

/**
 * Build { row, invoice, data } for any invoice id, campaign OR reward.
 *
 * @param {string} invoiceId
 * @returns {Promise<{row, invoice, data}>}
 * @throws when the invoice has neither campaign_id nor reward_entry_id.
 * @gotcha reward invoices have no campaign/agency/deliverables: the program name
 *         stands in for the campaign label, there is no third-party Bill To, and
 *         Talent falls back to the creator handle. Data mapping only; the visual
 *         layout is identical to a campaign invoice.
 */
export async function buildInvoicePdfModel(invoiceId) {
  const { data: invoice, error: invErr } = await supabase
    .from('invoices').select('*').eq('id', invoiceId).maybeSingle();
  if (invErr || !invoice) throw invErr || new Error('Invoice not found');

  if (invoice.campaign_id) {
    const { data: campaign, error: campErr } = await supabase
      .from('campaigns')
      .select('id, campaign_name, brand_name, contracted_rate, creator_profile_id, creator:profiles!campaigns_creator_profile_id_fkey(creator_name, full_name)')
      .eq('id', invoice.campaign_id).maybeSingle();
    // Every field below falls back to '' or null, so a failed read rendered an
    // invoice with a blank campaign, brand and talent name rather than failing.
    if (campErr) throw campErr;

    const data = await fetchInvoicePdfData({
      campaignId: invoice.campaign_id,
      creatorProfileId: campaign?.creator_profile_id,
    });

    const row = {
      campaign_id:     invoice.campaign_id,
      campaign_name:   campaign?.campaign_name || '',
      brand_name:      campaign?.brand_name || '',
      contracted_rate: campaign?.contracted_rate ?? null,
      creator_name:    campaign?.creator?.creator_name || campaign?.creator?.full_name || '',
    };
    return { row, invoice, data };
  }

  if (invoice.reward_entry_id) {
    const { data: entry, error: entryErr } = await supabase
      .from('platform_reward_entries')
      .select('id, gross_amount, profile_id, program:platform_rewards_programs(name, platform:platforms(name)), profile:profiles!platform_reward_entries_profile_id_fkey(creator_name, full_name)')
      .eq('id', invoice.reward_entry_id).maybeSingle();
    if (entryErr) throw entryErr;

    const { data: bp, error: bpErr } = await supabase
      .from('business_profile')
      .select('legal_name, ein, street_address, city, state_province, postal_code, country, contact_email, contact_phone')
      .eq('is_active', true).maybeSingle();
    // The FROM block: legal name and EIN. mapSender(null) returns null and the
    // renderer prints nothing, so a failed read produced an unsigned invoice.
    if (bpErr) throw bpErr;

    const programName = entry?.program?.name || '';
    const data = {
      agency:           {},                              // platform reward: no third-party bill-to
      creator:          entry?.profile || {},
      sender:           mapSender(bp),
      deliverables:     [],
      musicMap:         {},
      paymentAddresses: await fetchPaymentAddresses(entry?.profile_id),
      platformAccts:    [],
    };
    const row = {
      campaign_id:     null,
      campaign_name:   programName,
      brand_name:      programName,
      contracted_rate: entry?.gross_amount ?? null,
      creator_name:    entry?.profile?.creator_name || entry?.profile?.full_name || '',
    };
    return { row, invoice, data };
  }

  throw new Error('Invoice has neither campaign_id nor reward_entry_id');
}
