/**
 * components/shared/CalendarPage.js. Deliverable and expense schedule calendar (admin + creator).
 *
 * One shared month/week calendar. Admin (isAdmin=true, profileId=null) sees every creator with
 * a filter and per-creator colour coding; creator (isAdmin=false, profileId=<uuid>) sees only
 * their own RLS-scoped deliverables with no filter. Both roles may move a MOVABLE deliverable
 * (not Posted, not Zernio-Scheduled), which writes ONLY contracted_post_date. The move is
 * optimistic, proves itself against the row it reads back, and reverts with a toast if not.
 *
 * Three routes reach that one write: drag a chip onto a day, pick a chip up and click or tap
 * the day, or pick it up and use the `Move to` field in the banner, which is the only route
 * without a pointer and the only one that reaches a date the grid on screen does not show.
 *
 * @security canReschedule is true for both roles and ownership is enforced by the DB, not the
 *           UI: RLS scopes the visible row set and `restrict_creator_deliverable_columns` is an
 *           allow list, so a column missing from it is locked by default. That guard REVERTS
 *           rather than raising, which is why `moveDeliverable` proves its write landed.
 * @gotcha Posted deliverables render on actual_post_date and Scheduled ones on
 *         scheduled_post_at, NOT contracted_post_date; only contracted-date rows are movable.
 * @gotcha format(date,'yyyy-MM-dd') is the canonical date key everywhere; never build a Date
 *         from a 'YYYY-MM-DD' string (UTC midnight shifts to the prior day in US zones).
 * @see docs/CODEBASE.md (RLS and forward triggers, date parsing)
 */
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { supabase } from '../../lib/supabase';
import { ExternalLinkIcon, DragHandleIcon, ScheduledIcon } from './Icon';
import { useCreators } from '../../hooks/useCreators';
import { useEscapeKey } from '../../hooks/useEscapeKey';
import Badge from './Badge';
import { useToast } from './Toast';
import { humanizeError } from '../../utils/errors';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { resolveStatusRow } from '../../utils/statusRow';
import { activationProps } from '../../utils/rowActivation';
import { format, parseISO, startOfMonth, endOfMonth, startOfWeek, endOfWeek, addDays, addWeeks, addMonths, subWeeks, subMonths, isSameDay, isSameMonth, isToday } from 'date-fns';
import { DB_DATE_MIN, DB_DATE_MAX } from '../../utils/dbLimits';
import Field from './Field';
import { getOccurrencesInRange, expenseCoverageStatus } from '../../utils/expenses';
import { openPopup } from '../../utils/openPopup';
import { campaignLabel } from '../../utils/campaignLabel';
import ReadError from './ReadError';
import Feedback from './Feedback';
import Modal from './Modal';
import Loading from './Loading';

const CREATOR_PALETTE = ['#60a5fa', '#a78bfa', '#34d399', '#fbbf24', '#f87171', '#38bdf8', '#fb923c', '#4ade80', '#e879f9', '#a3e635'];
const CREATOR_SINGLE  = '#60a5fa'; // used when only one creator's data is shown

const MAX_MONTH_CHIPS = 3;

/**
 * Short chip label: the brand name if present, else the campaign's display name.
 *
 * @param {object} d - the flattened deliverable row (carries brand_name plus the
 *        campaign's display_name / campaign_name).
 * @gotcha A chip has no room for a date, so two same-agency deals with the same
 *         creator read identically here. The day cell the chip sits in is what
 *         separates them. @see utils/campaignLabel.js
 */
function chipLabel(d) {
  return d?.brand_name || campaignLabel(d) || '?';
}

/**
 * One deliverable chip in a day cell or agenda row.
 *
 * @gotcha draggable is gated to canDrag AND not Posted/Scheduled, so a posted or
 *         Zernio-scheduled chip can never be dragged even if the caller passes
 *         draggable. A draggable chip's click toggles selection (tap-to-move);
 *         a non-draggable chip's click opens the detail popup.
 */
function DeliverableChip({ d, color, statusRow, draggable: canDrag, isDragging, onDragStart, onDragEnd, onClick, large, isSelected, onSelect }) {
  const isPosted     = d.draft_status === 'Posted';
  const isScheduled  = d.draft_status === 'Scheduled';
  const draggable    = canDrag && !isPosted && !isScheduled;
  const label        = chipLabel(d);
  const scheduledTime = isScheduled && d.scheduled_post_at
    ? new Date(d.scheduled_post_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    : null;
  const [hovered, setHovered] = React.useState(false);

  function handleClick() {
    if (draggable && onSelect) {
      onSelect(isSelected ? null : d.id);
    } else {
      onClick?.(d);
    }
  }

  return (
    <div
      draggable={draggable}
      onDragStart={draggable ? e => { e.dataTransfer.setData('deliverable_id', d.id); onDragStart?.(d); } : undefined}
      onDragEnd={onDragEnd}
      {...activationProps(handleClick, draggable && onSelect ? { pressed: !!isSelected } : {})}
      onMouseEnter={draggable ? () => setHovered(true) : undefined}
      onMouseLeave={draggable ? () => setHovered(false) : undefined}
      title={[label, d.creator_name, d.platform_name].filter(Boolean).join(' · ')}
      style={{
        padding: large ? '8px 10px' : '4px 8px',
        borderRadius: 5,
        marginBottom: 4,
        cursor: draggable ? 'grab' : 'pointer',
        background: `${color}18`,
        border: isSelected ? '2px solid var(--orange)' : `1px solid ${color}30`,
        borderLeft: isSelected ? '2px solid var(--orange)' : `3px solid ${color}`,
        opacity: isDragging ? 0.4 : 1,
        display: 'flex',
        alignItems: 'center',
        gap: 6,
        userSelect: 'none',
        overflow: 'hidden',
        transition: 'opacity 0.15s, border 0.1s',
        minHeight: large ? 48 : 36,
      }}
    >
      {draggable && (
        <DragHandleIcon size={14} style={{
          color: hovered ? 'var(--white)' : 'var(--muted)',
          transition: 'color 0.12s',
        }} />
      )}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div title={label} style={{ fontWeight: 600, fontSize: large ? 14 : 12, color: 'var(--white)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
          {isScheduled && <ScheduledIcon size={large ? 12 : 10} style={{ marginRight: 4 }} />}{label}
        </div>
        <div title={scheduledTime
            ? [scheduledTime, d.platform_name].filter(Boolean).join(' · ')
            : [d.creator_name, d.platform_name, d.type_name].filter(Boolean).join(' · ')} style={{ fontSize: large ? 12 : 10, color: 'var(--muted)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', marginTop: 1 }}>
          {scheduledTime
            ? [scheduledTime, d.platform_name].filter(Boolean).join(' · ')
            : [d.creator_name, d.platform_name, d.type_name].filter(Boolean).join(' · ')}
        </div>
      </div>
      {statusRow && (
        <span style={{
          fontSize: large ? 11 : 9, fontWeight: 700, flexShrink: 0,
          color: statusRow.text_color, background: `${statusRow.text_color}22`,
          padding: '2px 5px', borderRadius: 3, whiteSpace: 'nowrap',
        }}>
          {statusRow.label}
        </span>
      )}
    </div>
  );
}

/**
 * One recurring/one-time expense occurrence chip. coverageStatus drives the
 * color + label (covered=PAID, partial=PARTIAL, else DUE); isFuture dashes the
 * border for occurrences past today.
 */
function ExpenseChip({ expense, coverageStatus, isFuture, large }) {
  const bg     = coverageStatus === 'covered' ? 'rgba(61,220,132,0.08)' : coverageStatus === 'partial' ? 'rgba(255,140,66,0.08)' : 'rgba(255,92,0,0.06)';
  const color  = coverageStatus === 'covered' ? 'var(--green)' : coverageStatus === 'partial' ? 'var(--orange2)' : 'var(--orange)';
  const label  = coverageStatus === 'covered' ? 'PAID' : coverageStatus === 'partial' ? 'PARTIAL' : 'DUE';
  return (
    <div title={`${expense.name}: ${expense.category}`} style={{
      padding: large ? '8px 10px' : '4px 8px', borderRadius: 5, marginBottom: 4,
      background: bg,
      border: `1px ${isFuture ? 'dashed' : 'solid'} ${color}44`,
      opacity: isFuture ? 0.65 : 1,
      display: 'flex', alignItems: 'center', gap: 6, overflow: 'hidden', minHeight: large ? 44 : 30,
    }}>
      <span style={{ fontSize: large ? 12 : 10, color, fontWeight: 700, flexShrink: 0 }}>$</span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div title={expense.name} style={{ fontWeight: 600, fontSize: large ? 13 : 11, color: 'var(--white)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
          {expense.name}
        </div>
      </div>
      <span style={{ fontSize: large ? 11 : 9, fontWeight: 700, flexShrink: 0, color, background: `${color}22`, padding: '2px 5px', borderRadius: 3 }}>
        {label}
      </span>
    </div>
  );
}

/**
 * The destination half of a move, for a reader who has no pointer.
 *
 * Picking a chip up answers the keyboard already; a day cell cannot, because it holds the chip
 * buttons and a button inside a button is announced as neither. So the banner that appears on
 * pickup carries the destination: one focus stop instead of one per day, and it reaches a date
 * the grid on screen does not show.
 *
 * @gotcha both call sites key this on the chip id. Without that key the field keeps the date
 *         typed for the PREVIOUS pickup, which is a wrong date offered as a default.
 * @gotcha the input holds 'YYYY-MM-DD' and `onMove` takes a Date, so the parse carries the
 *         local-midnight suffix; without it a US zone reads the value as the day before.
 */
function MoveToField({ current, onMove }) {
  const [date, setDate] = useState(current || '');
  return (
    <form onSubmit={e => { e.preventDefault(); if (date) onMove(parseISO(`${date}T00:00:00`)); }}
          style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
      <Field label="Move to" style={{ display: 'flex', alignItems: 'baseline', gap: 10, marginBottom: 0 }}>
        {id => <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={date} onChange={e => setDate(e.target.value)} style={{ width: 'auto' }} />}
      </Field>
      <button type="submit" className="btn btn-primary" disabled={!date}>Move</button>
    </form>
  );
}

/**
 * Calendar page. @see file header for roles, rescheduling rules, and traps.
 *
 * @param {boolean} props.isAdmin - true → all creators + filter; false → own rows.
 * @param {?string} props.profileId - creator's uuid (scopes the fetch); null for admin.
 */
export default function CalendarPage({ isAdmin, profileId }) {
  const toast = useToast();
  // Admins see every campaign; the creator view is RLS-scoped to their own
  // campaigns. Either way every deliverable on screen belongs to the viewer,
  // so both roles may reschedule a movable one (the chip guard still blocks
  // Posted / Zernio-Scheduled, and the DB enforces ownership independently).
  const canReschedule = true;
  const { options: statusOptions, loading: vocabLoading } = useStatusOptions();
  const delivStatuses = statusOptions.deliverable || [];
  // One resolver for every pill in the hub, by ID and inside the deliverable group only. This
  // was the one site that matched on the VALUE, off `d.draft_status`, which is itself derived
  // from the id below; on a miss it drew a padded grey pill with nothing in it, a sixth answer
  // to a question that now has one. @see utils/statusRow.js
  const statusRowFor = d => resolveStatusRow(statusOptions, 'deliverable', { statusId: d.draft_status_id });
  const cancelledCampaignId = (statusOptions.campaign || []).find(o => o.value === 'Cancelled')?.id;

  const [deliverables,       setDeliverables]       = useState([]);
  const [expenses,           setExpenses]           = useState([]);
  const [expenseAllocations, setExpenseAllocations] = useState([]);
  const { creators } = useCreators(isAdmin);
  const [loading, setLoading]           = useState(true);
  const [filterWarning, setFilterWarning] = useState(false);
  // The third state. A blank month is what an empty calendar and a refused one both look
  // like, and the blank month is the answer a creator plans her week against.
  const [loadError, setLoadError]       = useState(null);
  const [showExpenses, setShowExpenses] = useState(true);
  const [view, setView]                 = useState('week');
  const [currentDate, setCurrentDate]   = useState(new Date());
  const [creatorFilter, setCreatorFilter] = useState('all');
  const [statusFilter, setStatusFilter]   = useState('all');
  const [draggingId, setDraggingId]     = useState(null);
  const [dragOverDate, setDragOverDate] = useState(null);
  const [selected, setSelected]         = useState(null);
  const [dayModal, setDayModal]         = useState(null);
  const [edgeActive, setEdgeActive]     = useState(0); // -1 left, 0 none, 1 right
  const [selectedChipId, setSelectedChipId] = useState(null);
  const edgeScrollRef  = useRef(null);
  const edgeIntervalId = useRef(null);

  const stopEdgeScroll = useCallback(() => {
    if (edgeIntervalId.current) {
      clearInterval(edgeIntervalId.current);
      edgeIntervalId.current = null;
    }
    edgeDir.current = 0;
    setEdgeActive(0);
  }, []);

  const edgeDir = useRef(0);
  useEscapeKey(useCallback(() => setSelectedChipId(null), []), !!selectedChipId);
  const [isMobile, setIsMobile] = useState(() => window.innerWidth <= 768);
  const touchStartX = useRef(null);
  const touchStartY = useRef(null);
  const swipeNavRef = useRef(false); // set when a touch ends as a week/month swipe, so the trailing click doesn't also drop a move

  const handleCalendarDragOver = useCallback(e => {
    const rect = edgeScrollRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = e.clientX - rect.left;
    const ZONE = 120;
    let dir = 0;
    if (x < ZONE) dir = -1;
    else if (x > rect.width - ZONE) dir = 1;

    if (dir !== 0 && dir !== edgeDir.current) {
      stopEdgeScroll();
      edgeDir.current = dir;
      setEdgeActive(dir);
      const step = () => setCurrentDate(d => dir > 0
        ? (view === 'month' ? addMonths(d, 1) : addWeeks(d, 1))
        : (view === 'month' ? subMonths(d, 1) : subWeeks(d, 1)));
      edgeIntervalId.current = setInterval(step, 400);
    } else if (dir === 0) {
      stopEdgeScroll();
    }
  }, [view, stopEdgeScroll]);

  // vocabLoading is in the deps because with an empty campaign group the id stays undefined
  // forever, so nothing else here ever changes and the settled case was unreachable. P200.
  useEffect(() => { fetchAll(); }, [cancelledCampaignId, vocabLoading]); // re-fetch once statusOptions loads so the cancelled filter uses the real UUID

  useEffect(() => {
    const mq = window.matchMedia('(max-width: 768px)');
    const handler = e => setIsMobile(e.matches);
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, []);

  /**
   * Load deliverables (+ campaign/creator joins), expenses, and expense-coverage
   * splits in one round-trip batch. Creator scope is applied via profileId; the
   * Cancelled campaign filter waits for statusOptions to resolve the real UUID
   * (see the cancelledCampaignId dep on the calling effect).
   * @gotcha draft_status is resolved client-side from delivStatuses; if this runs
   *         before statusOptions loads it would be null, but the effect re-fetches
   *         on cancelledCampaignId so the second pass has real status values.
   */
  async function fetchAll() {
    setLoadError(null);
    const delivQuery = supabase.from('campaign_deliverables').select(`
      id, contracted_post_date, actual_post_date, draft_status_id, post_url, deliverable_details, quantity, scheduled_post_at,
      platform:platforms(name),
      deliverable_type:deliverable_types(name),
      campaign:campaigns!inner(
        id, campaign_name, display_name, brand_name, status_id, campaign_start_date, campaign_end_date,
        creator:profiles!campaigns_creator_profile_id_fkey(id, full_name, creator_name)
      )
    `);

    let expQuery = supabase.from('expenses').select('*');
    if (profileId) expQuery = expQuery.or(`creator_id.eq.${profileId},creator_id.is.null`);

    let scopedDelivQuery = profileId ? delivQuery.eq('campaign.creator_profile_id', profileId) : delivQuery;
    if (cancelledCampaignId) scopedDelivQuery = scopedDelivQuery.neq('campaign.status_id', cancelledCampaignId);
    // Drawn rather than refused, unlike the shared-dashboard picker: blanking a whole month
    // over one missing status row is worse than the leak it prevents. Not routed through
    // loadError, which empties the grid.
    setFilterWarning(!cancelledCampaignId && !vocabLoading);
    const [delRes, expRes, allocRes] = await Promise.all([
      scopedDelivQuery,
      expQuery,
      supabase.from('payout_splits').select('expense_id, expense_period, amount').not('expense_id', 'is', null),
    ]);

    const readError = delRes.error || expRes.error || allocRes.error;
    if (readError) {
      setLoadError(readError);
      setDeliverables([]);
      setExpenses([]);
      setExpenseAllocations([]);
      setLoading(false);
      return;
    }
    const { data: delData } = delRes;
    const { data: expData } = expRes;
    const { data: allocData } = allocRes;

    const flat = ((delData) || []).map(d => ({
      id:                   d.id,
      contracted_post_date: d.contracted_post_date,
      actual_post_date:     d.actual_post_date,
      scheduled_post_at:    d.scheduled_post_at,
      draft_status_id:      d.draft_status_id,
      draft_status:         delivStatuses.find(s => s.id === d.draft_status_id)?.value || null,
      post_url:             d.post_url,
      deliverable_details:  d.deliverable_details,
      platform_name:        d.platform?.name || '?',
      type_name:            d.deliverable_type?.name || '',
      campaign_id:          d.campaign?.id,
      campaign_name:        d.campaign?.campaign_name || '?',
      display_name:         d.campaign?.display_name || null,
      brand_name:           d.campaign?.brand_name || '',
      creator_id:           d.campaign?.creator?.id,
      creator_name:         d.campaign?.creator?.creator_name || d.campaign?.creator?.full_name || '',
    }));

    setDeliverables(flat);
    setExpenses(expData || []);
    setExpenseAllocations(allocData || []);
    setLoading(false);
  }

  // Creator → color map (admin only; single color for creator view)
  const creatorColorMap = {};
  if (isAdmin) {
    creators.forEach((c, i) => { creatorColorMap[c.id] = CREATOR_PALETTE[i % CREATOR_PALETTE.length]; });
  }
  function chipColor(d) {
    return isAdmin ? (creatorColorMap[d.creator_id] || 'var(--muted)') : CREATOR_SINGLE;
  }

  /**
   * Reschedule a deliverable to newDate, writing ONLY contracted_post_date.
   *
   * Optimistic: the chip moves immediately, then reconciles with the server.
   *
   * @invariant either the toast says it moved AND the row read back holds the new date, or the
   *            chip goes back and the reader is told. There is no third outcome, which is the
   *            rule utils/markPosted.js already states for the same reason.
   * @gotcha the read-back is not padding. `restrict_creator_deliverable_columns` REVERTS a
   *         creator write it does not permit rather than raising, so a refused save returns
   *         error null against a row the database has already restored and is otherwise
   *         indistinguishable from a real one. @see utils/markPosted.js
   */
  async function moveDeliverable(id, newDate) {
    const dateStr  = format(newDate, 'yyyy-MM-dd');
    const prevDate = deliverables.find(d => d.id === id)?.contracted_post_date ?? null;
    if (prevDate === dateStr) return; // dropped on the same day: nothing to do

    // Optimistic: move the chip immediately, reconcile with the server after.
    setDeliverables(prev => prev.map(d => d.id === id ? { ...d, contracted_post_date: dateStr } : d));
    const { data, error } = await supabase
      .from('campaign_deliverables')
      .update({ contracted_post_date: dateStr })
      .eq('id', id)
      .select('id, contracted_post_date');

    const row = (data || [])[0];
    const refused = !error && (!row || row.contracted_post_date !== dateStr);
    if (error || refused) {
      if (process.env.NODE_ENV !== 'production') console.error(error || 'reschedule reverted');
      setDeliverables(prev => prev.map(d => d.id === id ? { ...d, contracted_post_date: prevDate } : d));
      const h = error ? humanizeError(error) : {
        tone: 'error',
        title: "Couldn't move that post",
        body: 'The save came back without your change. Ask Patrick to move it for you.',
      };
      toast[h?.tone || 'error'](h || 'Could not reschedule that post. Try again.');
      return;
    }
    toast.success(`Moved to ${format(newDate, 'MMM d')}`);
  }

  /**
   * Deliverables landing on `date`, after creator + status filters.
   * @gotcha Posted rows key off actual_post_date, Scheduled rows off
   *         scheduled_post_at (date part), everything else off
   *         contracted_post_date, so a deliverable can appear on a different day
   *         than its contracted date once it is posted or Zernio-scheduled.
   */
  function getDeliverablesForDate(date) {
    const dateStr = format(date, 'yyyy-MM-dd');
    return deliverables.filter(d => {
      let postDate;
      if (d.draft_status === 'Posted') postDate = d.actual_post_date;
      else if (d.draft_status === 'Scheduled' && d.scheduled_post_at) postDate = d.scheduled_post_at.split('T')[0];
      else postDate = d.contracted_post_date;
      if (!postDate || postDate !== dateStr) return false;
      if (isAdmin && creatorFilter !== 'all' && d.creator_id !== creatorFilter) return false;
      if (statusFilter !== 'all' && d.draft_status !== statusFilter) return false;
      return true;
    });
  }

  function navigate(dir) {
    if (view === 'month') setCurrentDate(d => dir > 0 ? addMonths(d, 1) : subMonths(d, 1));
    else setCurrentDate(d => dir > 0 ? addWeeks(d, 1) : subWeeks(d, 1));
  }

  const handleTouchStart = e => {
    touchStartX.current = e.touches[0].clientX;
    touchStartY.current = e.touches[0].clientY;
    swipeNavRef.current = false;
  };
  const handleTouchEnd = e => {
    if (touchStartX.current === null) return;
    const dx = touchStartX.current - e.changedTouches[0].clientX;
    const dy = Math.abs(touchStartY.current - e.changedTouches[0].clientY);
    if (Math.abs(dx) > 60 && Math.abs(dx) > dy * 1.5) { navigate(dx > 0 ? 1 : -1); swipeNavRef.current = true; }
    touchStartX.current = null;
  };

  let days = [];
  if (view === 'month') {
    const start = startOfWeek(startOfMonth(currentDate), { weekStartsOn: 0 });
    const end   = endOfWeek(endOfMonth(currentDate), { weekStartsOn: 0 });
    let d = start;
    while (d <= end) { days.push(d); d = addDays(d, 1); }
  } else {
    const start = startOfWeek(currentDate, { weekStartsOn: 0 });
    for (let i = 0; i < 7; i++) days.push(addDays(start, i));
  }

  // Coverage map: expense_id -> { 'YYYY-MM': amount, total: amount }
  const expCoverageMap = React.useMemo(() => {
    const map = {};
    expenseAllocations.forEach(a => {
      if (!a.expense_id) return;
      if (!map[a.expense_id]) map[a.expense_id] = {};
      const key = a.expense_period ? a.expense_period.substring(0, 7) : 'total';
      map[a.expense_id][key] = (map[a.expense_id][key] || 0) + (parseFloat(a.amount) || 0);
    });
    return map;
  }, [expenseAllocations]);

  // 'YYYY-MM-DD' -> [{ expense, isFuture, periodKey, coverageStatus }]
  const expensesByDate = React.useMemo(() => {
    if (!showExpenses || expenses.length === 0) return {};
    let rangeStart, rangeEnd;
    if (view === 'month') {
      rangeStart = startOfWeek(startOfMonth(currentDate), { weekStartsOn: 0 });
      rangeEnd   = endOfWeek(endOfMonth(currentDate),   { weekStartsOn: 0 });
    } else {
      rangeStart = startOfWeek(currentDate, { weekStartsOn: 0 });
      rangeEnd   = addDays(rangeStart, 6);
    }
    const map = {};
    expenses.forEach(exp => {
      getOccurrencesInRange(exp, rangeStart, rangeEnd).forEach(({ date, periodKey, isFuture }) => {
        const key = format(date, 'yyyy-MM-dd');
        if (!map[key]) map[key] = [];
        const covAmt = exp.type === 'one_time'
          ? (expCoverageMap[exp.id]?.total || 0)
          : (expCoverageMap[exp.id]?.[periodKey] || 0);
        map[key].push({ expense: exp, periodKey, isFuture, coverageStatus: expenseCoverageStatus(covAmt, parseFloat(exp.amount)) });
      });
    });
    return map;
  }, [expenses, expCoverageMap, currentDate, view, showExpenses]);

  const isWeek = view === 'week';

  if (loading) return <div className="page"><Loading /></div>;
  if (loadError) return <div className="page"><ReadError error={loadError} onRetry={fetchAll} /></div>;

  // Rendered by both the mobile and the desktop branch, so the two cannot disagree about
  // whether the month on screen is complete.
  const filterNotice = filterWarning ? (
    <Feedback value={{ tone: 'warn', title: 'Cancelled campaigns could not be filtered out', body: 'The status list did not load, so some deliverables here may belong to a cancelled campaign.' }} />
  ) : null;

  // Read once for both branches: the two move banners name the same post and offer the same
  // destination field, so a creator's route on her phone cannot drift from the one on a laptop.
  const movingDeliv = selectedChipId ? deliverables.find(d => d.id === selectedChipId) : null;
  const placeOnDate = date => { moveDeliverable(selectedChipId, date); setSelectedChipId(null); };

  if (isMobile) {
    const moveMode = !!movingDeliv;
    return (
      <div className="page">
        {filterNotice}
        <div className="page-header" style={{ marginBottom: 16 }}>
          <div>
            <h1 className="page-title">CALENDAR</h1>
            <div className="page-subtitle">{isAdmin ? 'Deliverable schedule across all campaigns' : 'Your posting schedule'}</div>
          </div>
        </div>

        {/* Move-mode banner: sticky so it stays in reach while swiping weeks */}
        {moveMode && (
          <div style={{
            position: 'sticky', top: 8, zIndex: 5,
            background: 'var(--orange-glow)',
            border: '1px solid rgba(255,92,0,0.3)',
            borderRadius: 'var(--radius)',
            padding: '10px 14px',
            marginBottom: 14,
            display: 'flex', flexDirection: 'column', gap: 10,
            animation: 'slideDown 0.18s ease',
          }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10 }}>
              <span title={`Moving ${chipLabel(movingDeliv)} · tap a day`} style={{ fontSize: 13, color: 'var(--orange)', minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                Moving <strong style={{ fontWeight: 700 }}>{chipLabel(movingDeliv)}</strong> · tap a day
              </span>
              <button type="button" className="btn btn-ghost btn-sm" onClick={() => setSelectedChipId(null)} style={{ flexShrink: 0, color: 'var(--orange)' }}>Cancel</button>
            </div>
            <MoveToField key={selectedChipId} current={movingDeliv.contracted_post_date} onMove={placeOnDate} />
          </div>
        )}

        {/* Navigation */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
          <button
            className="btn btn-secondary"
            /* The step is a week or a month depending on the view, so a fixed word would be
               wrong half the time. */
            aria-label={isWeek ? 'Previous week' : 'Previous month'}
            onClick={() => navigate(-1)}
            style={{ width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22, flexShrink: 0, padding: 0 }}
          >‹</button>
          <div style={{ flex: 1, textAlign: 'center' }}>
            <div style={{ fontFamily: 'var(--font-display)', fontSize: 20, letterSpacing: '0.08em', color: 'var(--white)', lineHeight: 1.1 }}>
              {isWeek
                ? `${format(days[0], 'MMM d')} - ${format(days[6], 'MMM d, yyyy')}`
                : format(currentDate, 'MMMM yyyy')}
            </div>
          </div>
          <button
            className="btn btn-secondary"
            aria-label={isWeek ? 'Next week' : 'Next month'}
            onClick={() => navigate(1)}
            style={{ width: 44, height: 44, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22, flexShrink: 0, padding: 0 }}
          >›</button>
        </div>

        {/* View + filter controls */}
        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 12, alignItems: 'center' }}>
          {['week', 'month'].map(v => (
            <button key={v} className={`filter-chip ${view === v ? 'active' : ''}`} aria-pressed={view === v} onClick={() => setView(v)}>
              {v.charAt(0).toUpperCase() + v.slice(1)}
            </button>
          ))}
          <button className={`filter-chip ${showExpenses ? 'active' : ''}`} aria-pressed={showExpenses} onClick={() => setShowExpenses(v => !v)}>
            Expenses
          </button>
          <button className="btn btn-ghost btn-sm" onClick={() => setCurrentDate(new Date())}>Today</button>
        </div>

        {/* Dropdowns */}
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 20 }}>
          {isAdmin && (
            <select className="form-select" aria-label="Filter by creator" style={{ flex: 1, minWidth: 140, fontSize: 13 }} value={creatorFilter} onChange={e => setCreatorFilter(e.target.value)}>
              <option value="all">All Creators</option>
              {creators.map(c => <option key={c.id} value={c.id}>{c.creator_name || c.full_name}</option>)}
            </select>
          )}
          <select className="form-select" aria-label="Filter by deliverable status" style={{ flex: 1, minWidth: 140, fontSize: 13 }} value={statusFilter} onChange={e => setStatusFilter(e.target.value)}>
            <option value="all">All Statuses</option>
            {delivStatuses.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
          </select>
        </div>

        {/* Agenda list */}
        <div onTouchStart={handleTouchStart} onTouchEnd={handleTouchEnd} style={{ userSelect: 'none' }}>
          {days.map(day => {
            const items        = getDeliverablesForDate(day);
            const expItems     = expensesByDate[format(day, 'yyyy-MM-dd')] || [];
            const hasItems     = items.length > 0 || expItems.length > 0;
            const todayFlag    = isToday(day);
            const isOtherMonth = !isSameMonth(day, currentDate) && view === 'month';

            const isCurrentDay = moveMode && format(day, 'yyyy-MM-dd') === movingDeliv.contracted_post_date;

            return (
              <div
                key={format(day, 'yyyy-MM-dd')}
                onClick={moveMode ? () => {
                  if (swipeNavRef.current) { swipeNavRef.current = false; return; }
                  moveDeliverable(selectedChipId, day);
                  setSelectedChipId(null);
                } : undefined}
                style={{
                  display: 'flex', gap: 14, alignItems: 'flex-start',
                  marginBottom: moveMode ? 10 : hasItems ? 20 : 0,
                  opacity: isOtherMonth ? 0.35 : 1,
                  cursor: moveMode ? 'pointer' : undefined,
                }}
              >
                {/* Date column */}
                <div style={{ width: 44, flexShrink: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', paddingTop: 4 }}>
                  <span style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.1em', color: todayFlag ? 'var(--orange)' : 'var(--muted)', lineHeight: 1, marginBottom: 4 }}>
                    {format(day, 'EEE')}
                  </span>
                  <span style={{
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    width: 36, height: 36, borderRadius: '50%',
                    background: todayFlag ? 'var(--orange)' : 'transparent',
                    color: todayFlag ? 'var(--black)' : isOtherMonth ? 'var(--dim)' : 'var(--white)',
                    fontSize: 18, fontWeight: 700, lineHeight: 1,
                  }}>
                    {format(day, 'd')}
                  </span>
                </div>

                {/* Items, divider, or move target */}
                <div style={{ flex: 1, minWidth: 0, paddingTop: (hasItems || moveMode) ? 4 : 19 }}>
                  {hasItems && (
                    <>
                      {items.map(d => (
                        <DeliverableChip
                          key={d.id}
                          d={d}
                          color={chipColor(d)}
                          statusRow={statusRowFor(d)}
                          draggable={false}
                          isDragging={false}
                          isSelected={moveMode && d.id === selectedChipId}
                          onClick={moveMode ? undefined : d => setSelected(d)}
                          large
                        />
                      ))}
                      {expItems.map(({ expense, coverageStatus, isFuture }) => (
                        <ExpenseChip
                          key={`${expense.id}-${format(day, 'yyyy-MM-dd')}`}
                          expense={expense}
                          coverageStatus={coverageStatus}
                          isFuture={isFuture}
                          large
                        />
                      ))}
                    </>
                  )}
                  {moveMode ? (
                    !isCurrentDay && (
                      <div style={{
                        border: '1px dashed rgba(255,92,0,0.4)',
                        borderRadius: 6,
                        padding: '11px 12px',
                        marginTop: hasItems ? 6 : 0,
                        fontSize: 12, fontWeight: 600, letterSpacing: '0.04em',
                        color: 'var(--orange)', textAlign: 'center',
                        background: 'rgba(255,92,0,0.05)',
                      }}>
                        Move here
                      </div>
                    )
                  ) : !hasItems && (
                    <div style={{ borderTop: '1px solid var(--border)' }} />
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {/* Detail popup */}
        {selected && (
          <Modal
            title={chipLabel(selected)}
            subtitle={[selected.creator_name, selected.platform_name].filter(Boolean).join(' · ')}
            size="sm"
            modalStyle={{ margin: '0 12px' }}
            onClose={() => setSelected(null)}
          >
              <div className="modal-body">
                <div className="detail-grid">
                  <div><div className="detail-item-label">Status</div><div className="detail-item-value"><Badge group="deliverable" statusId={selected.draft_status_id} status={selected.draft_status} /></div></div>
                  <div><div className="detail-item-label">Type</div><div className="detail-item-value">{selected.type_name || '—'}</div></div>
                  <div><div className="detail-item-label">Planned Date</div><div className="detail-item-value">{selected.contracted_post_date || '—'}</div></div>
                  {selected.actual_post_date && (
                    <div><div className="detail-item-label">Posted</div><div className="detail-item-value" style={{ color: 'var(--green)' }}>✓ {selected.actual_post_date}</div></div>
                  )}
                  {selected.deliverable_details && (
                    <div style={{ gridColumn: 'span 2' }}><div className="detail-item-label">Details</div><div className="detail-item-value">{selected.deliverable_details}</div></div>
                  )}
                  {selected.post_url && (
                    <div style={{ gridColumn: 'span 2' }}><div className="detail-item-label">Post</div><div className="detail-item-value"><button onClick={() => openPopup(selected.post_url)} className="link btn-ghost" style={{ padding: 0, background: 'none', border: 'none', cursor: 'pointer' }}>View Post <ExternalLinkIcon size={11} style={{ marginLeft: 3, verticalAlign: '-1px' }} /></button></div></div>
                  )}
                </div>
              </div>
              {canReschedule && selected.draft_status !== 'Posted' && selected.draft_status !== 'Scheduled' && (
                <div className="modal-footer">
                  <button className="btn btn-primary" onClick={() => { setSelectedChipId(selected.id); setSelected(null); }}>Reschedule</button>
                </div>
              )}
          </Modal>
        )}
      </div>
    );
  }

  return (
    <div className="page">
      {filterNotice}
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">CALENDAR</h1>
          <div className="page-subtitle">{isAdmin ? 'Deliverable schedule across all campaigns' : 'Your posting schedule'}</div>
        </div>
        <div className="flex gap-8 items-center" style={{ flexWrap: 'wrap' }}>
          <div className="flex gap-4" style={{ flexWrap: 'wrap' }}>
            {['week', 'month'].map(v => (
              <button key={v} className={`filter-chip ${view === v ? 'active' : ''}`} aria-pressed={view === v} onClick={() => setView(v)}>
                {v.charAt(0).toUpperCase() + v.slice(1)}
              </button>
            ))}
            <button className={`filter-chip ${showExpenses ? 'active' : ''}`} aria-pressed={showExpenses} onClick={() => setShowExpenses(v => !v)}>
              Expenses
            </button>
          </div>
          {isAdmin && (
            <select className="form-select" aria-label="Filter by creator" style={{ width: 'auto', padding: '5px 10px', fontSize: 12 }} value={creatorFilter} onChange={e => setCreatorFilter(e.target.value)}>
              <option value="all">All Creators</option>
              {creators.map(c => <option key={c.id} value={c.id}>{c.creator_name || c.full_name}</option>)}
            </select>
          )}
          <select className="form-select" aria-label="Filter by deliverable status" style={{ width: 'auto', padding: '5px 10px', fontSize: 12 }} value={statusFilter} onChange={e => setStatusFilter(e.target.value)}>
            <option value="all">All Statuses</option>
            {delivStatuses.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
          </select>
          <div className="flex gap-4 items-center">
            <button className="btn btn-secondary btn-sm" aria-label={isWeek ? 'Previous week' : 'Previous month'} onClick={() => navigate(-1)}>‹</button>
            <span style={{ fontSize: 14, fontWeight: 600, minWidth: 200, textAlign: 'center' }}>
              {isWeek
                ? `${format(days[0], 'MMM d')} - ${format(days[6], 'MMM d, yyyy')}`
                : format(currentDate, 'MMMM yyyy')}
            </span>
            <button className="btn btn-secondary btn-sm" aria-label={isWeek ? 'Next week' : 'Next month'} onClick={() => navigate(1)}>›</button>
            <button className="btn btn-ghost btn-sm" onClick={() => setCurrentDate(new Date())}>Today</button>
          </div>
        </div>
      </div>

      {/* Legend */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 20, marginBottom: 16, flexWrap: 'wrap' }}>
        <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
          {delivStatuses.map(s => (
            <div key={s.value} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12 }}>
              <div style={{ width: 10, height: 10, borderRadius: 3, background: s.text_color, flexShrink: 0 }} />
              <span style={{ color: 'var(--muted)', fontWeight: 500 }}>{s.label}</span>
            </div>
          ))}
        </div>
        {isAdmin && creators.length > 0 && (
          <div style={{ display: 'flex', gap: 14, borderLeft: '1px solid var(--border)', paddingLeft: 16 }}>
            {creators.map((c, i) => (
              <div key={c.id} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12 }}>
                <div style={{ width: 10, height: 10, borderRadius: 3, background: CREATOR_PALETTE[i % CREATOR_PALETTE.length], flexShrink: 0 }} />
                <span style={{ color: 'var(--muted)', fontWeight: 500 }}>{c.creator_name || c.full_name}</span>
              </div>
            ))}
          </div>
        )}
        {canReschedule && (
          <span style={{ fontSize: 11, color: 'var(--dim)', marginLeft: 'auto' }}>Drag unposted deliverables to reschedule</span>
        )}
      </div>

      {/* Move-mode banner: names the post, and carries the destination for a reader with no
          pointer. @see MoveToField */}
      {movingDeliv && (
        <div style={{
          background: 'var(--orange-glow)',
          border: '1px solid rgba(255,92,0,0.3)',
          borderRadius: 'var(--radius)',
          padding: '10px 14px',
          fontSize: 12,
          color: 'var(--orange)',
          marginBottom: 12,
          display: 'flex',
          alignItems: 'center',
          gap: 16,
          flexWrap: 'wrap',
        }}>
          <span title={`Moving ${chipLabel(movingDeliv)}`} style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            Moving <strong style={{ fontWeight: 700 }}>{chipLabel(movingDeliv)}</strong> · click a day
          </span>
          <MoveToField key={selectedChipId} current={movingDeliv.contracted_post_date} onMove={placeOnDate} />
          <button type="button" onClick={() => setSelectedChipId(null)} style={{ background: 'none', border: 'none', color: 'var(--orange)', cursor: 'pointer', fontSize: 12, padding: '0 4px', marginLeft: 'auto' }}>Cancel</button>
        </div>
      )}

      {/* Calendar grid */}
      <div
        ref={edgeScrollRef}
        className="calendar-scroll-wrap"
        style={{ border: '1px solid var(--border)', borderRadius: 8, position: 'relative' }}
        onDragOver={canReschedule ? handleCalendarDragOver : undefined}
        onDragLeave={canReschedule ? stopEdgeScroll : undefined}
      >
        {edgeActive === -1 && (
          <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: 120, zIndex: 10, pointerEvents: 'none', background: 'linear-gradient(to right, rgba(255,92,0,0.18), transparent)', display: 'flex', alignItems: 'center', justifyContent: 'flex-start', paddingLeft: 14, borderRadius: '8px 0 0 8px', animation: 'fadeIn 0.15s ease' }}>
            <span aria-hidden="true" style={{ fontSize: 22, color: 'var(--orange)', opacity: 0.9, animation: 'pulse 0.6s ease-in-out infinite alternate' }}>‹</span>
          </div>
        )}
        {edgeActive === 1 && (
          <div style={{ position: 'absolute', right: 0, top: 0, bottom: 0, width: 120, zIndex: 10, pointerEvents: 'none', background: 'linear-gradient(to left, rgba(255,92,0,0.18), transparent)', display: 'flex', alignItems: 'center', justifyContent: 'flex-end', paddingRight: 14, borderRadius: '0 8px 8px 0', animation: 'fadeIn 0.15s ease' }}>
            <span aria-hidden="true" style={{ fontSize: 22, color: 'var(--orange)', opacity: 0.9, animation: 'pulse 0.6s ease-in-out infinite alternate' }}>›</span>
          </div>
        )}
      <div className="calendar-scroll-inner" style={{ overflow: 'hidden' }}>
        {/* Day headers */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, minmax(0, 1fr))', background: 'var(--surface2)', borderBottom: '1px solid var(--border)' }}>
          {isWeek
            ? days.map((d, i) => {
                const todayCol = isToday(d);
                return (
                  <div key={i} style={{
                    padding: '8px 12px',
                    fontSize: 11, fontWeight: 600, letterSpacing: '0.06em',
                    color: todayCol ? 'var(--orange)' : 'var(--muted)',
                    textTransform: 'uppercase',
                    display: 'flex', flexDirection: 'column', gap: 2,
                  }}>
                    <span>{format(d, 'EEE')}</span>
                    <span style={{ fontSize: 18, fontWeight: 700, letterSpacing: 0, lineHeight: 1, color: todayCol ? 'var(--orange)' : 'var(--white)', opacity: todayCol ? 1 : 0.7 }}>
                      {format(d, 'd')}
                    </span>
                  </div>
                );
              })
            : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((label, i) => (
                <div key={i} style={{ padding: '10px 12px', fontSize: 11, fontWeight: 600, letterSpacing: '0.06em', color: 'var(--muted)', textTransform: 'uppercase' }}>
                  {label}
                </div>
              ))
          }
        </div>

        {/* Day cells */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, minmax(0, 1fr))' }}>
          {days.map((day, i) => {
            const items        = getDeliverablesForDate(day);
            const expItems     = expensesByDate[format(day, 'yyyy-MM-dd')] || [];
            const todayFlag    = isToday(day);
            const isOtherMonth = !isSameMonth(day, currentDate) && view === 'month';
            const isOver       = canReschedule && dragOverDate && isSameDay(dragOverDate, day);
            const allItems     = items.length + expItems.length;
            const chipLimit    = allItems === MAX_MONTH_CHIPS + 1 ? MAX_MONTH_CHIPS + 1 : MAX_MONTH_CHIPS;
            const visible      = isWeek ? items : items.slice(0, chipLimit);
            const expVisible   = isWeek ? expItems : expItems.slice(0, Math.max(0, chipLimit - items.length));
            const overflow     = isWeek ? 0 : Math.max(0, allItems - chipLimit);

            return (
              <div
                key={i}
                onDragOver={canReschedule ? e => { e.preventDefault(); setDragOverDate(day); } : undefined}
                onDragLeave={canReschedule ? () => setDragOverDate(null) : undefined}
                onDrop={canReschedule ? e => {
                  e.preventDefault();
                  stopEdgeScroll();
                  const id = e.dataTransfer.getData('deliverable_id');
                  if (id) moveDeliverable(id, day);
                  setDragOverDate(null);
                  setDraggingId(null);
                } : undefined}
                onClick={canReschedule && selectedChipId ? () => {
                  moveDeliverable(selectedChipId, day);
                  setSelectedChipId(null);
                } : undefined}
                style={{
                  minHeight: isWeek ? 200 : 110,
                  padding: '8px',
                  borderRight: (i + 1) % 7 !== 0 ? '1px solid var(--border)' : 'none',
                  borderBottom: '1px solid var(--border)',
                  background: isOver
                    ? 'rgba(255,92,0,0.08)'
                    : isOtherMonth ? 'rgba(0,0,0,0.18)' : 'transparent',
                  cursor: canReschedule && selectedChipId ? 'crosshair' : undefined,
                  transition: 'background 0.1s',
                }}
              >
                {/* Date number */}
                <div style={{ marginBottom: 8 }}>
                  {todayFlag ? (
                    <span style={{
                      display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                      background: 'var(--orange)', color: 'var(--black)', borderRadius: '50%',
                      width: isWeek ? 32 : 24, height: isWeek ? 32 : 24,
                      fontSize: isWeek ? 15 : 12, fontWeight: 700,
                    }}>
                      {format(day, 'd')}
                    </span>
                  ) : (
                    <span style={{ fontSize: isWeek ? 15 : 12, fontWeight: 500, color: isOtherMonth ? 'var(--dim)' : 'var(--muted)' }}>
                      {format(day, 'd')}
                    </span>
                  )}
                  {allItems > 0 && (
                    <span style={{ fontSize: 9, background: 'var(--surface3)', color: 'var(--muted)', borderRadius: 8, padding: '1px 5px', marginLeft: 5 }}>
                      {allItems}
                    </span>
                  )}
                </div>

                {/* Chips */}
                {visible.map(d => (
                  <DeliverableChip
                    key={d.id}
                    d={d}
                    color={chipColor(d)}
                    statusRow={statusRowFor(d)}
                    draggable={canReschedule}
                    isDragging={draggingId === d.id}
                    onDragStart={d => setDraggingId(d.id)}
                    onDragEnd={() => { setDraggingId(null); stopEdgeScroll(); }}
                    onClick={d => setSelected(d)}
                    isSelected={selectedChipId === d.id}
                    onSelect={setSelectedChipId}
                  />
                ))}

                {expVisible.map(({ expense, coverageStatus, isFuture }) => (
                  <ExpenseChip key={`${expense.id}-${format(day, 'yyyy-MM-dd')}`} expense={expense} coverageStatus={coverageStatus} isFuture={isFuture} />
                ))}

                {overflow > 0 && (
                  <button
                    onClick={() => setDayModal({ date: day, items: [...items, ...expItems.map(ei => ({ ...ei.expense, _isExpense: true, _coverageStatus: ei.coverageStatus, _isFuture: ei.isFuture }))] })}
                    style={{ fontSize: 10, color: 'var(--muted)', background: 'var(--surface3)', border: '1px solid var(--border2)', borderRadius: 3, cursor: 'pointer', padding: '2px 7px', fontWeight: 600, width: '100%', textAlign: 'center', marginTop: 2 }}
                  >
                    +{overflow} more
                  </button>
                )}
              </div>
            );
          })}
        </div>
      </div>
      </div>

      {/* Day overflow modal */}
      {dayModal && (
        <Modal
          title={format(dayModal.date, 'EEEE, MMMM d')}
          size="sm"
          onClose={() => setDayModal(null)}
        >
            <div className="modal-body">
              {dayModal.items.map(d => d._isExpense ? (
                <ExpenseChip key={`exp-${d.id}`} expense={d} coverageStatus={d._coverageStatus} isFuture={d._isFuture} />
              ) : (
                <DeliverableChip
                  key={d.id}
                  d={d}
                  color={chipColor(d)}
                  statusRow={statusRowFor(d)}
                  draggable={false}
                  isDragging={false}
                  onClick={d => { setDayModal(null); setSelected(d); }}
                />
              ))}
            </div>
        </Modal>
      )}

      {/* Detail popup */}
      {selected && (
        <Modal
          title={chipLabel(selected)}
          subtitle={[selected.creator_name, selected.platform_name].filter(Boolean).join(' · ')}
          size="sm"
          onClose={() => setSelected(null)}
        >
            <div className="modal-body">
              <div className="detail-grid">
                <div><div className="detail-item-label">Status</div><div className="detail-item-value"><Badge group="deliverable" statusId={selected.draft_status_id} status={selected.draft_status} /></div></div>
                <div><div className="detail-item-label">Type</div><div className="detail-item-value">{selected.type_name || '—'}</div></div>
                <div><div className="detail-item-label">Planned Date</div><div className="detail-item-value">{selected.contracted_post_date || '—'}</div></div>
                {selected.actual_post_date && (
                  <div><div className="detail-item-label">Posted</div><div className="detail-item-value" style={{ color: 'var(--green)' }}>✓ {selected.actual_post_date}</div></div>
                )}
                {selected.deliverable_details && (
                  <div style={{ gridColumn: 'span 2' }}><div className="detail-item-label">Details</div><div className="detail-item-value">{selected.deliverable_details}</div></div>
                )}
                {selected.post_url && (
                  <div style={{ gridColumn: 'span 2' }}><div className="detail-item-label">Post</div><div className="detail-item-value"><button onClick={() => openPopup(selected.post_url)} className="link btn-ghost" style={{ padding: 0, background: 'none', border: 'none', cursor: 'pointer' }}>View Post <ExternalLinkIcon size={11} style={{ marginLeft: 3, verticalAlign: '-1px' }} /></button></div></div>
                )}
              </div>
            </div>
        </Modal>
      )}
    </div>
  );
}
