/**
 * components/shared/InvoiceLock.js. Shared primitives and data layer that mirror the field-lock
 * triggers in the UI: prevent_invoice_trigger_field_mutation,
 * prevent_split_trigger_field_mutation and prevent_payout_trigger_field_mutation.
 *
 * Any editor that touches a row a trigger may reject must probe ledger_journal_entries for
 * unreversed JEs on the source row, disable the trigger-protected inputs while a JE is live and
 * offer an in-place reverse path (LockedField / CheckboxLock), render <PostedEntries /> so
 * admins see what is posted, and wire <ReverseEntryModal />, refetching JEs and reloading the
 * row on success.
 *
 * Used by PaymentsPage InvoiceForm, RewardsPage EntryForm and RewardInvoiceForm, the shared
 * PayoutForm, and CampaignsPage InvoiceTab (read-only snapshot).
 *
 * @gotcha do not reintroduce inline copies of the JE-probe regex or the lock UI primitives;
 *         centralising them here keeps every editor in lockstep with the trigger contract.
 * @see docs/CODEBASE.md (trigger and RLS mechanism), docs/MONEY.md
 */
import React, { useCallback, useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { fmtDate } from '../../utils/format';
import LockIcon from './LockIcon';

/**
 * Fetch unreversed JEs for the given source rows with their decorated lines
 * (account_code/account_name joined in). Feeds ReverseEntryModal without an
 * extra round-trip when the user clicks Reverse.
 *
 * @param {string} sourceType - 'invoice' | 'payout' | 'split'
 * @param {string[]} sourceIds
 * @returns {Promise<{entry: object, lines: object[]}[]>}
 * @throws the raw Supabase error when any of the three reads is refused. Every caller must
 *         catch it and report, because the alternative is an empty list that reads as
 *         "nothing is posted here".
 */
export async function fetchJournalEntriesWithLines(sourceType, sourceIds) {
  const ids = (sourceIds || []).filter(Boolean);
  if (ids.length === 0) return [];
  const { data: entries, error: entriesErr } = await supabase
    .from('ledger_journal_entries')
    .select('*')
    .eq('source_type', sourceType)
    .in('source_id', ids)
    .is('reversed_by_je_id', null);
  // Throws rather than returning [], for the reason useRewardEntryJournalEntries already
  // says below: [] means "nothing is posted", and that is the answer that unlocks every
  // trigger-protected field and enables Cancel on a campaign whose AR entry is live. A
  // refused read is not evidence that nothing posted.
  if (entriesErr) throw entriesErr;
  if (!entries || entries.length === 0) return [];
  const { data: lines, error: linesErr } = await supabase
    .from('ledger_entry_lines')
    .select('*')
    .in('journal_entry_id', entries.map((e) => e.id));
  if (linesErr) throw linesErr;
  const accIds = [...new Set((lines || []).map((l) => l.account_id))];
  const { data: accs, error: accsErr } = accIds.length
    ? await supabase.from('ledger_accounts').select('id, code, name, normal_balance').in('id', accIds)
    : { data: [], error: null };
  if (accsErr) throw accsErr;
  const accMap = new Map((accs || []).map((a) => [a.id, a]));
  return entries.map((e) => ({
    entry: e,
    lines: (lines || [])
      .filter((l) => l.journal_entry_id === e.id)
      .map((l) => {
        const a = accMap.get(l.account_id);
        return { ...l, account_code: a?.code, account_name: a?.name };
      }),
  }));
}

/**
 * Description-prefix probes that match the invoice/payout JE branches.
 *
 * @gotcha these regexes are the contract with the JE descriptions the triggers
 *         write (AR/In-kind invoice, Cash received, Payout for). Centralised
 *         here so they live in one place and never drift between call sites;
 *         never re-inline them. If a trigger renames a JE description, update here.
 */
export const findArJe     = (jes) => (jes || []).find((j) => /^(AR invoice|In-kind invoice)/i.test(j.entry?.description || ''));
export const findCashJe   = (jes) => (jes || []).find((j) => /^Cash received/i.test(j.entry?.description || ''));
export const findPayoutJe = (jes) => (jes || []).find((j) => /^Payout for/i.test(j.entry?.description || ''));

/**
 * Hook for editors that load a single invoice. Returns the unreversed JEs + the
 * two derived locks (arJe, cashJe). `refetch` is what callers call after a
 * successful reverse so lock icons disappear without a full re-mount.
 */
export function useInvoiceJournalEntries(invoiceId) {
  const [invoiceJes, setInvoiceJes] = useState([]);
  const [loading, setLoading] = useState(false);
  // The raw error, for a caller to hand to <ReadError />. Non-null means the locks below are
  // UNKNOWN, not open: arJe and cashJe are null on a failed probe exactly as they are on an
  // unposted invoice, so a caller that ignores this renders an editable form over a posted one.
  const [error, setError] = useState(null);

  const refetch = useCallback(async () => {
    if (!invoiceId) { setInvoiceJes([]); setError(null); return; }
    setLoading(true);
    setError(null);
    try {
      setInvoiceJes(await fetchJournalEntriesWithLines('invoice', [invoiceId]));
    } catch (e) {
      setInvoiceJes([]);
      setError(e);
    }
    setLoading(false);
  }, [invoiceId]);

  useEffect(() => {
    let cancelled = false;
    if (!invoiceId) { setInvoiceJes([]); setError(null); setLoading(false); return undefined; }
    setLoading(true);
    setError(null);
    fetchJournalEntriesWithLines('invoice', [invoiceId]).then((r) => {
      if (cancelled) return;
      setInvoiceJes(r);
      setLoading(false);
    }, (e) => {
      if (cancelled) return;
      setInvoiceJes([]);
      setError(e);
      setLoading(false);
    });
    return () => { cancelled = true; };
  }, [invoiceId]);

  return { invoiceJes, arJe: findArJe(invoiceJes), cashJe: findCashJe(invoiceJes), loading, error, refetch };
}

/**
 * Same probe as useInvoiceJournalEntries, addressed by the reward_entry_id that
 * owns the invoice. EntryForm / RewardInvoiceForm load the invoice via the FK;
 * this hook hides the two-step join.
 */
export function useRewardEntryJournalEntries(rewardEntryId) {
  const [invoiceJes, setInvoiceJes] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const fetchOnce = useCallback(async () => {
    if (!rewardEntryId) return [];
    const { data: inv, error } = await supabase
      .from('invoices').select('id').eq('reward_entry_id', rewardEntryId).maybeSingle();
    // Returning [] here means "no posted entry", which UNLOCKS every field this
    // module exists to seal. A read failure is not evidence that nothing posted.
    if (error) throw error;
    if (!inv?.id) return [];
    return fetchJournalEntriesWithLines('invoice', [inv.id]);
  }, [rewardEntryId]);

  const refetch = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      setInvoiceJes(await fetchOnce());
    } catch (e) {
      setInvoiceJes([]);
      setError(e);
    }
    setLoading(false);
  }, [fetchOnce]);

  useEffect(() => {
    let cancelled = false;
    if (!rewardEntryId) { setInvoiceJes([]); setError(null); setLoading(false); return undefined; }
    setLoading(true);
    setError(null);
    // Both arms bound. fetchOnce already threw on a refused invoice lookup, and with only the
    // success arm the rejection escaped as an unhandled promise: nothing set the error, and
    // `loading` stayed true forever behind a form that had already decided nothing was posted.
    fetchOnce().then((r) => {
      if (cancelled) return;
      setInvoiceJes(r);
      setLoading(false);
    }, (e) => {
      if (cancelled) return;
      setInvoiceJes([]);
      setError(e);
      setLoading(false);
    });
    return () => { cancelled = true; };
  }, [rewardEntryId, fetchOnce]);

  return { invoiceJes, arJe: findArJe(invoiceJes), cashJe: findCashJe(invoiceJes), loading, error, refetch };
}

/**
 * Same probe shape as useInvoiceJournalEntries but addressed by the
 * creator_payouts.id that owns the Pattern E JE (DR 511x Creator Payouts,
 * CR 21xx Payable). The shared PayoutForm uses this to lock
 * payout_date / profile_id / campaign_id / reward_entry_id in lockstep with
 * prevent_payout_trigger_field_mutation.
 *
 * @see docs/MONEY.md Pattern E
 */
export function usePayoutJournalEntries(payoutId) {
  const [payoutJes, setPayoutJes] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const refetch = useCallback(async () => {
    if (!payoutId) { setPayoutJes([]); setError(null); return; }
    setLoading(true);
    setError(null);
    try {
      setPayoutJes(await fetchJournalEntriesWithLines('payout', [payoutId]));
    } catch (e) {
      setPayoutJes([]);
      setError(e);
    }
    setLoading(false);
  }, [payoutId]);

  useEffect(() => {
    let cancelled = false;
    if (!payoutId) { setPayoutJes([]); setError(null); setLoading(false); return undefined; }
    setLoading(true);
    setError(null);
    fetchJournalEntriesWithLines('payout', [payoutId]).then((r) => {
      if (cancelled) return;
      setPayoutJes(r);
      setLoading(false);
    }, (e) => {
      if (cancelled) return;
      setPayoutJes([]);
      setError(e);
      setLoading(false);
    });
    return () => { cancelled = true; };
  }, [payoutId]);

  return { payoutJes, payoutJe: findPayoutJe(payoutJes), loading, error, refetch };
}

/**
 * Wraps a disabled input/select with an in-field lock icon. Clicking it opens
 * ReverseEntryModal for the JE that locked the field. Renders the child
 * untouched when je is null so callers keep one render path.
 *
 * @gotcha the `.locked-field` class is load bearing, not decoration. A locked field is
 *         `disabled`, and `.form-input:disabled` is written for a control that is
 *         UNAVAILABLE: muted text at 70% opacity. A locked one is the opposite case, holding
 *         a posted, final and usually load-bearing figure, so the class restores full
 *         strength text and leaves the dimmed ground, the dimmed border and this chip to say
 *         it cannot be typed in. Without it the one real number on a row renders fainter
 *         than every editable field beside it and reads as placeholder text.
 */
export function LockedField({ je, onReverse, tooltip = 'Locked. Click to reverse the posted entry.', children }) {
  if (!je) return children;
  return (
    <div className="locked-field" style={{ position: 'relative' }}>
      {children}
      <button
        type="button"
        onClick={() => onReverse(je)}
        title={tooltip}
        aria-label={tooltip}
        style={{
          position: 'absolute', right: 6, top: '50%', transform: 'translateY(-50%)',
          background: 'color-mix(in oklab, var(--orange) 10%, transparent)', border: '1px solid color-mix(in oklab, var(--orange) 35%, transparent)',
          borderRadius: 4, cursor: 'pointer', color: 'var(--orange)',
          fontSize: 12, lineHeight: 1, padding: '4px 6px',
          display: 'inline-flex', alignItems: 'center',
        }}
      ><LockIcon size={12} /></button>
    </div>
  );
}

/** Inline lock chip for checkbox rows where the in-field icon pattern doesn't fit. */
export function CheckboxLock({ je, onReverse, tooltip = 'Locked. Click to reverse the posted entry.' }) {
  if (!je) return null;
  return (
    <button
      type="button"
      onClick={() => onReverse(je)}
      title={tooltip}
      aria-label={tooltip}
      style={{
        marginLeft: 8, background: 'color-mix(in oklab, var(--orange) 10%, transparent)',
        border: '1px solid color-mix(in oklab, var(--orange) 35%, transparent)', borderRadius: 4,
        cursor: 'pointer', color: 'var(--orange)', fontSize: 11,
        lineHeight: 1, padding: '3px 6px',
        display: 'inline-flex', alignItems: 'center',
      }}
    ><LockIcon size={11} /></button>
  );
}

/**
 * Small "Posted" badge for section titles, rendered next to RECEIVED BY YOU /
 * PAYOUT TO etc. when an unreversed JE locks the section.
 */
export function PostedBadge({ visible }) {
  if (!visible) return null;
  return (
    <span style={{ marginLeft: 8, fontSize: 10, color: 'var(--orange)', display: 'inline-flex', alignItems: 'center', gap: 4 }}>
      <LockIcon size={11} /> Posted
    </span>
  );
}

/**
 * Panel rendered below a form listing every unreversed JE tied to the row, with
 * a Reverse button per entry. onReverse receives the full { entry, lines } pair
 * so ReverseEntryModal can render line details.
 */
export function PostedEntries({ jes, title, onReverse }) {
  if (!jes || jes.length === 0) return null;
  return (
    <div style={{ marginTop: 24, padding: '14px 16px', background: 'color-mix(in oklab, var(--orange) 6%, transparent)', borderLeft: '3px solid var(--orange)', borderRadius: 4 }}>
      <div style={{ fontSize: 11, color: 'var(--orange)', textTransform: 'uppercase', letterSpacing: 1.5, marginBottom: 8 }}>{title}</div>
      <div style={{ fontSize: 11, color: 'var(--muted)', marginBottom: 10 }}>
        Trigger-protected fields above cannot be edited while these entries are posted. Reverse first, then re-edit.
      </div>
      {jes.map(({ entry, lines }) => (
        <div key={entry.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '6px 0', borderTop: '1px solid var(--border)', gap: 12 }}>
          <div style={{ minWidth: 0, flex: 1 }}>
            <div style={{ fontSize: 12 }}>{entry.description}</div>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>{fmtDate(entry.entry_date)} · {entry.source_type}</div>
          </div>
          <button className="btn btn-ghost btn-sm" onClick={() => onReverse({ entry, lines })}>Reverse…</button>
        </div>
      ))}
    </div>
  );
}
