/**
 * utils/expenseCapacity.js - UI mirror of the expense allocation cap.
 *
 * Surfaces the remaining headroom on an (expense, period) so a payout-split form
 * can show the cap and clamp input BEFORE the user types past it.
 *
 * @invariant the DB trigger fn_check_split_expense_cap is the source of truth
 *            and blocks any over-allocation regardless of the UI. This file only
 *            mirrors that math; if the two ever disagree, the trigger wins and
 *            this file is the bug.
 * @see docs/MONEY.md (expense splits), trg_check_split_expense_cap
 */
import { supabase } from '../lib/supabase';

/**
 * Effective price for a period from a price_history array (ascending by
 * effective_date), or null when no history row applies.
 *
 * @returns {number|null} null means "the caller should use expenses.amount",
 *          which is what the trigger's coalesce does. Two cases reach it: no
 *          history at all, and a period EARLIER than the earliest row.
 * @gotcha the second case is the trap. Seeding the search with priceHistory[0]
 *         returns the earliest history price for a period that price was not yet
 *         in effect for, where the trigger finds no row and falls back to
 *         expenses.amount. The screen then offers headroom the trigger refuses
 *         with a P0001. Seeding null is what makes the
 *         two agree.
 * @gotcha a null period is not that case. The trigger's predicate is
 *         `(NEW.expense_period is null or eph.effective_date <= NEW.expense_period)`,
 *         so a one-time expense matches every row and takes the newest.
 */
function pickEffective(priceHistory, periodYmd) {
  if (!priceHistory || priceHistory.length === 0) return null;
  if (!periodYmd) return parseFloat(priceHistory[priceHistory.length - 1].amount);
  let pick = null;
  for (const row of priceHistory) {
    if (row.effective_date <= periodYmd) pick = row;
    else break;
  }
  return pick ? parseFloat(pick.amount) : null;
}

/**
 * Cap, allocations committed by OTHER payouts, and remaining headroom for one
 * (expense, period).
 *
 * @param {{expenseId, expensePeriod, excludePayoutId}} args - expensePeriod is
 *        null (one-time) or 'YYYY-MM'/'YYYY-MM-01' (recurring); excludePayoutId
 *        drops the calling form's own splits from the allocated sum since it is
 *        editing those locally.
 * @returns {Promise<{cap, allocated, remaining, expenseName, loaded}>} `loaded: false`
 *          only when no expense is chosen.
 * @throws whatever PostgREST returned, so a refused cap is never a cap of zero.
 */
export async function fetchExpenseRemaining({ expenseId, expensePeriod, excludePayoutId }) {
  if (!expenseId) return { cap: 0, allocated: 0, remaining: 0, expenseName: '', loaded: false };

  const periodYmd = expensePeriod && /^\d{4}-\d{2}$/.test(expensePeriod) ? `${expensePeriod}-01` : expensePeriod || null;

  const [{ data: expense, error: expErr }, { data: priceHistory, error: phErr }, { data: splits, error: spErr }] = await Promise.all([
    supabase.from('expenses').select('id, name, amount').eq('id', expenseId).single(),
    supabase.from('expense_price_history').select('effective_date, amount').eq('expense_id', expenseId).order('effective_date', { ascending: true }),
    (() => {
      let q = supabase.from('payout_splits').select('amount, payout_id, expense_period').eq('expense_id', expenseId);
      if (periodYmd === null) q = q.is('expense_period', null);
      else q = q.eq('expense_period', periodYmd);
      return q;
    })(),
  ]);
  // Each of the three is one part of one cap, and `remaining` is what the split input
  // is clamped to, so a refusal answering 0 clamps a typed amount to $0.00 while the
  // meter, which does honour `loaded`, renders nothing to explain it. `loaded: false`
  // means only "no expense chosen"; a refusal throws and the caller says so.
  const readErr = expErr || phErr || spErr;
  if (readErr) throw readErr;
  if (!expense) return { cap: 0, allocated: 0, remaining: 0, expenseName: '', loaded: false };

  const effective = pickEffective(priceHistory, periodYmd);
  const cap = effective !== null ? effective : parseFloat(expense.amount);
  const allocated = (splits || [])
    .filter(s => !excludePayoutId || s.payout_id !== excludePayoutId)
    .reduce((sum, s) => sum + (parseFloat(s.amount) || 0), 0);
  const remaining = Math.max(0, cap - allocated);

  return { cap, allocated, remaining, expenseName: expense.name, loaded: true };
}

/**
 * One selectable row per (expense, period) that still has open balance.
 *   - One-time expenses -> a single row with period_key=null.
 *   - Recurring expenses -> one row per occurrence from start_date through
 *     today, period_key='YYYY-MM', with a price-history-aware cap.
 *
 * @param {{excludePayoutId?: string}} [opts]
 * @returns {Promise<object[]>} rows with remaining <= 0 filtered out; the
 *          current payout's splits excluded so the form-edit case shows the
 *          right remaining (those splits get overwritten by form state).
 * @throws whatever PostgREST returned, so a refused read is never an empty picker.
 */
export async function fetchExpenseOptions({ excludePayoutId } = {}) {
  const { getOccurrencesInRange, parseLocalDate } = await import('./expenses');
  const [{ data: expenses, error: expErr }, { data: splits, error: spErr }, { data: priceHistory, error: phErr }] = await Promise.all([
    supabase.from('expenses').select('id, name, type, frequency, amount, category_id, start_date, end_date, recurrence_day_of_month').order('name'),
    supabase.from('payout_splits').select('expense_id, expense_period, amount, payout_id').not('expense_id', 'is', null),
    supabase.from('expense_price_history').select('expense_id, effective_date, amount'),
  ]);
  // Same rule as fetchExpenseRemaining above, and the same reason. An empty list is not
  // "no expense has an open balance", it is this picker's entire claim, and the split row
  // that reads it is how a shared cost gets recovered from a payout.
  const readErr = expErr || spErr || phErr;
  if (readErr) throw readErr;

  // Group splits by (expense_id, period_key) → sum (excluding current payout).
  const allocByKey = new Map();
  for (const s of splits || []) {
    if (excludePayoutId && s.payout_id === excludePayoutId) continue;
    const periodKey = s.expense_period ? s.expense_period.substring(0, 7) : null;
    const k = `${s.expense_id}|${periodKey || ''}`;
    allocByKey.set(k, (allocByKey.get(k) || 0) + (parseFloat(s.amount) || 0));
  }

  // Index price history by expense.
  const phByExpense = new Map();
  for (const row of priceHistory || []) {
    if (!phByExpense.has(row.expense_id)) phByExpense.set(row.expense_id, []);
    phByExpense.get(row.expense_id).push(row);
  }
  for (const arr of phByExpense.values()) arr.sort((a, b) => a.effective_date.localeCompare(b.effective_date));

  // Same rule as pickEffective above, over the batched index: no applicable
  // history row means expenses.amount, never the earliest price. B-10 was in
  // both functions, so the picker's per-period rows carried the same wrong cap
  // as the readout beside them.
  function effectiveAmount(expense, periodYmd) {
    const arr = phByExpense.get(expense.id) || [];
    const fallback = parseFloat(expense.amount) || 0;
    if (arr.length === 0) return fallback;
    let pick = null;
    for (const row of arr) {
      if (!periodYmd || row.effective_date <= periodYmd) pick = row;
      else break;
    }
    return pick ? (parseFloat(pick.amount) || 0) : fallback;
  }

  const today = new Date();
  const out = [];
  for (const e of expenses || []) {
    if (e.type === 'one_time') {
      const cap = effectiveAmount(e, null);
      const allocated = allocByKey.get(`${e.id}|`) || 0;
      const remaining = Math.max(0, cap - allocated);
      if (remaining > 0.005) {
        out.push({
          expense_id: e.id, expense_name: e.name, category_id: e.category_id,
          type: e.type, frequency: e.frequency,
          period_key: null, period_label: null,
          cap, allocated, remaining,
        });
      }
    } else {
      // Recurring: enumerate occurrences from start_date through today.
      const start = parseLocalDate(e.start_date);
      if (!start) continue;
      const occurrences = getOccurrencesInRange(e, start, today);
      for (const occ of occurrences) {
        if (!occ.periodKey) continue;
        const ymd = `${occ.periodKey}-01`;
        const cap = effectiveAmount(e, ymd);
        const allocated = allocByKey.get(`${e.id}|${occ.periodKey}`) || 0;
        const remaining = Math.max(0, cap - allocated);
        if (remaining > 0.005) {
          const periodLabel = occ.date.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
          out.push({
            expense_id: e.id, expense_name: e.name, category_id: e.category_id,
            type: e.type, frequency: e.frequency,
            period_key: occ.periodKey, period_label: periodLabel,
            cap, allocated, remaining,
          });
        }
      }
    }
  }
  return out;
}

/**
 * Pure clamp: never returns a value above remaining.
 * @returns {{value, clamped}} clamped=true when the input was reduced. Covered
 *          by utils/__tests__/expenseCapacity.test.js (guards the iPhone
 *          over-allocation fix).
 */
export function clampSplitAmount(input, remaining) {
  const n = parseFloat(input);
  if (!Number.isFinite(n) || n < 0) return { value: input, clamped: false };
  if (remaining <= 0) return { value: '0', clamped: n > 0 };
  if (n > remaining + 0.005) return { value: remaining.toFixed(2), clamped: true };
  return { value: input, clamped: false };
}
