/**
 * components/shared/OopPaymentModal.js. Record how an expense was paid.
 *
 * Two modes, picked by the "Who paid this?" toggle. Out of pocket calls `record_oop_payment`,
 * whose trigger posts Pattern P for a creator (reimbursed later from a payout) or Pattern Q for
 * a partner (never reimbursed); the payer card decides which. Company account calls
 * `record_company_payment`, posting Pattern R, and each creator's share is recovered by a
 * carved recharge split on their next payout, excluded from the 511x JE, so their earnings and
 * 1099 drop by that share. The split editor is creators-only: partners receive no payout.
 *
 * @invariant amount clamps to the uncovered remainder and paid_at caps at today; the cap trigger
 *            and the RPC both re-check. Company-mode percentages must sum to 100, with the last
 *            creator absorbing the rounding cent server-side.
 * @gotcha multi-period mode posts one RPC per period in a loop, so a mid-loop failure leaves
 *         earlier entries posted, and a receipt attaches to the FIRST period only.
 * @see docs/MONEY.md Patterns P, Q and R
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { ReceiptIcon, ChevronIcon } from './Icon';
import { fmtMoney, todayYMD } from '../../utils/format';
import { DB_DATE_MIN as DATE_MIN, RECHARGE_MIN } from '../../utils/dbLimits';
import { useEscapeKey } from '../../hooks/useEscapeKey';
import { humanizeError } from '../../utils/errors';
import { clampSplitAmount, fetchExpenseRemaining } from '../../utils/expenseCapacity';
import { fetchExpenseOopCoverage } from '../../utils/oopPayments';
import { uploadExpenseReceipt } from '../../utils/receipt';
import { validateUploadFile, RECEIPT_FILE_ACCEPT } from '../../utils/storage';
import { useToast } from './Toast';
import Feedback from './Feedback';
import Loading from './Loading';
import OutstandingList from './OutstandingList';
import Modal, { ModalClose } from './Modal';
import SubmitButton from './SubmitButton';
import MoneyInput from './MoneyInput';

const NOTES_MAX = 2000;
// The window the chk_*_dates CHECKs accept. paid_at deliberately caps at TODAY
// rather than at DATE_MAX: this records a payment that has already been made,
// and the header @invariant above says so. It was capped at DATE_MAX until
// which let a journal entry be dated six years out with nothing on
// the path to stop it.

const log = (...args) => {
  if (process.env.NODE_ENV !== 'production') console.error('[OopPaymentModal]', ...args);
};

function formatPeriodLabel(period) {
  if (!period) return 'one-time';
  const m = /^(\d{4})-(\d{2})$/.exec(period);
  if (!m) return period;
  const d = new Date(parseInt(m[1], 10), parseInt(m[2], 10) - 1, 1);
  return d.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
}

/** The percentage typed in one row, as a number. A blank box reads as 0, same as a typed 0. */
const allocPct = (a) => parseFloat(a.pct) || 0;

/**
 * The dollar share each active row would be written with, mirroring `record_company_payment`
 * exactly: every row but the last rounds to 2dp, the last absorbs the residual. The database
 * refuses a share of 0.00 (`chk_recharge_amount`), and a legal percentage can still round
 * away on a small enough amount, so the client has to do the same arithmetic to see it coming.
 * @see schemas/SCHEMA.sql function record_company_payment
 */
function allocShares(active, amount) {
  let running = 0;
  return active.map((a, i) => {
    if (i < active.length - 1) {
      const share = Math.round((amount * allocPct(a)) / 100 * 100) / 100;
      running += share;
      return share;
    }
    return Math.round((amount - running) * 100) / 100;
  });
}

/**
 * Even split across creators, last creator absorbing the rounding so the
 * percentages sum to exactly 100 (mirrors the server-side last-party residual).
 * Used only to seed a freshly opened modal: nothing has been typed yet, so there is
 * nothing to preserve. Every later edit leaves the other rows exactly as they were.
 * @param {{id: string}[]} creators
 * @returns {{creatorId: string, pct: number}[]}
 */
function evenAllocations(creators) {
  const n = creators.length;
  if (n === 0) return [];
  const base = Math.floor((100 / n) * 100) / 100; // 2dp floor
  return creators.map((c, i) => ({
    creatorId: c.id,
    pct: i === n - 1 ? Math.round((100 - base * (n - 1)) * 100) / 100 : base,
  }));
}

/**
 * @param {object} props
 * @param {{id, name, amount, category_id, type, start_date}} props.expense - required
 * @param {string|null} [props.period] - 'YYYY-MM' for a recurring single period; null for one-time
 * @param {{periodKey, amount}[]} [props.periods] - multi-period batch; when present overrides `period`
 * @param {function} props.onClose
 * @param {function} props.onSaved - receives the new payment id (single) or {count} (multi)
 */
export default function OopPaymentModal({ expense, period, periods, onClose, onSaved }) {
  const isMulti = Array.isArray(periods) && periods.length > 0;
  const multiTotal = isMulti ? periods.reduce((s, p) => s + (parseFloat(p.amount) || 0), 0) : 0;
  const [creators, setCreators] = useState([]);
  const [partners, setPartners] = useState([]);
  const [mode, setMode] = useState('oop');            // 'oop' (a person paid) | 'company' (LLC paid from checking)
  const [payerKey, setPayerKey] = useState('');       // creator id, or 'partners' (oop mode only)
  const [allocations, setAllocations] = useState([]); // [{ creatorId, pct }]
  // Partners buy most of the kit here, and usually absorb it. Charging a creator is the
  // deliberate case, so it is opt-in: an empty split would say the same thing silently, and
  // silence is what let a partner-bought phone case get filed as company-paid to reach her.
  const [recharge, setRecharge] = useState(false);
  const [amount, setAmount] = useState('');
  const [paidAt, setPaidAt] = useState(() => {
    // Default to the date the expense actually occurred, capped at today (paid_at
    // can't be in the future). Recurring with a period_key: first of that month.
    // Recurring multi-period: first of the earliest selected period. One-time:
    // expense.start_date. Falls back to today only if no anchor is available.
    const today = todayYMD();
    const anchor = (() => {
      if (Array.isArray(periods) && periods.length > 0) {
        const earliest = [...periods].sort((a, b) => (a.periodKey < b.periodKey ? -1 : 1))[0];
        return earliest?.periodKey ? `${earliest.periodKey}-01` : null;
      }
      if (period) return `${period}-01`;
      if (expense?.start_date) return expense.start_date;
      return null;
    })();
    if (!anchor) return today;
    return anchor > today ? today : anchor;
  });
  const [notes, setNotes] = useState('');
  const [uncovered, setUncovered] = useState(null);
  // Whether the last keystroke was rewritten by the clamp, so the field can admit it.
  const [amountClamped, setAmountClamped] = useState(false);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);
  const [showNotes, setShowNotes] = useState(false);
  const [receipt, setReceipt] = useState(null);          // pending File
  const [dragOver, setDragOver] = useState(false);
  const [categoryAccount, setCategoryAccount] = useState(null); // { code, name }
  const [creatorOopCodes, setCreatorOopCodes] = useState({});   // creatorId -> '21xx'
  const [partnerAccounts, setPartnerAccounts] = useState([]);   // [{ creatorId, code }] aligned to admin profile ids
  const firstFieldRef = useRef(null);
  const receiptInputRef = useRef(null);
  const overlayRef = useRef(null);
  const toast = useToast();

  useEscapeKey(onClose, !submitting, overlayRef);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      setLoading(true);
      setError(null);

      // Three lookups feed the Posts preview: the expense's category 6xxx code,
      // each creator's 21xx OOP liability code (via payment_destinations), and
      // every partner's 30x0 equity code.
      const previewFetches = Promise.all([
        expense?.category_id
          ? supabase.from('ledger_accounts').select('id, code, name').eq('id', expense.category_id).maybeSingle()
          : Promise.resolve({ data: null }),
        supabase.from('payment_destinations')
          .select('oop_creator_id, ledger_account_id, ledger_accounts:ledger_account_id(code)')
          .not('oop_creator_id', 'is', null),
        supabase.from('ledger_accounts')
          .select('id, code, name, source_id')
          .eq('source_type', 'partner')
          .eq('is_active', true),
      ]);

      if (isMulti) {
        const [{ data: profiles, error: profErr }, [catRes, oopDestRes, partnerActRes]] = await Promise.all([
          supabase.from('profiles').select('id, role, creator_name, full_name, partner_allocation_pct').order('creator_name'),
          previewFetches,
        ]);
        if (cancelled) return;
        if (profErr) { setError(humanizeError(profErr)); setLoading(false); return; }
        const cs = (profiles || []).filter((p) => p.role === 'creator');
        const ps = (profiles || [])
          .filter((p) => p.role === 'admin' && p.partner_allocation_pct != null)
          .map((p) => ({ ...p, partner_allocation_pct: parseFloat(p.partner_allocation_pct) || 0 }));
        const oopMap = {};
        (oopDestRes?.data || []).forEach((d) => { if (d.ledger_accounts?.code) oopMap[d.oop_creator_id] = d.ledger_accounts.code; });
        setCreators(cs);
        setPartners(ps);
        setAllocations(evenAllocations(cs));
        setCategoryAccount(catRes?.data || null);
        setCreatorOopCodes(oopMap);
        setPartnerAccounts((partnerActRes?.data || []).map((a) => ({ creatorId: a.source_id, code: a.code, name: a.name })));
        setUncovered(multiTotal);
        setAmount(multiTotal.toFixed(2));
        setLoading(false);
        requestAnimationFrame(() => firstFieldRef.current?.focus());
        return;
      }

      // The Uncovered figure this modal prefills its amount from is capacity minus
      // coverage. Both helpers throw rather than answering 0, because 0 is also what
      // a fully covered expense looks like, and the difference is a second payment
      // recorded against an expense that was already paid for.
      let profRes; let capacity; let coverage; let previews;
      try {
        [profRes, capacity, coverage, previews] = await Promise.all([
          supabase.from('profiles').select('id, role, creator_name, full_name, partner_allocation_pct').order('creator_name'),
          fetchExpenseRemaining({ expenseId: expense?.id, expensePeriod: period }),
          fetchExpenseOopCoverage(expense?.id, period || null),
          previewFetches,
        ]);
      } catch (e) {
        if (!cancelled) { log('load', e); setError(humanizeError(e)); setLoading(false); }
        return;
      }
      const { data: profiles, error: profErr } = profRes;
      // The three preview lookups are deliberately best-effort, unlike `profRes` above them:
      // they only feed the monospace preview of the entry the TRIGGER will post, and
      // `postsPreview` returns null without the category account, so a refusal hides the
      // preview rather than showing a different entry from the one that will be written.
      const [catRes, oopDestRes, partnerActRes] = previews;

      if (cancelled) return;
      if (profErr) {
        log('load', profErr);
        setError(humanizeError(profErr));
        setLoading(false);
        return;
      }

      const cs = (profiles || []).filter((p) => p.role === 'creator');
      const ps = (profiles || [])
        .filter((p) => p.role === 'admin' && p.partner_allocation_pct != null)
        .map((p) => ({ ...p, partner_allocation_pct: parseFloat(p.partner_allocation_pct) || 0 }));
      const oopMap = {};
      (oopDestRes?.data || []).forEach((d) => { if (d.ledger_accounts?.code) oopMap[d.oop_creator_id] = d.ledger_accounts.code; });

      // capacity.remaining already excludes split allocations; subtract existing OOP too.
      const remaining = Math.max(0, capacity.remaining - coverage.amount);

      setCreators(cs);
      setPartners(ps);
      setAllocations(evenAllocations(cs));
      setCategoryAccount(catRes?.data || null);
      setCreatorOopCodes(oopMap);
      setPartnerAccounts((partnerActRes?.data || []).map((a) => ({ creatorId: a.source_id, code: a.code, name: a.name })));
      setUncovered(remaining);
      if (remaining > 0) setAmount(remaining.toFixed(2));
      setLoading(false);
      requestAnimationFrame(() => firstFieldRef.current?.focus());
    }
    if (expense?.id) load();
    return () => { cancelled = true; };
  }, [expense?.id, period, isMulti, multiTotal]);

  const partnerPctLabel = useMemo(() => {
    if (partners.length === 0) return '50/50';
    return partners.map((p) => `${p.partner_allocation_pct}%`).join(' / ');
  }, [partners]);

  /**
   * Monospace preview of the exact JE the trigger will post, built from the
   * three account-code lookups above (category 6xxx, creator 21xx OOP, partner
   * 30x0). Display only; the trigger, not this string, authors the real JE.
   */
  const postsPreview = useMemo(() => {
    if (!categoryAccount) return null;
    const dr = `DR ${categoryAccount.code} ${categoryAccount.name}`;
    if (mode === 'company') {
      // Pattern R: the company-payment JE itself is just DR 6xxx / CR 1000.
      // The per-creator recharge is a later payout reduction, not a line here.
      return `${dr} / CR 1000 Business Checking`;
    }
    if (!payerKey) return null;
    if (payerKey === 'partners') {
      const lines = partners.map((p) => {
        const acct = partnerAccounts.find((a) => a.creatorId === p.id);
        const code = acct?.code || '30??';
        return `CR ${code} ${p.partner_allocation_pct}%`;
      });
      return `${dr} / ${lines.join(' + ')} · partner contribution`;
    }
    const c = creators.find((x) => x.id === payerKey);
    const name = c?.creator_name || c?.full_name || 'creator';
    const code = creatorOopCodes[payerKey] || '21??';
    return `${dr} / CR ${code} Due to ${name}`;
  }, [mode, payerKey, creators, partners, categoryAccount, creatorOopCodes, partnerAccounts]);

  /**
   * The rows that actually bear something. A row left at 0 stays on screen, greyed, so the
   * decision is visible, but it is never sent: `expense_recharge_allocations` refuses a row
   * at 0% or $0.00, and a stored one would carve a $0.00 recharge out of that creator's next
   * payout. Typing 0 is how you say "not this creator", and the ✕ is how you stop seeing them.
   *
   * The floor is RECHARGE_MIN, not zero: `pct` is 2dp, so a typed 0.001 is above zero here and
   * still lands in the column as 0.00.
   */
  const activeAllocations = useMemo(
    () => allocations.filter((a) => allocPct(a) >= RECHARGE_MIN),
    [allocations]
  );

  // The total counts only what will be recorded, so it answers the question the reader is
  // actually asking: does the split I am about to save add up?
  const allocTotal = useMemo(
    () => activeAllocations.reduce((s, a) => s + allocPct(a), 0),
    [activeAllocations]
  );

  /**
   * The amount the shares are checked against. Multi-period posts one RPC per period, so the
   * SMALLEST period is the one that can round a share away; checking the total would pass a
   * split that fails on the cheapest month.
   */
  const guardAmount = useMemo(() => {
    if (!isMulti) return parseFloat(amount) || 0;
    const amts = (periods || []).map((p) => parseFloat(p.amount) || 0).filter((n) => n > 0);
    return amts.length ? Math.min(...amts) : 0;
  }, [isMulti, periods, amount]);

  /** The first active row whose dollar share would be written as 0.00, or null. */
  const zeroShareAlloc = useMemo(() => {
    if (!(guardAmount > 0) || activeAllocations.length === 0) return null;
    const i = allocShares(activeAllocations, guardAmount).findIndex((share) => share < RECHARGE_MIN);
    return i === -1 ? null : activeAllocations[i];
  }, [activeAllocations, guardAmount]);

  const allocValid = Math.abs(allocTotal - 100) <= 0.01 && activeAllocations.length > 0 && !zeroShareAlloc;
  /** Partners paid, and somebody is being charged for it. @see record_oop_payment */
  const partnerRecharge = mode === 'oop' && payerKey === 'partners' && recharge;
  /** The split control is on screen, so its rules apply. */
  const splitting = mode === 'company' || partnerRecharge;
  const addableCreators = useMemo(
    () => creators.filter((c) => !allocations.some((a) => a.creatorId === c.id)),
    [creators, allocations]
  );

  /**
   * What is still standing between this payment and being recorded.
   *
   * Four identifiers gated the button and two of them are transient, so the only signals a
   * reader had were the allocation total turning green and the ledger preview silently
   * returning null when no payer was picked. Neither says the word why.
   */
  const creatorLabel = useCallback(
    (id) => {
      const c = creators.find((x) => x.id === id);
      return c?.creator_name || c?.full_name || 'Creator';
    },
    [creators]
  );

  const outstanding = [];
  if (!isMulti && !amount) outstanding.push({ key: 'amount', label: 'Enter the amount that was paid' });
  if (mode === 'oop' && !payerKey) outstanding.push({ key: 'payer', label: 'Pick who paid for this' });
  if (splitting) {
    if (!allocations.length) outstanding.push({ key: 'alloc-none', label: 'Add at least one creator to split this across' });
    else if (!activeAllocations.length) outstanding.push({ key: 'alloc-zero', label: 'Give at least one creator a share' });
    else if (Math.abs(allocTotal - 100) > 0.01) outstanding.push({ key: 'alloc-sum', label: `Make the split add up to 100%: it is ${allocTotal.toFixed(2)}% now` });
    else if (zeroShareAlloc) outstanding.push({ key: 'alloc-dust', label: `${creatorLabel(zeroShareAlloc.creatorId)}'s share rounds to $0.00. Raise it, or zero it out.` });
  }

  /** Set one creator's percentage (free-typed; total is validated on save). */
  function setAllocPct(creatorId, value) {
    setAllocations((prev) => prev.map((a) => (a.creatorId === creatorId ? { ...a, pct: value } : a)));
  }

  /**
   * Drop a creator from the editor. Every other row keeps the percentage typed into it, so
   * the total falls and the outstanding list asks where the rest goes.
   *
   * @invariant no control in this editor rewrites a number somebody entered. Re-splitting the
   *            survivors evenly would move money on a keystroke aimed at a different row.
   */
  function removeAlloc(creatorId) {
    setAllocations((prev) => prev.filter((a) => a.creatorId !== creatorId));
  }

  /**
   * Add a creator holding whatever is still unallocated: 40 into a split standing at 60, and
   * 0 into one already at 100, which lands them inactive for the admin to decide. Filling the
   * gap completes a split without touching a row somebody typed.
   */
  function addAlloc(creatorId) {
    if (!creatorId) return;
    setAllocations((prev) => {
      if (prev.some((a) => a.creatorId === creatorId)) return prev;
      const used = prev.reduce((s, a) => s + (allocPct(a) >= RECHARGE_MIN ? allocPct(a) : 0), 0);
      const free = Math.max(0, Math.round((100 - used) * 100) / 100);
      return [...prev, { creatorId, pct: free }];
    });
  }

  if (!expense) return null;

  /**
   * Take the typed amount, clamped to what is still uncovered, and say so when the clamp
   * actually rewrote it. Silence was the defect: the field snapped to the remainder mid-word
   * with the caret after a number nobody typed.
   */
  function onAmountTyped(value) {
    if (uncovered == null) { setAmount(value); return; }
    const { value: next, clamped } = clampSplitAmount(value, uncovered);
    setAmount(next);
    setAmountClamped(clamped);
  }

  async function handleReceiptFile(file) {
    if (!file) return;
    const err = await validateUploadFile(file);
    if (err) {
      setError({ tone: 'error', title: 'Receipt rejected', body: err });
      return;
    }
    setReceipt(file);
  }

  async function uploadReceiptIfPresent({ expenseId, periodKey, uploadedBy }) {
    if (!receipt) return { ok: true };
    return new Promise((resolve) => {
      uploadExpenseReceipt({
        file: receipt,
        expenseId,
        periodKey,
        uploadedBy,
        setUploading: () => {},
        onSuccess: () => resolve({ ok: true }),
        onError: (msg) => resolve({ ok: false, msg }),
      });
    });
  }

  async function handleSubmit() {
    const trimmedNotes = notes.trim() ? notes.trim() : null;

    // Validate the mode-specific picker before touching the network.
    if (splitting) {
      if (!allocValid) {
        // The outstanding list already worked out WHICH of the four ways a split can be wrong
        // this is. Restating "must total 100%" was wrong for three of them.
        const why = outstanding.find((o) => o.key.startsWith('alloc'));
        setError({ tone: 'error', title: 'Check the split', body: why ? why.label : 'Allocate the full expense across creators.' });
        return;
      }
    }
    if (mode === 'oop' && !payerKey) {
      setError({ tone: 'error', title: 'Pick a payer', body: 'Choose either a creator or "Partners" before saving.' });
      return;
    }

    const payerType = payerKey === 'partners' ? 'partners' : 'creator';
    const payerCreatorId = payerType === 'creator' ? payerKey : null;
    // Rows left at 0 are not part of the split and are not sent. Sending them was the defect:
    // the database refused the $0.00 allocation and the banner named no field.
    const allocPayload = activeAllocations.map((a) => ({ party_type: 'creator', party_id: a.creatorId, pct: allocPct(a) }));

    // One call per (period, amount); dispatches to the right RPC for the mode.
    const callRpc = (periodKey, amt) =>
      mode === 'company'
        ? supabase.rpc('record_company_payment', {
            p_expense_id: expense.id,
            p_period_key: periodKey,
            p_amount: amt,
            p_paid_at: paidAt,
            p_notes: trimmedNotes,
            p_allocations: allocPayload,
          })
        : supabase.rpc('record_oop_payment', {
            p_expense_id: expense.id,
            p_period_key: periodKey,
            p_payer_type: payerType,
            p_payer_creator_id: payerCreatorId,
            p_amount: amt,
            p_paid_at: paidAt,
            p_notes: trimmedNotes,
            // Null, not an empty array, when nobody is being charged: the function reads a
            // present-but-empty array the same way, and null says "not asked for" out loud.
            p_allocations: partnerRecharge ? allocPayload : null,
          });

    if (isMulti) {
      setSubmitting(true);
      setError(null);
      let succeeded = 0;
      let firstFailure = null;
      for (const p of periods) {
        const amt = parseFloat(p.amount) || 0;
        if (amt <= 0) continue;
        const { error: rpcErr } = await callRpc(p.periodKey, amt);
        if (rpcErr) {
          firstFailure = { period: p.periodKey, err: rpcErr };
          break;
        }
        succeeded += 1;
      }
      if (firstFailure) {
        log('rpc record payment multi', firstFailure.err);
        const baseErr = humanizeError(firstFailure.err);
        setError({
          ...baseErr,
          title: `Recorded ${succeeded} of ${periods.length}`,
          body: `${firstFailure.period} failed: ${baseErr.body || baseErr.title}. Earlier entries posted.`,
        });
        setSubmitting(false);
        return;
      }
      if (receipt && periods[0]?.periodKey) {
        // Attach receipt to the first period only (multi-period attach not yet specified).
        const { data: { user } = {} } = await supabase.auth.getUser();
        const r = await uploadReceiptIfPresent({ expenseId: expense.id, periodKey: periods[0].periodKey, uploadedBy: user?.id });
        if (!r.ok && toast?.warn) toast.warn("Recorded. The receipt didn't upload. Attach it from this expense under Payment Records.");
      }
      setSubmitting(false);
      if (onSaved) onSaved({ count: succeeded });
      onClose();
      return;
    }

    const n = parseFloat(amount);
    if (!Number.isFinite(n) || n <= 0) {
      setError({ tone: 'error', title: 'Amount required', body: 'Enter a positive dollar amount.' });
      return;
    }

    setSubmitting(true);
    setError(null);

    const { data, error: rpcErr } = await callRpc(period || null, n);

    if (rpcErr) {
      log('rpc record payment', rpcErr);
      setError(humanizeError(rpcErr));
      setSubmitting(false);
      return;
    }
    if (receipt) {
      const { data: { user } = {} } = await supabase.auth.getUser();
      const r = await uploadReceiptIfPresent({ expenseId: expense.id, periodKey: period || null, uploadedBy: user?.id });
      const receiptHome = expense.type === 'recurring' ? 'under Payment Records' : 'in the Receipts section';
      if (!r.ok && toast?.warn) toast.warn(`Recorded. The receipt didn't upload. Attach it from this expense ${receiptHome}.`);
    }
    setSubmitting(false);
    if (onSaved) onSaved(data);
    onClose();
  }

  return (
    <Modal
      title="RECORD PAYMENT"
      size="md"
      onClose={onClose}
      closeDisabled={submitting}
    >

        <div className="modal-body">
          <div style={{ marginBottom: 16, padding: '10px 12px', background: 'var(--surface2)', borderRadius: 6 }}>
            <div style={{ fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1, marginBottom: 4 }}>Expense</div>
            <div style={{ fontSize: 13 }}>
              <strong>{expense.name}</strong>
              {!isMulti && <span style={{ color: 'var(--muted)' }}> &middot; {formatPeriodLabel(period)}</span>}
              {isMulti && <span style={{ color: 'var(--muted)' }}> &middot; {periods.length} periods selected</span>}
            </div>
            {isMulti ? (
              <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 6, display: 'flex', flexDirection: 'column', gap: 2 }}>
                {periods.map((p) => (
                  <div key={p.periodKey} style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>{formatPeriodLabel(p.periodKey)}</span>
                    <span style={{ fontVariantNumeric: 'tabular-nums', color: 'var(--white)' }}>{fmtMoney(p.amount)}</span>
                  </div>
                ))}
                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 4, paddingTop: 4, borderTop: '1px solid var(--border)', fontWeight: 600, color: 'var(--white)' }}>
                  <span>Total</span>
                  <span style={{ fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(multiTotal)}</span>
                </div>
              </div>
            ) : uncovered != null ? (
              <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4 }}>
                Uncovered: <strong>{fmtMoney(uncovered)}</strong>
              </div>
            ) : null}
          </div>

          {loading ? <Loading style={{ fontSize: 12 }} /> : (
            <>
              <div className="oop-modal-section-label">WHO PAID THIS?</div>
              <div className="rp-segmented" role="tablist" aria-label="Who paid this expense">
                <button
                  type="button"
                  role="tab"
                  aria-selected={mode === 'oop'}
                  className={`rp-segment${mode === 'oop' ? ' is-active' : ''}`}
                  onClick={() => setMode('oop')}
                  disabled={submitting}
                >Out of pocket</button>
                <button
                  type="button"
                  role="tab"
                  aria-selected={mode === 'company'}
                  className={`rp-segment${mode === 'company' ? ' is-active' : ''}`}
                  onClick={() => setMode('company')}
                  disabled={submitting}
                >Company account</button>
              </div>

              {mode === 'oop' ? (
              <div className="oop-payer-cards">
                {creators.map((c, idx) => {
                  const isSelected = payerKey === c.id;
                  const initial = (c.creator_name || c.full_name || '?')[0].toUpperCase();
                  return (
                    <button
                      key={c.id}
                      ref={idx === 0 ? firstFieldRef : null}
                      type="button"
                      className={`oop-payer-card${isSelected ? ' is-selected' : ''}`}
                      onClick={() => setPayerKey(c.id)}
                      disabled={submitting}
                      aria-pressed={isSelected}
                    >
                      <div className="oop-payer-card-initial">{initial}</div>
                      <div className="oop-payer-card-name">{c.creator_name || c.full_name || 'Creator'}</div>
                    </button>
                  );
                })}
                {partners.length > 0 ? (() => {
                  const isSelected = payerKey === 'partners';
                  const initials = partners.map((p) => (p.full_name || '?')[0].toUpperCase()).join('+');
                  return (
                    <button
                      type="button"
                      className={`oop-payer-card${isSelected ? ' is-selected' : ''}`}
                      onClick={() => setPayerKey('partners')}
                      disabled={submitting}
                      aria-pressed={isSelected}
                    >
                      <div className="oop-payer-card-initial">{initials}</div>
                      <div className="oop-payer-card-name">Partners</div>
                      <div className="oop-payer-card-pct">{partnerPctLabel}</div>
                    </button>
                  );
                })() : null}
              </div>
              ) : null}

              {mode === 'oop' && payerKey === 'partners' ? (
                <label className="rp-recharge">
                  <input
                    type="checkbox"
                    checked={recharge}
                    onChange={(e) => setRecharge(e.target.checked)}
                    disabled={submitting}
                  />
                  <span>
                    <span className="rp-recharge-title">Charge this back to a creator</span>
                    <span className="rp-recharge-note">
                      Off, the partners absorb it. On, it comes off the creator's next payroll month,
                      the same as a company-paid cost.
                    </span>
                  </span>
                </label>
              ) : null}

              {splitting ? (
                <div className="rp-company">
                  <div className="rp-alloc-head">
                    <span className="oop-modal-section-label" style={{ marginBottom: 0 }}>SPLIT BETWEEN</span>
                    <span className="rp-alloc-hint">recovered from each creator's next payout</span>
                  </div>
                  <div className="rp-alloc-rows">
                    {allocations.map((a, idx) => {
                      // A row at 0 is not an error, so it quiets rather than alarms: the name
                      // drops to --muted and one caption states the half the 0 does not, that
                      // nothing at all will be recorded against this creator.
                      const off = allocPct(a) < RECHARGE_MIN;
                      const name = creatorLabel(a.creatorId);
                      const offId = `rp-alloc-off-${a.creatorId}`;
                      return (
                      <div className={`rp-alloc-row${off ? ' is-off' : ''}`} key={a.creatorId}>
                        <div className="rp-alloc-who">
                          <span className="rp-alloc-name">{name}</span>
                          {off ? <span className="rp-alloc-off" id={offId}>not in this split</span> : null}
                        </div>
                        <div className="rp-alloc-pct">
                          <input
                            ref={idx === 0 ? firstFieldRef : null}
                            type="number"
                            className="form-input"
                            step="0.01"
                            min="0"
                            max="100"
                            value={a.pct}
                            onChange={(e) => setAllocPct(a.creatorId, e.target.value)}
                            disabled={submitting}
                            aria-label={`${name} percentage`}
                            aria-describedby={off ? offId : undefined}
                          />
                          <span className="rp-alloc-pct-sign">%</span>
                        </div>
                        <button
                          type="button"
                          className="rp-alloc-remove"
                          onClick={() => removeAlloc(a.creatorId)}
                          disabled={submitting || allocations.length <= 1}
                          aria-label={`Remove ${name}`}
                        >✕</button>
                      </div>
                      );
                    })}
                  </div>
                  <div className="rp-alloc-foot">
                    {addableCreators.length > 0 ? (
                      <select
                        className="form-select rp-alloc-add"
                        value=""
                        onChange={(e) => addAlloc(e.target.value)}
                        disabled={submitting}
                        aria-label="Add a creator to the split"
                      >
                        <option value="">+ Add creator</option>
                        {addableCreators.map((c) => (
                          <option key={c.id} value={c.id}>{c.creator_name || c.full_name || 'Creator'}</option>
                        ))}
                      </select>
                    ) : <span />}
                    <span className={`rp-alloc-total${allocValid ? ' is-ok' : ''}`}>
                      {allocTotal.toFixed(allocTotal % 1 === 0 ? 0 : 2)}%
                    </span>
                  </div>
                </div>
              ) : null}

              <div className="oop-modal-section-label" style={{ marginTop: 18 }}>{isMulti ? 'TOTAL' : 'AMOUNT'} · DATE</div>
              <div className="oop-form-grid">
                {!isMulti ? (
                  <div className="form-group" style={{ margin: 0 }}>
                    <MoneyInput
                      className="form-input"
                      min="0.01"
                      max={uncovered != null && uncovered > 0 ? uncovered.toFixed(2) : undefined}
                      value={amount}
                      onChange={(e) => onAmountTyped(e.target.value)}
                      disabled={submitting}
                      aria-label="Amount"
                    />
                    {amountClamped && (
                      <div className="form-hint" style={{ color: 'var(--orange2)' }}>
                        Capped at {fmtMoney(uncovered)}, which is all this expense still has
                        uncovered.
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="form-input" style={{ display: 'flex', alignItems: 'center', color: 'var(--white)', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                    {fmtMoney(multiTotal)} <span style={{ color: 'var(--muted)', fontWeight: 400, marginLeft: 8, fontSize: 11 }}>across {periods.length} periods</span>
                  </div>
                )}
                <div className="form-group" style={{ margin: 0 }}>
                  <input
                    type="date"
                    className="form-input"
                    min={DATE_MIN}
                    max={todayYMD()}
                    value={paidAt}
                    onChange={(e) => setPaidAt(e.target.value)}
                    disabled={submitting}
                    aria-label="Date paid"
                  />
                </div>
              </div>

              <button
                type="button"
                className="oop-notes-toggle"
                onClick={() => setShowNotes((v) => !v)}
                aria-expanded={showNotes}
              ><ChevronIcon size={11} style={{ transform: showNotes ? 'rotate(90deg)' : 'none', transition: 'transform 0.15s', marginRight: 6 }} />NOTES (optional)</button>
              {showNotes && (
                <div className="form-group" style={{ marginTop: 6 }}>
                  <textarea
                    className="form-textarea"
                    rows={3}
                    aria-label="Notes about this payment"
                    maxLength={NOTES_MAX}
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    disabled={submitting}
                    placeholder="Anything worth remembering about this payment."
                  />
                  <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4, textAlign: 'right' }}>
                    {notes.length}/{NOTES_MAX}
                  </div>
                </div>
              )}

              {!receipt ? (<>
                {/* A hit area, not a control: the click repeats what the button inside it does,
                    so the zone stays clickable and a drop target, and the button is the keyboard
                    route. The input sits outside, or its click() bubbles straight back in here. */}
                <div
                  className={`oop-drop-zone${dragOver ? ' is-over' : ''}`}
                  onClick={() => receiptInputRef.current.click()}
                  onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
                  onDragLeave={() => setDragOver(false)}
                  onDrop={(e) => { e.preventDefault(); setDragOver(false); const f = e.dataTransfer.files?.[0]; if (f) handleReceiptFile(f); }}
                >
                  Drop receipt here
                  <button type="button" className="btn btn-ghost btn-sm" disabled={submitting} onClick={(e) => { e.stopPropagation(); receiptInputRef.current.click(); }}>Attach a receipt</button>
                </div>
                <input aria-label="Receipt file" ref={receiptInputRef} type="file" accept={RECEIPT_FILE_ACCEPT} style={{ display: 'none' }}
                  onChange={(e) => { if (e.target.files?.[0]) handleReceiptFile(e.target.files[0]); e.target.value = ''; }} />
              </>) : (
                <div className="oop-drop-zone oop-drop-zone-attached">
                  <span title={`${receipt.name} · ${(receipt.size / 1024).toFixed(0)} KB`} style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                    <ReceiptIcon size={14} style={{ color: 'var(--muted)' }} /> {receipt.name} · {(receipt.size / 1024).toFixed(0)} KB
                  </span>
                  <button
                    type="button"
                    className="btn btn-ghost btn-sm"
                    onClick={() => setReceipt(null)}
                    style={{ color: 'var(--muted)' }}
                    aria-label="Remove receipt"
                  >✕</button>
                </div>
              )}

              {postsPreview ? (
                <div className="oop-posts-preview">{postsPreview}</div>
              ) : null}
            </>
          )}

          {error ? <Feedback value={error} style={{ marginTop: 12 }} onDismiss={() => setError(null)} /> : null}

          <OutstandingList items={outstanding} heading="Before you can record this" style={{ marginTop: 16 }} />
        </div>

        <div className="modal-footer">
          <ModalClose className="btn btn-ghost" disabled={submitting}>Cancel</ModalClose>
          <SubmitButton saving={submitting} className="btn btn-primary" onClick={handleSubmit} disabled={
              submitting || loading || outstanding.length > 0
            }>{isMulti ? `Save ${periods.length} entries` : 'Record payment'}</SubmitButton>
        </div>
    </Modal>
  );
}
