/**
 * components/shared/SplitBreakdown.js: what a payout split is CALLED, and the read-only card
 * list that renders it.
 *
 * `payout_splits` carries a three-way exactly-one over destination_id / expense_id /
 * recharge_allocation_id, so naming a split has to know all three. A namer that knows only two
 * prints "Unknown destination" for a recharge on the creator's own money screen.
 *
 * Two exports, because the call sites are not one layout: `splitLabel` is the naming rule, used
 * by the Rewards table cells as well as the cards, and `SplitBreakdown` is the card list. The
 * TITLE names the thing and the SUB-LINE names the kind.
 *
 * @invariant the kind partition comes from utils/payroll.js splitKind and is never re-derived
 *            here, so the money maths and these labels learn about a new type at once.
 * @gotcha the creator-facing word for an expense split is "gear", not "expense", and a recharge
 *         is a "Shared tool". MyMoneyPage calls the identical dollars the same thing.
 * @see docs/MONEY.md (Patterns F, G and R)
 */
import React from 'react';
import { splitKind } from '../../utils/payroll';
import { fmtDate, fmtMoney } from '../../utils/format';
import { SplitStatusBadge } from './StatusBadges';
import EmptyState from './EmptyState';

/** Free-text on an "Other" destination is a note, not a label; keep it to one line. */
const NOTE_MAX = 50;

/** "2026-06" -> "Jun 2026". Parses the parts explicitly (never new Date('YYYY-MM')). */
function monthLabel(period) {
  const [y, m] = String(period).split('-');
  if (!y || !m) return period;
  return new Date(parseInt(y, 10), parseInt(m, 10) - 1, 1)
    .toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
}

/**
 * What this split is called: a title and the sub-line under it.
 *
 * @param {object} split - a payout_splits row. Needs destination_id /
 *        expense_id / recharge_allocation_id to pick the kind, plus whichever
 *        embed that kind reads: `destination` for a destination split,
 *        `expense` for gear, `notes` for a recharge.
 * @returns {{title: string, subline: string}} subline is '' when there is none.
 *
 * @gotcha a recharge split embeds nothing. Its label is already written into
 *         `notes` by utils/oopPayments.js buildRechargeSplitRow as
 *         "Recharge: Coupler.io (2026-06)", so the prefix is stripped and the
 *         rest used verbatim. Do NOT parse the parenthetical apart: one live
 *         label reads "Stripe - Custom Domain -" and a
 *         second parser would be a second thing to get wrong.
 * @gotcha the "Unknown destination" fallback is reachable only when a new split
 *         type is added without teaching splitKind about it, which is exactly
 *         when it must be loud. It is never the empty-value placeholder: the
 *         row carries a real amount whose purpose is unrecognised.
 */
export function splitLabel(split) {
  const kind = splitKind(split);

  if (kind === 'recharge') {
    const label = String(split.notes || '').replace(/^Recharge:\s*/, '').trim();
    return { title: label || 'Shared tool', subline: 'Shared tool' };
  }

  if (kind === 'gear') {
    const exp = split.expense;
    const cadence = exp?.type === 'recurring' ? exp.frequency : 'one-time';
    const period = split.expense_period ? ` · ${monthLabel(split.expense_period)}` : '';
    return { title: exp?.name || 'Gear', subline: `Gear · ${cadence}${period}` };
  }

  // Every destination kind (wages, deferred, reimbursement) is named by its
  // destination; only the money maths tells them apart, not the label.
  const dest = split.destination;
  if (dest?.account_type === 'Other') {
    const note = String(split.notes || '');
    return {
      title: dest.name || 'Unknown destination',
      subline: note ? note.slice(0, NOTE_MAX) + (note.length > NOTE_MAX ? '…' : '') : 'Other',
    };
  }
  return {
    title: dest?.name || 'Unknown destination',
    subline: [dest?.account_type, dest?.account_last4 ? `···${dest.account_last4}` : null, dest?.institution]
      .filter(Boolean).join(' · '),
  };
}

/**
 * The read-only per-split card list, plus its total when there is more than one.
 *
 * @param {object} props
 * @param {object[]} props.splits - payout_splits rows, already fetched. Every
 *        caller must select `percentage` along with the label fields.
 * @param {string} [props.emptyText] - shown instead of the list when there are
 *        no splits. Omit on a surface that renders nothing at all in that case.
 */
export default function SplitBreakdown({ splits, emptyText }) {
  const rows = splits || [];
  if (rows.length === 0) {
    return emptyText ? <EmptyState variant="note" text={emptyText} /> : null;
  }

  return (
    <>
      {rows.map((s, i) => {
        const { title, subline } = splitLabel(s);
        return (
          <div key={s.id || i} style={{ background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 6, padding: '14px 16px', marginBottom: 10 }}>
            <div className="flex items-center justify-between mb-10">
              <div>
                <div style={{ fontWeight: 600, fontSize: 14 }}>{title}</div>
                {subline && <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 2 }}>{subline}</div>}
              </div>
              <SplitStatusBadge statusId={s.split_status_id} status={s.split_status} />
            </div>
            <div className="detail-grid">
              <div>
                <div className="detail-item-label">Percentage</div>
                <div className="detail-item-value">{s.percentage}%</div>
              </div>
              <div>
                <div className="detail-item-label">Amount</div>
                <div className="detail-item-value" style={{ fontWeight: 700, color: 'var(--blue)', fontSize: 16 }}>{fmtMoney(s.amount)}</div>
              </div>
              {s.sent_date && (
                <div>
                  <div className="detail-item-label">Sent</div>
                  <div className="detail-item-value">{fmtDate(s.sent_date)}</div>
                </div>
              )}
              {s.cleared_date && (
                <div>
                  <div className="detail-item-label">Cleared</div>
                  <div className="detail-item-value" style={{ color: 'var(--green)' }}>✓ {fmtDate(s.cleared_date)}</div>
                </div>
              )}
              {s.reference && (
                <div style={{ gridColumn: 'span 2' }}>
                  <div className="detail-item-label">Reference</div>
                  <div className="detail-item-value font-mono text-sm">{s.reference}</div>
                </div>
              )}
            </div>
          </div>
        );
      })}
      {rows.length > 1 && (
        <div style={{ display: 'flex', justifyContent: 'flex-end', fontSize: 13, color: 'var(--muted)', marginTop: 8, gap: 12 }}>
          <span>Total across {rows.length} destinations:</span>
          <span style={{ fontWeight: 700, color: 'var(--blue)' }}>{fmtMoney(rows.reduce((t, sp) => t + (sp.amount || 0), 0))}</span>
        </div>
      )}
    </>
  );
}
